
do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'missing-delays';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('missing-delays', 'data_analyst', 'The Missing Delays', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'data_analyst', title = 'The Missing Delays', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"missing-delays","roleKey":"data_analyst","title":"The Missing Delays","tagline":"A dashboard says zero delayed revenue. The service team says that''s wrong.","mission":"The operations dashboard says there is no delayed revenue today, but the customer service team says two delayed orders are missing. Identify the problem, calculate the correct delayed revenue and explain the fix.","companyName":"Harborline Retail","durationMinutes":5,"resources":[{"id":"orders","title":"orders.csv","kind":"table","content":"| Order ID | Revenue | Status |\n| --- | ---: | --- |\n| A-101 | 1200 | Shipped |\n| A-102 | 800 | Processing |\n| A-103 | 500 | Processing |\n| A-104 | 1000 | Shipped |"},{"id":"manual_delays","title":"manual_delays.csv","kind":"table","content":"| Order ID | Delay reason |\n| --- | --- |\n| A102 | Carrier capacity |\n| A103 | Weather |"},{"id":"metric_definition","title":"Metric definition","kind":"markdown","content":"## Delayed revenue\n\nDelayed revenue is the total revenue for orders appearing in the manual delay file.\n\nThe dashboard joins `orders.csv` to `manual_delays.csv` on **Order ID** and sums Revenue for matched rows."}],"stakeholders":[{"id":"dana","name":"Dana Whitfield","role":"Operations Manager","blurb":"Owns the operations dashboard. Needs a number leadership can trust.","knowledge":["Some teams enter order IDs with hyphens and some do not.","Leadership needs the corrected delayed-revenue number and a prevention recommendation."],"withholds":["Will not state the root cause or the corrected number."],"responseRules":[{"id":"rel_hyphens","priority":3,"anyKeywords":["hyphen","dash","format","id format","a-102","a102","spelling","match","join"],"reply":"They should not be. Some teams enter order IDs with hyphens and some do not."},{"id":"rel_leadership","priority":2,"anyKeywords":["leadership","need","expect","deliver","report","want"],"reply":"The corrected delayed-revenue number and a recommendation that prevents this tomorrow."}],"fallbackReply":"I only know that the service team can see two delayed orders that the dashboard is missing."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is the most likely cause of the missing delayed orders?","options":["Revenue values are incorrect","Order statuses are incorrect","Order IDs use inconsistent formatting","The dashboard refresh is too slow"],"points":30,"answer":["Order IDs use inconsistent formatting"],"competencyKey":"problem_diagnosis","expectedEvidence":"orders.csv uses A-102 / A-103 while manual_delays.csv uses A102 / A103, so the join on Order ID finds no matches."},{"id":"corrected_value","kind":"number","prompt":"What is the corrected delayed revenue in dollars?","helpText":"Enter the number only, e.g. 1500","points":25,"answer":[1300,0.5],"competencyKey":"analytical_correctness","expectedEvidence":"A-102 ($800) + A-103 ($500) = $1,300."},{"id":"supporting_orders","kind":"multi_select","prompt":"Which orders support the corrected number?","options":["A-101","A-102","A-103","A-104"],"points":15,"answer":["A-102","A-103"],"competencyKey":"evidence_selection","expectedEvidence":"A-102 and A-103 appear in the manual delay file (as A102 and A103)."},{"id":"recommendation","kind":"text","prompt":"Write a recommendation that prevents this tomorrow.","helpText":"Max 400 characters. What should change in the pipeline?","maxChars":400,"points":20,"concepts":[{"id":"normalize_ids","label":"Normalize IDs before joining","keywords":["normaliz","standardiz","clean","strip","consistent format","same format"]},{"id":"remove_hyphens","label":"Remove or standardize hyphens","keywords":["hyphen","dash","remove -","strip -"]},{"id":"validate_match","label":"Validate the match rate","keywords":["match rate","validate","check match","unmatched","reconcil","verify"]},{"id":"alert_unmatched","label":"Alert or test for unmatched records","keywords":["alert","test","monitor","flag","warn","fail the job"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Normalize order IDs (strip hyphens) in both sources before joining, validate the match rate, and alert on unmatched delay records so silent drops can''t recur."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"evidence_selection","label":"Evidence selection"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Correctly identified inconsistent ID formatting as the cause of the missing records.","corrected_value":"Calculated the corrected delayed revenue of $1,300 from the source data.","supporting_orders":"Selected exactly the two orders that support the corrected number.","recommendation":"The recommendation addresses the join defect rather than just the symptom."},"improvementTemplates":{"root_cause":"The root cause was inconsistent order ID formatting between the two files: the dashboard''s join found no matches.","corrected_value":"The corrected delayed revenue is $1,300 (A-102 at $800 plus A-103 at $500).","supporting_orders":"The supporting records are A-102 and A-103, listed without hyphens in the delay file.","recommendation":"A stronger recommendation would normalize IDs before joining and add a check for unmatched delay records so this cannot silently recur."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"missing-delays","roleKey":"data_analyst","title":"The Missing Delays","tagline":"A dashboard says zero delayed revenue. The service team says that''s wrong.","mission":"The operations dashboard says there is no delayed revenue today, but the customer service team says two delayed orders are missing. Identify the problem, calculate the correct delayed revenue and explain the fix.","companyName":"Harborline Retail","durationMinutes":5,"resources":[{"id":"orders","title":"orders.csv","kind":"table","content":"| Order ID | Revenue | Status |\n| --- | ---: | --- |\n| A-101 | 1200 | Shipped |\n| A-102 | 800 | Processing |\n| A-103 | 500 | Processing |\n| A-104 | 1000 | Shipped |"},{"id":"manual_delays","title":"manual_delays.csv","kind":"table","content":"| Order ID | Delay reason |\n| --- | --- |\n| A102 | Carrier capacity |\n| A103 | Weather |"},{"id":"metric_definition","title":"Metric definition","kind":"markdown","content":"## Delayed revenue\n\nDelayed revenue is the total revenue for orders appearing in the manual delay file.\n\nThe dashboard joins `orders.csv` to `manual_delays.csv` on **Order ID** and sums Revenue for matched rows."}],"stakeholders":[{"id":"dana","name":"Dana Whitfield","role":"Operations Manager","blurb":"Owns the operations dashboard. Needs a number leadership can trust.","knowledge":["Some teams enter order IDs with hyphens and some do not.","Leadership needs the corrected delayed-revenue number and a prevention recommendation."],"withholds":["Will not state the root cause or the corrected number."],"responseRules":[{"id":"rel_hyphens","priority":3,"anyKeywords":["hyphen","dash","format","id format","a-102","a102","spelling","match","join"],"reply":"They should not be. Some teams enter order IDs with hyphens and some do not."},{"id":"rel_leadership","priority":2,"anyKeywords":["leadership","need","expect","deliver","report","want"],"reply":"The corrected delayed-revenue number and a recommendation that prevents this tomorrow."}],"fallbackReply":"I only know that the service team can see two delayed orders that the dashboard is missing."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is the most likely cause of the missing delayed orders?","options":["Revenue values are incorrect","Order statuses are incorrect","Order IDs use inconsistent formatting","The dashboard refresh is too slow"],"points":30,"answer":["Order IDs use inconsistent formatting"],"competencyKey":"problem_diagnosis","expectedEvidence":"orders.csv uses A-102 / A-103 while manual_delays.csv uses A102 / A103, so the join on Order ID finds no matches."},{"id":"corrected_value","kind":"number","prompt":"What is the corrected delayed revenue in dollars?","helpText":"Enter the number only, e.g. 1500","points":25,"answer":[1300,0.5],"competencyKey":"analytical_correctness","expectedEvidence":"A-102 ($800) + A-103 ($500) = $1,300."},{"id":"supporting_orders","kind":"multi_select","prompt":"Which orders support the corrected number?","options":["A-101","A-102","A-103","A-104"],"points":15,"answer":["A-102","A-103"],"competencyKey":"evidence_selection","expectedEvidence":"A-102 and A-103 appear in the manual delay file (as A102 and A103)."},{"id":"recommendation","kind":"text","prompt":"Write a recommendation that prevents this tomorrow.","helpText":"Max 400 characters. What should change in the pipeline?","maxChars":400,"points":20,"concepts":[{"id":"normalize_ids","label":"Normalize IDs before joining","keywords":["normaliz","standardiz","clean","strip","consistent format","same format"]},{"id":"remove_hyphens","label":"Remove or standardize hyphens","keywords":["hyphen","dash","remove -","strip -"]},{"id":"validate_match","label":"Validate the match rate","keywords":["match rate","validate","check match","unmatched","reconcil","verify"]},{"id":"alert_unmatched","label":"Alert or test for unmatched records","keywords":["alert","test","monitor","flag","warn","fail the job"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Normalize order IDs (strip hyphens) in both sources before joining, validate the match rate, and alert on unmatched delay records so silent drops can''t recur."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"evidence_selection","label":"Evidence selection"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Correctly identified inconsistent ID formatting as the cause of the missing records.","corrected_value":"Calculated the corrected delayed revenue of $1,300 from the source data.","supporting_orders":"Selected exactly the two orders that support the corrected number.","recommendation":"The recommendation addresses the join defect rather than just the symptom."},"improvementTemplates":{"root_cause":"The root cause was inconsistent order ID formatting between the two files: the dashboard''s join found no matches.","corrected_value":"The corrected delayed revenue is $1,300 (A-102 at $800 plus A-103 at $500).","supporting_orders":"The supporting records are A-102 and A-103, listed without hyphens in the delay file.","recommendation":"A stronger recommendation would normalize IDs before joining and add a check for unmatched delay records so this cannot silently recur."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'duplicate-revenue';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('duplicate-revenue', 'data_analyst', 'Duplicate Revenue', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'data_analyst', title = 'Duplicate Revenue', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"duplicate-revenue","roleKey":"data_analyst","title":"Duplicate Revenue","tagline":"The revenue dashboard says $3,300. The invoice team says that is too high.","mission":"The revenue dashboard shows $3,300 for the week, but the invoice team insists their invoices only add up to $2,500. Find out why the dashboard is overstating revenue, compute the correct total and recommend a fix.","companyName":"Brightwell Supply","durationMinutes":5,"resources":[{"id":"invoices","title":"invoices.csv","kind":"table","content":"| Invoice ID | Amount | Customer |\n| --- | ---: | --- |\n| INV-1 | 1200 | Acme Tools |\n| INV-2 | 800 | Bolt Ltd |\n| INV-3 | 500 | Corvus Co |"},{"id":"payment_events","title":"payment_events.csv","kind":"table","content":"| Event ID | Invoice ID | Event type |\n| --- | --- | --- |\n| PE-1 | INV-1 | card_charge |\n| PE-2 | INV-2 | card_charge |\n| PE-3 | INV-2 | card_retry |\n| PE-4 | INV-3 | card_charge |"},{"id":"dashboard_query","title":"How the dashboard computes revenue","kind":"markdown","content":"## Dashboard query\n\nThe dashboard joins `invoices.csv` to `payment_events.csv` on **Invoice ID** and sums invoice Amount for every matched row.\n\nDisplayed total this week: **$3,300**."}],"stakeholders":[{"id":"priya","name":"Priya Raman","role":"Finance Manager","blurb":"Owns weekly revenue reporting. Needs a number she can defend.","knowledge":["INV-2''s first card charge failed and the system retried it, so INV-2 has two payment events.","The invoice table is the source of truth: one row per invoice, one amount per row.","Leadership needs the corrected total and a prevention step today."],"withholds":["Will not state the corrected total or name the join defect."],"responseRules":[{"id":"rel_retry","priority":3,"anyKeywords":["retry","twice","two events","duplicate","failed","second charge","multiple payment","inv-2","inv2"],"reply":"INV-2''s first card charge failed and the system retried it. Both attempts were logged as separate payment events."},{"id":"rel_source","priority":2,"anyKeywords":["source of truth","invoice table","which table","trust","true revenue","correct amount"],"reply":"The invoice table is our source of truth. One row per invoice, one amount per row."},{"id":"rel_need","priority":1,"anyKeywords":["need","deliver","leadership","report","expect","want"],"reply":"A corrected revenue number and a change that keeps this from happening again next month."}],"fallbackReply":"All I can tell you is the invoice team swears their totals are right, and the dashboard number is higher than theirs."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why is the dashboard overstating revenue?","options":["A one-to-many join duplicates invoice revenue","Invoice amounts were entered twice in the invoice table","A currency conversion doubled INV-2","The dashboard cache is stale"],"points":30,"answer":["A one-to-many join duplicates invoice revenue"],"competencyKey":"problem_diagnosis","expectedEvidence":"INV-2 has two payment events (PE-2 and PE-3). Joining invoices to payment events produces two rows for INV-2, so its $800 is counted twice."},{"id":"corrected_total","kind":"number","prompt":"What is the corrected total revenue in dollars?","helpText":"Enter the number only, e.g. 1500","points":25,"answer":[2500,0.5],"competencyKey":"analytical_correctness","expectedEvidence":"INV-1 ($1,200) + INV-2 ($800) + INV-3 ($500) = $2,500."},{"id":"duplicated_invoice","kind":"multi_select","prompt":"Which invoice is being double counted?","options":["INV-1","INV-2","INV-3"],"points":15,"answer":["INV-2"],"competencyKey":"evidence_selection","expectedEvidence":"INV-2 appears twice in payment_events.csv (a charge and a retry), so it is the only duplicated invoice."},{"id":"recommendation","kind":"text","prompt":"Recommend a fix so payment retries never inflate revenue again.","helpText":"Max 400 characters. What should change in the query or pipeline?","maxChars":400,"points":20,"concepts":[{"id":"aggregate_before_join","label":"Aggregate payment events before joining","keywords":["aggregate","group by","one row per invoice","sum payments first","collapse"]},{"id":"dedupe_by_invoice","label":"Deduplicate by invoice id","keywords":["dedup","distinct","unique invoice","one event per invoice"]},{"id":"row_count_check","label":"Add a row-count check","keywords":["row count","count check","same number of rows","row-count","count of invoices"]},{"id":"reconcile_source","label":"Reconcile totals against the source","keywords":["reconcil","compare to source","tie out","match the invoice total","invoice table total"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Aggregate payment events to one row per invoice before joining, or select distinct invoice ids. Add a row-count check on the joined output and reconcile the dashboard total against the invoice table."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"evidence_selection","label":"Evidence selection"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Correctly identified the one-to-many join as the source of the inflated total.","corrected_total":"Calculated the corrected revenue of $2,500 from the invoice table.","duplicated_invoice":"Pinpointed INV-2 as the only invoice counted twice.","recommendation":"The recommendation fixes the join itself and adds a check so the defect cannot return silently."},"improvementTemplates":{"root_cause":"The root cause is a one-to-many join. INV-2 has two payment events, so its revenue is summed twice.","corrected_total":"The corrected total is $2,500: INV-1 at $1,200 plus INV-2 at $800 plus INV-3 at $500.","duplicated_invoice":"INV-2 is the duplicated invoice. It appears twice in the payment events file.","recommendation":"A stronger fix aggregates payment events to one row per invoice before joining and adds a row-count check against the invoice table."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"duplicate-revenue","roleKey":"data_analyst","title":"Duplicate Revenue","tagline":"The revenue dashboard says $3,300. The invoice team says that is too high.","mission":"The revenue dashboard shows $3,300 for the week, but the invoice team insists their invoices only add up to $2,500. Find out why the dashboard is overstating revenue, compute the correct total and recommend a fix.","companyName":"Brightwell Supply","durationMinutes":5,"resources":[{"id":"invoices","title":"invoices.csv","kind":"table","content":"| Invoice ID | Amount | Customer |\n| --- | ---: | --- |\n| INV-1 | 1200 | Acme Tools |\n| INV-2 | 800 | Bolt Ltd |\n| INV-3 | 500 | Corvus Co |"},{"id":"payment_events","title":"payment_events.csv","kind":"table","content":"| Event ID | Invoice ID | Event type |\n| --- | --- | --- |\n| PE-1 | INV-1 | card_charge |\n| PE-2 | INV-2 | card_charge |\n| PE-3 | INV-2 | card_retry |\n| PE-4 | INV-3 | card_charge |"},{"id":"dashboard_query","title":"How the dashboard computes revenue","kind":"markdown","content":"## Dashboard query\n\nThe dashboard joins `invoices.csv` to `payment_events.csv` on **Invoice ID** and sums invoice Amount for every matched row.\n\nDisplayed total this week: **$3,300**."}],"stakeholders":[{"id":"priya","name":"Priya Raman","role":"Finance Manager","blurb":"Owns weekly revenue reporting. Needs a number she can defend.","knowledge":["INV-2''s first card charge failed and the system retried it, so INV-2 has two payment events.","The invoice table is the source of truth: one row per invoice, one amount per row.","Leadership needs the corrected total and a prevention step today."],"withholds":["Will not state the corrected total or name the join defect."],"responseRules":[{"id":"rel_retry","priority":3,"anyKeywords":["retry","twice","two events","duplicate","failed","second charge","multiple payment","inv-2","inv2"],"reply":"INV-2''s first card charge failed and the system retried it. Both attempts were logged as separate payment events."},{"id":"rel_source","priority":2,"anyKeywords":["source of truth","invoice table","which table","trust","true revenue","correct amount"],"reply":"The invoice table is our source of truth. One row per invoice, one amount per row."},{"id":"rel_need","priority":1,"anyKeywords":["need","deliver","leadership","report","expect","want"],"reply":"A corrected revenue number and a change that keeps this from happening again next month."}],"fallbackReply":"All I can tell you is the invoice team swears their totals are right, and the dashboard number is higher than theirs."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why is the dashboard overstating revenue?","options":["A one-to-many join duplicates invoice revenue","Invoice amounts were entered twice in the invoice table","A currency conversion doubled INV-2","The dashboard cache is stale"],"points":30,"answer":["A one-to-many join duplicates invoice revenue"],"competencyKey":"problem_diagnosis","expectedEvidence":"INV-2 has two payment events (PE-2 and PE-3). Joining invoices to payment events produces two rows for INV-2, so its $800 is counted twice."},{"id":"corrected_total","kind":"number","prompt":"What is the corrected total revenue in dollars?","helpText":"Enter the number only, e.g. 1500","points":25,"answer":[2500,0.5],"competencyKey":"analytical_correctness","expectedEvidence":"INV-1 ($1,200) + INV-2 ($800) + INV-3 ($500) = $2,500."},{"id":"duplicated_invoice","kind":"multi_select","prompt":"Which invoice is being double counted?","options":["INV-1","INV-2","INV-3"],"points":15,"answer":["INV-2"],"competencyKey":"evidence_selection","expectedEvidence":"INV-2 appears twice in payment_events.csv (a charge and a retry), so it is the only duplicated invoice."},{"id":"recommendation","kind":"text","prompt":"Recommend a fix so payment retries never inflate revenue again.","helpText":"Max 400 characters. What should change in the query or pipeline?","maxChars":400,"points":20,"concepts":[{"id":"aggregate_before_join","label":"Aggregate payment events before joining","keywords":["aggregate","group by","one row per invoice","sum payments first","collapse"]},{"id":"dedupe_by_invoice","label":"Deduplicate by invoice id","keywords":["dedup","distinct","unique invoice","one event per invoice"]},{"id":"row_count_check","label":"Add a row-count check","keywords":["row count","count check","same number of rows","row-count","count of invoices"]},{"id":"reconcile_source","label":"Reconcile totals against the source","keywords":["reconcil","compare to source","tie out","match the invoice total","invoice table total"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Aggregate payment events to one row per invoice before joining, or select distinct invoice ids. Add a row-count check on the joined output and reconcile the dashboard total against the invoice table."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"evidence_selection","label":"Evidence selection"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Correctly identified the one-to-many join as the source of the inflated total.","corrected_total":"Calculated the corrected revenue of $2,500 from the invoice table.","duplicated_invoice":"Pinpointed INV-2 as the only invoice counted twice.","recommendation":"The recommendation fixes the join itself and adds a check so the defect cannot return silently."},"improvementTemplates":{"root_cause":"The root cause is a one-to-many join. INV-2 has two payment events, so its revenue is summed twice.","corrected_total":"The corrected total is $2,500: INV-1 at $1,200 plus INV-2 at $800 plus INV-3 at $500.","duplicated_invoice":"INV-2 is the duplicated invoice. It appears twice in the payment events file.","recommendation":"A stronger fix aggregates payment events to one row per invoice before joining and adds a row-count check against the invoice table."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'broken-funnel';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('broken-funnel', 'data_analyst', 'The Broken Funnel', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'data_analyst', title = 'The Broken Funnel', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"broken-funnel","roleKey":"data_analyst","title":"The Broken Funnel","tagline":"Marketing says activation is 8%. Product says 40%. Both pull the same data.","mission":"Marketing reported 8% activation in the monthly review. Product reported 40% for the same month. Both teams pulled from the same funnel data. Explain why the numbers differ and propose naming that keeps both metrics useful.","companyName":"Fernwood Labs","durationMinutes":5,"resources":[{"id":"funnel","title":"Monthly funnel","kind":"table","content":"| Stage | Count |\n| --- | ---: |\n| Visitors | 1000 |\n| Signups | 200 |\n| Activated | 80 |"},{"id":"definitions","title":"How each team defines activation rate","kind":"markdown","content":"## Marketing\n\n`Activated / Visitors`\n\nReported: **80 / 1000 = 8%**\n\n## Product\n\n`Activated / Signups`\n\nReported: **80 / 200 = 40%**"}],"stakeholders":[{"id":"talia","name":"Talia Brooks","role":"Head of Growth","blurb":"Runs the monthly review. Wants the argument between teams to end.","knowledge":["Marketing measures from first visit because they own the whole funnel starting at the ad click.","Product measures from signup because they own onboarding.","Both numbers come from the same event stream."],"withholds":["Will not say which number is correct."],"responseRules":[{"id":"rel_marketing","priority":3,"anyKeywords":["marketing","8%","8 percent","visitor","whole funnel","ad click","top of funnel"],"reply":"Marketing measures from first visit. They care about the whole funnel starting at the ad click."},{"id":"rel_product","priority":2,"anyKeywords":["product","40","signup","after sign","onboarding","account created"],"reply":"Product measures from signup. They own onboarding, so they start counting once someone creates an account."},{"id":"rel_data","priority":1,"anyKeywords":["same data","source","event","pull from","pipeline","broken data"],"reply":"Both numbers come from the same event stream. Nobody''s data is broken."}],"fallbackReply":"Both teams are sure their number is right. Figure out how that can be true at the same time."}],"questions":[{"id":"why_disagree","kind":"single_select","prompt":"Why do the two activation rates disagree?","options":["The two metrics use different denominators","Marketing''s data is a month behind","Product is excluding mobile users","The activation event fires twice for some users"],"points":30,"answer":["The two metrics use different denominators"],"competencyKey":"metric_reasoning","expectedEvidence":"Both teams count 80 activated users. Marketing divides by 1,000 visitors while Product divides by 200 signups. Same numerator, different denominator."},{"id":"signup_rate","kind":"number","prompt":"What percent of signups activated?","helpText":"Enter the percent as a number only, e.g. 25","points":25,"answer":[40,0.5],"competencyKey":"analytical_correctness","expectedEvidence":"80 activated / 200 signups = 40%."},{"id":"which_correct","kind":"single_select","prompt":"Which number answers \"of the people who signed up, how many activated?\"","options":["8%","20%","40%","80%"],"points":15,"answer":["40%"],"competencyKey":"business_interpretation","expectedEvidence":"That question starts the count at signup, so the denominator is 200 signups and the answer is 40%."},{"id":"labeling","kind":"text","prompt":"Propose how to label the two metrics so both stay useful.","helpText":"Max 400 characters. Both teams should keep a metric they can use.","maxChars":400,"points":20,"concepts":[{"id":"name_denominator","label":"Put the denominator in the metric name","keywords":["denominator","in the name","rename","name the metric","name says"]},{"id":"keep_both","label":"Keep both metrics","keywords":["keep both","both metrics","both are useful","both stay","not replace"]},{"id":"distinct_names","label":"Visitor-to-activation vs signup-to-activation","keywords":["visitor-to-activation","signup-to-activation",