do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'refund-spike';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('refund-spike', 'data_analyst', 'The Refund Spike', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'data_analyst', title = 'The Refund Spike', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
