    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"refund-spike","roleKey":"data_analyst","title":"The Refund Spike","tagline":"Refunds jumped this week. Customers may have nothing to do with it.","mission":"The weekly refund dashboard shows $3,150, well above the usual range. Finance is worried about a customer problem. Find out what is actually inflating the number, compute the real refund total and recommend a durable fix.","companyName":"Kestrel Goods","durationMinutes":5,"resources":[{"id":"refunds","title":"refunds.csv (this week)","kind":"table","content":"| Refund ID | Account ID | Amount |\n| --- | --- | ---: |\n| R-1 | A-1 | 500 |\n| R-2 | A-2 | 650 |\n| R-3 | A-3 | 400 |\n| R-4 | A-4 | 850 |\n| R-5 | A-5 | 350 |\n| R-6 | A-6 | 400 |"},{"id":"accounts","title":"accounts.csv","kind":"table","content":"| Account ID | is_test |\n| --- | --- |\n| A-1 | false |\n| A-2 | false |\n| A-3 | true |\n| A-4 | false |\n| A-5 | true |\n| A-6 | false |"},{"id":"context","title":"Reporting context","kind":"markdown","content":"## Weekly refund review\n\nFinance reviews refunds every week and reports the total to the CFO. A normal week lands between $2,300 and $2,500.\n\nThe refund dashboard sums every row in `refunds.csv`. Displayed total this week: **$3,150**."}],"stakeholders":[{"id":"marcus","name":"Marcus Hale","role":"Finance Controller","blurb":"Reports the weekly refund total to the CFO. Hates surprises.","knowledge":["QA created internal accounts last month to test the refund flow. They are flagged in the accounts table.","A normal week lands between $2,300 and $2,500.","He needs the real total and a fix so the question never comes back."],"withholds":["Will not compute the production total or point at specific rows."],"responseRules":[{"id":"rel_test_accounts","priority":3,"anyKeywords":["test account","internal","qa","fake","flag","is_test","test data"],"reply":"QA set up a few internal accounts last month to test the refund flow. They are flagged in the accounts table."},{"id":"rel_baseline","priority":2,"anyKeywords":["normal","typical","usual","baseline","last week","spike","range"],"reply":"A normal week lands between $2,300 and $2,500. This week''s number is well above that."},{"id":"rel_need","priority":1,"anyKeywords":["need","report","cfo","deliver","want","expect"],"reply":"The real refund total for the week, and a fix so I never have to ask this question again."}],"fallbackReply":"The dashboard total looks too high to me, but I cannot tell you which rows are wrong."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is inflating the weekly refund total?","options":["Internal test accounts are included in the refund total","Customers are abusing the refund policy","A refund was recorded twice","The weekly date range includes an extra day"],"points":30,"answer":["Internal test accounts are included in the refund total"],"competencyKey":"problem_diagnosis","expectedEvidence":"Accounts A-3 and A-5 are flagged is_test = true in accounts.csv, and their refunds are included in the dashboard sum."},{"id":"production_total","kind":"number","prompt":"What is the production-only refund total in dollars?","helpText":"Enter the number only, e.g. 2000","points":25,"answer":[2400,0.5],"competencyKey":"analytical_correctness","expectedEvidence":"R-1 ($500) + R-2 ($650) + R-4 ($850) + R-6 ($400) = $2,400, back inside the normal range."},{"id":"test_rows","kind":"multi_select","prompt":"Which refund rows belong to test accounts?","options":["R-1","R-2","R-3","R-4","R-5","R-6"],"points":15,"answer":["R-3","R-5"],"competencyKey":"evidence_selection","expectedEvidence":"R-3 (account A-3) and R-5 (account A-5). Both accounts are flagged is_test = true."},{"id":"durable_fix","kind":"text","prompt":"Recommend a durable fix so test accounts never leak into finance reporting.","helpText":"Max 400 characters. Think beyond this week''s number.","maxChars":400,"points":20,"concepts":[{"id":"exclude_in_source","label":"Exclude flagged test accounts in the source query","keywords":["exclude","filter out","where is_test","source query","is_test = false"]},{"id":"classification_field","label":"Add an account classification field","keywords":["classification","account type","flag every account","classify accounts","label accounts"]},{"id":"backfill_reports","label":"Backfill historical reports","keywords":["backfill","historical","restate","past reports","prior weeks"]},{"id":"leakage_test","label":"Add a data test for test-account leakage","keywords":["data test","automated test","alert","leak","monitor","check for test accounts"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Exclude is_test accounts in the source query that feeds the dashboard, maintain an account classification field, backfill historical reports and add an automated data test that fails when a test account appears in finance data."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"evidence_selection","label":"Evidence selection"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Correctly identified test-account contamination instead of assuming a customer problem.","production_total":"Calculated the production-only total of $2,400, which falls back inside the normal range.","test_rows":"Selected exactly the two refund rows tied to flagged test accounts.","durable_fix":"The fix removes test data at the source and adds a test so leakage cannot recur silently."},"improvementTemplates":{"root_cause":"The spike comes from internal test accounts. A-3 and A-5 are flagged is_test = true and their refunds are in the total.","production_total":"The production-only total is $2,400: R-1, R-2, R-4 and R-6.","test_rows":"The test rows are R-3 (account A-3) and R-5 (account A-5).","durable_fix":"A stronger fix excludes flagged accounts in the source query, backfills history and adds an automated test for test-account leakage."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"refund-spike","roleKey":"data_analyst","title":"The Refund Spike","tagline":"Refunds jumped this week. Customers may have nothing to do with it.","mission":"The weekly refund dashboard shows $3,150, well above the usual range. Finance is worried about a customer problem. Find out what is actually inflating the number, compute the real refund total and recommend a durable fix.","companyName":"Kestrel Goods","durationMinutes":5,"resources":[{"id":"refunds","title":"refunds.csv (this week)","kind":"table","content":"| Refund ID | Account ID | Amount |\n| --- | --- | ---: |\n| R-1 | A-1 | 500 |\n| R-2 | A-2 | 650 |\n| R-3 | A-3 | 400 |\n| R-4 | A-4 | 850 |\n| R-5 | A-5 | 350 |\n| R-6 | A-6 | 400 |"},{"id":"accounts","title":"accounts.csv","kind":"table","content":"| Account ID | is_test |\n| --- | --- |\n| A-1 | false |\n| A-2 | false |\n| A-3 | true |\n| A-4 | false |\n| A-5 | true |\n| A-6 | false |"},{"id":"context","title":"Reporting context","kind":"markdown","content":"## Weekly refund review\n\nFinance reviews refunds every week and reports the total to the CFO. A normal week lands between $2,300 and $2,500.\n\nThe refund dashboard sums every row in `refunds.csv`. Displayed total this week: **$3,150**."}],"stakeholders":[{"id":"marcus","name":"Marcus Hale","role":"Finance Controller","blurb":"Reports the weekly refund total to the CFO. Hates surprises.","knowledge":["QA created internal accounts last month to test the refund flow. They are flagged in the accounts table.","A normal week lands between $2,300 and $2,500.","He needs the real total and a fix so the question never comes back."],"withholds":["Will not compute the production total or point at specific rows."],"responseRules":[{"id":"rel_test_accounts","priority":3,"anyKeywords":["test account","internal","qa","fake","flag","is_test","test data"],"reply":"QA set up a few internal accounts last month to test the refund flow. They are flagged in the accounts table."},{"id":"rel_baseline","priority":2,"anyKeywords":["normal","typical","usual","baseline","last week","spike","range"],"reply":"A normal week lands between $2,300 and $2,500. This week''s number is well above that."},{"id":"rel_need","priority":1,"anyKeywords":["need","report","cfo","deliver","want","expect"],"reply":"The real refund total for the week, and a fix so I never have to ask this question again."}],"fallbackReply":"The dashboard total looks too high to me, but I cannot tell you which rows are wrong."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is inflating the weekly refund total?","options":["Internal test accounts are included in the refund total","Customers are abusing the refund policy","A refund was recorded twice","The weekly date range includes an extra day"],"points":30,"answer":["Internal test accounts are included in the refund total"],"competencyKey":"problem_diagnosis","expectedEvidence":"Accounts A-3 and A-5 are flagged is_test = true in accounts.csv, and their refunds are included in the dashboard sum."},{"id":"production_total","kind":"number","prompt":"What is the production-only refund total in dollars?","helpText":"Enter the number only, e.g. 2000","points":25,"answer":[2400,0.5],"competencyKey":"analytical_correctness","expectedEvidence":"R-1 ($500) + R-2 ($650) + R-4 ($850) + R-6 ($400) = $2,400, back inside the normal range."},{"id":"test_rows","kind":"multi_select","prompt":"Which refund rows belong to test accounts?","options":["R-1","R-2","R-3","R-4","R-5","R-6"],"points":15,"answer":["R-3","R-5"],"competencyKey":"evidence_selection","expectedEvidence":"R-3 (account A-3) and R-5 (account A-5). Both accounts are flagged is_test = true."},{"id":"durable_fix","kind":"text","prompt":"Recommend a durable fix so test accounts never leak into finance reporting.","helpText":"Max 400 characters. Think beyond this week''s number.","maxChars":400,"points":20,"concepts":[{"id":"exclude_in_source","label":"Exclude flagged test accounts in the source query","keywords":["exclude","filter out","where is_test","source query","is_test = false"]},{"id":"classification_field","label":"Add an account classification field","keywords":["classification","account type","flag every account","classify accounts","label accounts"]},{"id":"backfill_reports","label":"Backfill historical reports","keywords":["backfill","historical","restate","past reports","prior weeks"]},{"id":"leakage_test","label":"Add a data test for test-account leakage","keywords":["data test","automated test","alert","leak","monitor","check for test accounts"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Exclude is_test accounts in the source query that feeds the dashboard, maintain an account classification field, backfill historical reports and add an automated data test that fails when a test account appears in finance data."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"evidence_selection","label":"Evidence selection"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Correctly identified test-account contamination instead of assuming a customer problem.","production_total":"Calculated the production-only total of $2,400, which falls back inside the normal range.","test_rows":"Selected exactly the two refund rows tied to flagged test accounts.","durable_fix":"The fix removes test data at the source and adds a test so leakage cannot recur silently."},"improvementTemplates":{"root_cause":"The spike comes from internal test accounts. A-3 and A-5 are flagged is_test = true and their refunds are in the total.","production_total":"The production-only total is $2,400: R-1, R-2, R-4 and R-6.","test_rows":"The test rows are R-3 (account A-3) and R-5 (account A-5).","durable_fix":"A stronger fix excludes flagged accounts in the source query, backfills history and adds an automated test for test-account leakage."}}'::jsonb,
      now()
    )
    returning id into v_id;
