do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'cohort-drift';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('cohort-drift', 'data_analyst', 'Cohort Drift', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'data_analyst', title = 'Cohort Drift', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"cohort-drift","roleKey":"data_analyst","title":"Cohort Drift","tagline":"Retention looks different on two dashboards. The customers did not change.","mission":"Two retention dashboards disagree for the same months. The old one groups customers by signup month and the new one groups by first-purchase month. Explain the disagreement, quantify how many customers move and recommend how the team should handle the two definitions.","companyName":"Alder & Vine","durationMinutes":5,"resources":[{"id":"customers","title":"customers.csv","kind":"table","content":"| Customer | Signup month | First purchase month |\n| --- | --- | --- |\n| C-1 | Jan | Jan |\n| C-2 | Jan | Feb |\n| C-3 | Feb | Feb |\n| C-4 | Feb | Feb |\n| C-5 | Mar | Mar |\n| C-6 | Feb | Mar |"},{"id":"definitions","title":"Dashboard definitions","kind":"markdown","content":"## Dashboard A (old)\n\nCohort = **signup month**. Retention = share of the cohort with a repeat purchase in a later month.\n\n## Dashboard B (new)\n\nCohort = **first-purchase month**. Same retention formula.\n\n## Leadership question\n\n\"Do customers keep buying after their first purchase?\""}],"stakeholders":[{"id":"nora","name":"Nora Okafor","role":"Retention Lead","blurb":"Presents retention monthly. Two dashboards are undermining her numbers.","knowledge":["The new dashboard was built for the merchandising team and groups by first-purchase month.","The old dashboard groups by signup month. Nothing else changed between them.","Leadership wants to know whether customers keep buying after their first purchase."],"withholds":["Will not say which definition is right or count the moving customers."],"responseRules":[{"id":"rel_question","priority":3,"anyKeywords":["leadership","question","trying to answer","goal","repeat","keep buying","care about"],"reply":"Leadership wants to know whether customers keep buying after their first purchase. That is the question the number needs to answer."},{"id":"rel_dashboards","priority":2,"anyKeywords":["two dashboard","which dashboard","new dashboard","old dashboard","definition","group","difference"],"reply":"The old dashboard groups customers by signup month. The new one groups by first-purchase month. Nothing else changed."}],"fallbackReply":"Retention did not really move that much in the business. Something about how we count must have changed."}],"questions":[{"id":"why_changed","kind":"single_select","prompt":"Why do the two dashboards report different retention?","options":["The cohort definition changed, so customers moved between cohorts","Customers actually churned faster this quarter","A pipeline bug dropped some customers","Seasonality shifted purchases between months"],"points":30,"answer":["The cohort definition changed, so customers moved between cohorts"],"competencyKey":"problem_diagnosis","expectedEvidence":"The dashboards use different cohort bases. Customers whose first purchase came after their signup month land in different cohorts on each dashboard."},{"id":"which_definition","kind":"single_select","prompt":"Which cohort definition answers \"do customers keep buying after their first purchase?\"","options":["Signup month","First-purchase month","Calendar quarter","Last-purchase month"],"points":25,"answer":["First-purchase month"],"competencyKey":"metric_reasoning","expectedEvidence":"The question starts the clock at the first purchase, so cohorts should be grouped by first-purchase month."},{"id":"movers","kind":"number","prompt":"How many customers move to a different cohort between the two definitions?","helpText":"Enter a whole number","points":15,"answer":[2,0],"competencyKey":"analytical_correctness","expectedEvidence":"C-2 (signup Jan, first purchase Feb) and C-6 (signup Feb, first purchase Mar). 2 customers."},{"id":"recommendation","kind":"text","prompt":"Recommend how the team should handle the two cohort definitions going forward.","helpText":"Max 