do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'filtered-forecast';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('filtered-forecast', 'bi_analyst', 'The Filtered Forecast', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'bi_analyst', title = 'The Filtered Forecast', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"filtered-forecast","roleKey":"bi_analyst","title":"The Filtered Forecast","tagline":"The executive forecast dropped overnight. No region actually changed.","mission":"The executive dashboard shows a $580k forecast and leadership is alarmed because they planned for more. The regional numbers all look fine to the regional teams. Find out why the displayed total is low, compute the correct total and recommend how to prevent this.","companyName":"Statler Instruments","durationMinutes":5,"resources":[{"id":"forecast","title":"Forecast by region","kind":"table","content":"| Region | Forecast ($ thousands) |\n| --- | ---: |\n| Americas | 410 |\n| EMEA | 220 |\n| APAC | 170 |"},{"id":"dashboard_state","title":"Dashboard state","kind":"markdown","content":"## Executive forecast view\n\nDisplayed total: **$580k**\n\nActive filter: **region is Americas, APAC**\n\nThe view was saved last quarter and is the one executives open by default. The total feeds Monday''s board deck."}],"stakeholders":[{"id":"sam","name":"Sam Porter","role":"Revenue Operations Lead","blurb":"Owns the executive dashboard. Needs the board number to be right by Monday.","knowledge":["A regional manager saved the filtered view last quarter for a team review, and executives have opened it ever since.","EMEA has not missed a forecast in two years.","The displayed total goes straight into Monday''s board deck."],"withholds":["Will not state the corrected total or name the filter as the cause."],"responseRules":[{"id":"rel_saved_view","priority":3,"anyKeywords":["filter","saved","view","who built","changed","setting","default"],"reply":"A regional manager saved that view last quarter for their own team review. Executives have been opening it ever since."},{"id":"rel_emea","priority":2,"anyKeywords":["emea","europe","missing region","region missing","which region","dropped"],"reply":"EMEA has not missed a forecast in two years. If the total looks low, I would not assume EMEA collapsed."},{"id":"rel_audience","priority":1,"anyKeywords":["board","exec","who sees","deck","meeting","monday"],"reply":"The number goes straight into Monday''s board deck. It has to be right and it has to be explainable."}],"fallbackReply":"The regional teams say their individual numbers look right. It is only the total that looks off."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why is the displayed forecast low?","options":["A saved region filter excludes EMEA from the total","EMEA missed its forecast this quarter","The forecast model dropped a region''s data","Currency conversion shrank the EMEA number"],"points":30,"answer":["A saved region filter excludes EMEA from the total"],"competencyKey":"problem_diagnosis","expectedEvidence":"The dashboard state shows an active filter of region is Americas, APAC. EMEA''s $220k is excluded, which explains the $580k display."},{"id":"corrected_total","kind":"number","prompt":"What is the corrected total forecast in $ thousands?","helpText":"Enter the number only, e.g. 750","points":25,"answer":[800,1],"competencyKey":"analytical_correctness","expectedEvidence":"Americas 410 + EMEA 220 + APAC 170 = 800 ($ thousands)."},{"id":"included_regions","kind":"multi_select","prompt":"Which regions does the displayed $580k include?","options":["Americas","EMEA","APAC"],"points":15,"answer":["Americas","APAC"],"competencyKey":"evidence_selection","expectedEvidence":"Americas (410) + APAC (170) = 580, matching the displayed total. EMEA is filtered out."},{"id":"prevention","kind":"text","prompt":"Recommend how to prevent a saved filter from distorting an executive number again.","helpText":"Max 400 characters. Focus on process and dashboard design.","maxChars":400,"points":20,"concepts":[{"id":"show_filter_state","label":"Show active filter state on the dashboard","keywords":["show the filter","display active filter","filter banner","visible filter","active filter"]},{"id":"default_unfiltered","label":"Default executive views to unfiltered","keywords":["default","unfiltered","no filter","reset","open clean"]},{"id":"review_saved_views","label":"Review saved views","keywords":["saved view","review view","audit","shared view","clean up views"]},{"id":"reconciliation_check","label":"Add a total reconciliation check","keywords":["reconcil","total check","sum of regions","control total","compare the total"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Show the active filter state prominently on the dashboard, default executive views to unfiltered, review saved views regularly and add a reconciliation check that compares the displayed total to the sum of all regions."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"evidence_selection","label":"Evidence selection"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Traced the low total to the saved region filter instead of a business decline.","corrected_total":"Calculated the corrected forecast of $800k across all three regions.","included_regions":"Verified that the displayed $580k is exactly Americas plus APAC.","prevention":"The prevention plan makes filter state visible and adds a check on the total itself."},"improvementTemplates":{"root_cause":"The cause is a saved filter: the view only includes Americas and APAC, so EMEA''s $220k is missing from the total.","corrected_total":"The corrected total is $800k: Americas 410 + EMEA 220 + APAC 170.","included_regions":"The displayed $580k includes only Americas ($410k) and APAC ($170k).","prevention":"A stronger plan shows the active filter on the dashboard, defaults executive views to unfiltered and reconciles the total against the sum of regions."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"filtered-forecast","roleKey":"bi_analyst","title":"The Filtered Forecast","tagline":"The executive forecast dropped overnight. No region actually changed.","mission":"The executive dashboard shows a $580k forecast and leadership is alarmed because they planned for more. The regional numbers all look fine to the regional teams. Find out why the displayed total is low, compute the correct total and recommend how to prevent this.","companyName":"Statler Instruments","durationMinutes":5,"resources":[{"id":"forecast","title":"Forecast by region","kind":"table","content":"| Region | Forecast ($ thousands) |\n| --- | ---: |\n| Americas | 410 |\n| EMEA | 220 |\n| APAC | 170 |"},{"id":"dashboard_state","title":"Dashboard state","kind":"markdown","content":"## Executive forecast view\n\nDisplayed total: **$580k**\n\nActive filter: **region is Americas, APAC**\n\nThe view was saved last quarter and is the one executives open by default. The total feeds Monday''s board deck."}],"stakeholders":[{"id":"sam","name":"Sam Porter","role":"Revenue Operations Lead","blurb":"Owns the executive dashboard. Needs the board number to be right by Monday.","knowledge":["A regional manager saved the filtered view last quarter for a team review, and executives have opened it ever since.","EMEA has not missed a forecast in two years.","The displayed total goes straight into Monday''s board deck."],"withholds":["Will not state the corrected total or name the filter as the cause."],"responseRules":[{"id":"rel_saved_view","priority":3,"anyKeywords":["filter","saved","view","who built","changed","setting","default"],"reply":"A regional manager saved that view last quarter for their own team review. Executives have been opening it ever since."},{"id":"rel_emea","priority":2,"anyKeywords":["emea","europe","missing region","region missing","which region","dropped"],"reply":"EMEA has not missed a forecast in two years. If the total looks low, I would not assume EMEA collapsed."},{"id":"rel_audience","priority":1,"anyKeywords":["board","exec","who sees","deck","meeting","monday"],"reply":"The number goes straight into Monday''s board deck. It has to be right and it has to be explainable."}],"fallbackReply":"The regional teams say their individual numbers look right. It is only the total that looks off."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why is the displayed forecast low?","options":["A saved region filter excludes EMEA from the total","EMEA missed its forecast this quarter","The forecast model dropped a region''s data","Currency conversion shrank the EMEA number"],"points":30,"answer":["A saved region filter excludes EMEA from the total"],"competencyKey":"problem_diagnosis","expectedEvidence":"The dashboard state shows an active filter of region is Americas, APAC. EMEA''s $220k is excluded, which explains the $580k display."},{"id":"corrected_total","kind":"number","prompt":"What is the corrected total forecast in $ thousands?","helpText":"Enter the number only, e.g. 750","points":25,"answer":[800,1],"competencyKey":"analytical_correctness","expectedEvidence":"Americas 410 + EMEA 220 + APAC 170 = 800 ($ thousands)."},{"id":"included_regions","kind":"multi_select","prompt":"Which regions does the displayed $580k include?","options":["Americas","EMEA","APAC"],"points":15,"answer":["Americas","APAC"],"competencyKey":"evidence_selection","expectedEvidence":"Americas (410) + APAC (170) = 580, matching the displayed total. EMEA is filtered out."},{"id":"prevention","kind":"text","prompt":"Recommend how to prevent a saved filter from distorting an executive number again.","helpText":"Max 400 characters. Focus on process and dashboard design.","maxChars":400,"points":20,"concepts":[{"id":"show_filter_state","label":"Show active filter state on the dashboard","keywords":["show the filter","display active filter","filter banner","visible filter","active filter"]},{"id":"default_unfiltered","label":"Default executive views to unfiltered","keywords":["default","unfiltered","no filter","reset","open clean"]},{"id":"review_saved_views","label":"Review saved views","keywords":["saved view","review view","audit","shared view","clean up views"]},{"id":"reconciliation_check","label":"Add a total reconciliation check","keywords":["reconcil","total check","sum of regions","control total","compare the total"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Show the active filter state prominently on the dashboard, default executive views to unfiltered, review saved views regularly and add a reconciliation check that compares the displayed total to the sum of all regions."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"evidence_selection","label":"Evidence selection"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Traced the low total to the saved region filter instead of a business decline.","corrected_total":"Calculated the corrected forecast of $800k across all three regions.","included_regions":"Verified that the displayed $580k is exactly Americas plus APAC.","prevention":"The prevention plan makes filter state visible and adds a check on the total itself."},"improvementTemplates":{"root_cause":"The cause is a saved filter: the view only includes Americas and APAC, so EMEA''s $220k is missing from the total.","corrected_total":"The corrected total is $800k: Americas 410 + EMEA 220 + APAC 170.","included_regions":"The displayed $580k includes only Americas ($410k) and APAC ($170k).","prevention":"A stronger plan shows the active filter on the dashboard, defaults executive views to unfiltered and reconciles the total against the sum of regions."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

