  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"currency-confusion","roleKey":"bi_analyst","title":"Currency Confusion","tagline":"The regional dashboard adds dollars, euros and pounds like they are the same thing.","mission":"The regional revenue dashboard shows a 600 total by adding the raw regional numbers, but the regions report in three different currencies. Diagnose the problem, compute the correct USD total and recommend how currency should be handled in reporting.","companyName":"Ostara Goods","durationMinutes":5,"resources":[{"id":"revenue","title":"Quarterly revenue by region","kind":"table","content":"| Region | Revenue (thousands) | Currency |\n| --- | ---: | --- |\n| US | 300 | USD |\n| Germany | 200 | EUR |\n| UK | 100 | GBP |"},{"id":"rates","title":"Exchange rates","kind":"markdown","content":"## Treasury rates\n\n- 1 EUR = 1.10 USD\n- 1 GBP = 1.25 USD\n\nRates as of the last business day of the quarter, from the company treasury feed.\n\n## Dashboard note\n\nThe dashboard sums the Revenue column directly and displays **600**."}],"stakeholders":[{"id":"lena","name":"Lena Fischer","role":"International Finance Lead","blurb":"Signs off on the combined revenue number. Does not trust the current one.","knowledge":["Regional teams book revenue in their local currency by policy.","Treasury publishes an official rate every business day; quarter reporting uses the last business day''s rate."],"withholds":["Will not compute the converted total."],"responseRules":[{"id":"rel_rates","priority":3,"anyKeywords":["rate","exchange","convert","which rate","treasury","fx"],"reply":"Treasury publishes an official rate every business day. For quarter reporting we use the rate on the last business day of the quarter."},{"id":"rel_local","priority":2,"anyKeywords":["local currency","eur","gbp","euro","pound","germany","uk","currency"],"reply":"Regional teams book revenue in their local currency. That is policy. The dashboard was supposed to handle the conversion."}],"fallbackReply":"Each regional number looks right to its regional team. It is the combined number nobody trusts."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is wrong with the displayed 600 total?","options":["Amounts in different currencies were summed without conversion","The UK number was double counted","Germany''s revenue is missing from the table","The dashboard rounds each region down"],"points":30,"answer":["Amounts in different currencies were summed without conversion"],"competencyKey":"problem_diagnosis","expectedEvidence":"The table mixes USD, EUR and GBP. Adding 300 + 200 + 100 treats a euro and a pound as a dollar, which understates the USD total."},{"id":"corrected_total","kind":"number","prompt":"What is the corrected total in USD thousands?","helpText":"Enter the number only, e.g. 700","points":25,"answer":[645,1],"competencyKey":"analytical_correctness","expectedEvidence":"300 USD + (200 EUR x 1.10 = 220) + (100 GBP x 1.25 = 125) = 645 thousand USD."},{"id":"documentation","kind":"single_select","prompt":"What must be documented alongside the converted number?","options":["The exchange-rate date and source","The dashboard color scheme","The names of the regional managers","The number of rows in the table"],"points":15,"answer":["The exchange-rate date and source"],"competencyKey":"reporting_rigor","expectedEvidence":"A converted total is only reproducible if the rate date and source are stated. The treasury feed and the last-business-day date must travel with the number."},{"id":"recommendation","kind":"text","prompt":"Recommend how currency should be handled in reporting from now on.","helpText":"Max 400 characters. Cover data, conversion and documentation.","maxChars":400,"points":20,"concepts":[{"id":"convert_stated_rate","label":"Convert at a stated rate","keywords":["convert","conversion","stated rate","exchange rate","official rate"]},{"id":"store_currency","label":"Store currency with every amount","keywords":["currency column","currency with every","currency field","store the currency","tag the currency"]},{"id":"single_reporting_currency","label":"Report in a single currency","keywords":["reporting currency","single currency","one currency","usd for reporting","common currency"]},{"id":"document_rate","label":"Document the rate source and date","keywords":["document","rate source","rate date","dated","source and date"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Store the currency with every amount, convert everything to a single reporting currency at a stated official rate, and document the rate source and date with every combined number."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"reporting_rigor","label":"Reporting rigor"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Spotted that the dashboard adds three currencies as if they were one.","corrected_total":"Converted each region correctly and reached the 645 thousand USD total.","documentation":"Knew that the rate date and source must travel with the converted number.","recommendation":"The recommendation fixes the data model, the conversion and the documentation together."},"improvementTemplates":{"root_cause":"The 600 total sums USD, EUR and GBP without conversion. The three currencies are not interchangeable.","corrected_total":"The corrected total is 645 thousand USD: 300 + (200 EUR at 1.10 = 220) + (100 GBP at 1.25 = 125).","documentation":"The exchange-rate date and source must be documented so the converted number can be reproduced and audited.","recommendation":"A stronger recommendation stores currency with every amount, converts to one reporting currency at a stated rate and documents the rate source and date."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"currency-confusion","roleKey":"bi_analyst","title":"Currency Confusion","tagline":"The regional dashboard adds dollars, euros and pounds like they are the same thing.","mission":"The regional revenue dashboard shows a 600 total by adding the raw regional numbers, but the regions report in three different currencies. Diagnose the problem, compute the correct USD total and recommend how currency should be handled in reporting.","companyName":"Ostara Goods","durationMinutes":5,"resources":[{"id":"revenue","title":"Quarterly revenue by region","kind":"table","content":"| Region | Revenue (thousands) | Currency |\n| --- | ---: | --- |\n| US | 300 | USD |\n| Germany | 200 | EUR |\n| UK | 100 | GBP |"},{"id":"rates","title":"Exchange rates","kind":"markdown","content":"## Treasury rates\n\n- 1 EUR = 1.10 USD\n- 1 GBP = 1.25 USD\n\nRates as of the last business day of the quarter, from the company treasury feed.\n\n## Dashboard note\n\nThe dashboard sums the Revenue column directly and displays **600**."}],"stakeholders":[{"id":"lena","name":"Lena Fischer","role":"International Finance Lead","blurb":"Signs off on the combined revenue number. Does not trust the current one.","knowledge":["Regional teams book revenue in their local currency by policy.","Treasury publishes an official rate every business day; quarter reporting uses the last business day''s rate."],"withholds":["Will not compute the converted total."],"responseRules":[{"id":"rel_rates","priority":3,"anyKeywords":["rate","exchange","convert","which rate","treasury","fx"],"reply":"Treasury publishes an official rate every business day. For quarter reporting we use the rate on the last business day of the quarter."},{"id":"rel_local","priority":2,"anyKeywords":["local currency","eur","gbp","euro","pound","germany","uk","currency"],"reply":"Regional teams book revenue in their local currency. That is policy. The dashboard was supposed to handle the conversion."}],"fallbackReply":"Each regional number looks right to its regional team. It is the combined number nobody trusts."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is wrong with the displayed 600 total?","options":["Amounts in different currencies were summed without conversion","The UK number was double counted","Germany''s revenue is missing from the table","The dashboard rounds each region down"],"points":30,"answer":["Amounts in different currencies were summed without conversion"],"competencyKey":"problem_diagnosis","expectedEvidence":"The table mixes USD, EUR and GBP. Adding 300 + 200 + 100 treats a euro and a pound as a dollar, which understates the USD total."},{"id":"corrected_total","kind":"number","prompt":"What is the corrected total in USD thousands?","helpText":"Enter the number only, e.g. 700","points":25,"answer":[645,1],"competencyKey":"analytical_correctness","expectedEvidence":"300 USD + (200 EUR x 1.10 = 220) + (100 GBP x 1.25 = 125) = 645 thousand USD."},{"id":"documentation","kind":"single_select","prompt":"What must be documented alongside the converted number?","options":["The exchange-rate date and source","The dashboard color scheme","The names of the regional managers","The number of rows in the table"],"points":15,"answer":["The exchange-rate date and source"],"competencyKey":"reporting_rigor","expectedEvidence":"A converted total is only reproducible if the rate date and source are stated. The treasury feed and the last-business-day date must travel with the number."},{"id":"recommendation","kind":"text","prompt":"Recommend how currency should be handled in reporting from now on.","helpText":"Max 400 characters. Cover data, conversion and documentation.","maxChars":400,"points":20,"concepts":[{"id":"convert_stated_rate","label":"Convert at a stated rate","keywords":["convert","conversion","stated rate","exchange rate","official rate"]},{"id":"store_currency","label":"Store currency with every amount","keywords":["currency column","currency with every","currency field","store the currency","tag the currency"]},{"id":"single_reporting_currency","label":"Report in a single currency","keywords":["reporting currency","single currency","one currency","usd for reporting","common currency"]},{"id":"document_rate","label":"Document the rate source and date","keywords":["document","rate source","rate date","dated","source and date"]}],"competencyKey":"recommendation_quality","expectedEvidence":"Store the currency with every amount, convert everything to a single reporting currency at a stated official rate, and document the rate source and date with every combined number."}],"competencies":[{"key":"problem_diagnosis","label":"Problem diagnosis"},{"key":"analytical_correctness","label":"Analytical correctness"},{"key":"reporting_rigor","label":"Reporting rigor"},{"key":"recommendation_quality","label":"Recommendation quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Spotted that the dashboard adds three currencies as if they were one.","corrected_total":"Converted each region correctly and reached the 645 thousand USD total.","documentation":"Knew that the rate date and source must travel with the converted number.","recommendation":"The recommendation fixes the data model, the conversion and the documentation together."},"improvementTemplates":{"root_cause":"The 600 total sums USD, EUR and GBP without conversion. The three currencies are not interchangeable.","corrected_total":"The corrected total is 645 thousand USD: 300 + (200 EUR at 1.10 = 220) + (100 GBP at 1.25 = 125).","documentation":"The exchange-rate date and source must be documented so the converted number can be reproduced and audited.","recommendation":"A stronger recommendation stores currency with every amount, converts to one reporting currency at a stated rate and documents the