begin
  select id into t_id from public.sim_templates where slug = 'promise-or-product-fit';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('promise-or-product-fit', 'solutions_engineer', 'Promise or Product Fit', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'solutions_engineer', title = 'Promise or Product Fit', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"promise-or-product-fit","roleKey":"solutions_engineer","title":"Promise or Product Fit","tagline":"Sales wants an answer before tomorrow''s demo. The product has one real gap.","mission":"A prospective customer wants SSO, a read-only CRM import and real-time bidirectional CRM updates. Sales wants an answer before tomorrow''s product demonstration. Determine what is supported and propose an honest solution.","companyName":"Meridian Assurance (prospect)","durationMinutes":5,"resources":[{"id":"requirements","title":"Customer requirements","kind":"markdown","content":"## What the customer asked for\n\n- SAML single sign-on\n- Import CRM account data\n- Send completed assessment results back to the CRM\n- Reflect CRM changes inside the product immediately\n- No custom software installed inside the customer network"},{"id":"capabilities","title":"Product capabilities","kind":"table","content":"| Capability | Status |\n| --- | --- |\n| SAML SSO | Supported |\n| Scheduled read-only CRM API import | Supported |\n| Outbound completion webhooks | Supported |\n| Real-time CRM write-back | Not supported |\n| Customer-installed connector | Optional, unavailable to this customer |"}],"stakeholders":[{"id":"alex","name":"Alex Morgan","role":"Account Executive","blurb":"Owns the deal. Wants a confident answer for tomorrow''s demo.","knowledge":["SSO and getting candidate results into the CRM are mandatory; real-time updates are nice-to-have.","Sales said ''we support CRM integration'' but promised no specific synchronization method."],"withholds":["Will not decide the architecture."],"responseRules":[{"id":"rel_essential","priority":3,"anyKeywords":["essential","mandatory","must have","required","priorit","deal breaker","need most"],"reply":"SSO and getting candidate results into the CRM are mandatory. Real-time updates would be helpful, but the customer has not said they are mandatory."},{"id":"rel_promised","priority":2,"anyKeywords":["promise","commit","told them","said we","real-time","real time","sync"],"reply":"I said we support CRM integration, but I did not promise a specific synchronization method."}],"fallbackReply":"I need something I can say to the customer tomorrow. What''s actually possible with what we have today?"}],"questions":[{"id":"capability_classification","kind":"multi_select","prompt":"Which customer requirements are fully supported today, without the connector?","options":["SAML single sign-on","Import CRM account data","Send completed assessment results back to the CRM","Reflect CRM changes inside the product immediately"],"points":30,"answer":["SAML single sign-on","Import CRM account data","Send completed assessment results back to the CRM"],"competencyKey":"requirement_analysis","expectedEvidence":"SAML SSO, scheduled read-only CRM import and outbound completion webhooks are supported. Immediate reflection of CRM changes requires real-time write-back, which is not supported."},{"id":"architecture","kind":"single_select","prompt":"Which architecture do you recommend?","options":["SAML SSO + scheduled CRM import + outbound completion webhook","Customer-installed connector","Promise real-time bidirectional synchronization","Manual CSV export only"],"points":25,"answer":["SAML SSO + scheduled CRM import + outbound completion webhook"],"competencyKey":"solution_judgment","expectedEvidence":"The supported stack covers every mandatory requirement. The connector is unavailable to this customer, and promising real-time sync would be false."},{"id":"main_gap","kind":"single_select","prompt":"What is the main product gap for this customer?","options":["Real-time bidirectional CRM synchronization","SAML single sign-on","CRM data import","Sending results to the CRM"],"points":15,"answer":["Real-time bidirectional CRM synchronization"],"competencyKey":"product_understanding","expectedEvidence":"Real-time CRM write-back is the only requirement the product cannot meet today."},{"id":"customer_explanation","kind":"text","prompt":"Write a short customer-facing explanation of your proposed solution.","helpText":"Max 400 characters. Communicate the solution without hiding the limitation.","maxChars":400,"points":20,"concepts":[{"id":"state_supported","label":"States what is supported","keywords":["sso","single sign","import","webhook","results","scheduled"]},{"id":"honest_limitation","label":"Acknowledges the real-time limitation honestly","keywords":["not real-time","not real time","not immediate","not currently support","limitation","gap","scheduled rather","near real"]},{"id":"workable_alternative","label":"Offers the workable alternative","keywords":["scheduled","webhook","sync interval","hourly","daily","refresh","on completion"]}],"competencyKey":"transparency","expectedEvidence":"We support SAML SSO, a scheduled read-only import of your CRM accounts, and instant delivery of completed results to your CRM via webhooks. Changes made in your CRM appear at the next scheduled sync rather than in real time. We''re happy to tune the interval to your workflow."}],"competencies":[{"key":"requirement_analysis","label":"Requirement analysis"},{"key":"product_understanding","label":"Product understanding"},{"key":"solution_judgment","label":"Solution judgment"},{"key":"transparency","label":"Transparency"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"capability_classification":"Classified every requirement correctly against real product capabilities.","architecture":"Recommended the architecture that meets all mandatory requirements without overpromising.","main_gap":"Identified real-time bidirectional synchronization as the true gap.","customer_explanation":"The customer explanation is honest about the limitation while presenting a workable solution."},"improvementTemplates":{"capability_cla