do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'sso-not-provisioning';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('sso-not-provisioning', 'solutions_engineer', 'SSO Is Not Provisioning', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'solutions_engineer', title = 'SSO Is Not Provisioning', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"sso-not-provisioning","roleKey":"solutions_engineer","title":"SSO Is Not Provisioning","tagline":"The customer wants SSO to do a job SSO does not do.","mission":"Ridgemont Financial asked for single sign-on with automatic account provisioning. The product supports SAML SSO but not SCIM. Work out what is really supported, name the gap honestly and write the explanation the customer will read.","companyName":"Ridgemont Financial (customer)","durationMinutes":5,"resources":[{"id":"requirements","title":"Customer requirements","kind":"markdown","content":"## What Ridgemont Financial asked for\n\n- Single sign-on through their identity provider\n- New employees get an account automatically, with no ticket\n- Departed employees lose access automatically\n- Go live within one month"},{"id":"capabilities","title":"Product capability doc","kind":"table","content":"| Capability | Status |\n| --- | --- |\n| SAML single sign-on | Supported |\n| Just-in-time account creation at first login | Supported |\n| SCIM automatic provisioning and deprovisioning | Not supported |\n| CSV user import | Supported |"}],"stakeholders":[{"id":"jordan","name":"Jordan Pike","role":"Account Executive","blurb":"Ran the discovery call with Ridgemont. Needs a clear answer to send back.","knowledge":["The customer''s IT team creates every account by hand today and wants that to stop.","On the call the customer used SSO to mean both login and account creation.","The customer runs a standard identity provider and HR can export a user list as CSV."],"withholds":["Will not say what the product supports. That is your job."],"responseRules":[{"id":"rel_goal","priority":3,"anyKeywords":["goal","want","achieve","why","manual","onboard","pain","problem"],"reply":"Their IT team creates every account by hand today. They want new employees to get access without a ticket, and departed employees removed quickly."},{"id":"rel_definition","priority":2,"anyKeywords":["mean","sso","conflat","same thing","account creation","difference","login"],"reply":"When they say SSO they seem to mean both login and account creation. Nobody on the call separated the two."},{"id":"rel_constraint","priority":2,"anyKeywords":["directory","export","csv","hr","identity provider","user list"],"reply":"They run a standard identity provider, and their HR team can export a user list as CSV whenever needed."}],"fallbackReply":"I can tell you what the customer said on the call. What the product actually does is your side of the desk."}],"questions":[{"id":"conflation","kind":"single_select","prompt":"What is the customer conflating in their request?","options":["Authentication and provisioning are different capabilities","SAML and CSV import are the same feature","Single sign-on requires SCIM to work at all","Account creation is only possible manually"],"points":30,"answer":["Authentication and provisioning are different capabilities"],"competencyKey":"requirement_analysis","expectedEvidence":"The customer bundles login (authentication) with account creation and removal (provisioning). The product supports the first through SAML but handles the second differently."},{"id":"supported_today","kind":"multi_select","prompt":"Which capabilities are supported today?","options":["SAML single sign-on","Just-in-time account creation at first login","CSV user import","SCIM automatic provisioning"],"points":25,"answer":["SAML single sign-on","Just-in-time account creation at first login","CSV user import"],"competencyKey":"product_knowledge","expectedEvidence":"The capability doc lists SAML SSO, just-in-time account creation and CSV user import as supported. SCIM provisioning is not supported."},{"id":"honest_gap","kind":"single_select","prompt":"What is the honest gap to tell the customer?","options":["SCIM automatic provisioning and deprovisioning","SAML single sign-on","Creating accounts at first login","Importing users from a CSV file"],"points":15,"answer":["SCIM automatic provisioning and deprovisioning"],"competencyKey":"gap_identification","expectedEvidence":"SCIM is the only capability marked not supported. It covers automatic provisioning and, critically for this customer, automatic deprovisioning of departed employees."},{"id":"customer_explanation","kind":"text","prompt":"Write the customer-facing explanation.","helpText":"Max 400 characters. Separate what works from what does not, and offer the supported path.","maxChars":400,"points":20,"concepts":[{"id":"separate_capabilities","label":"Separates authentication from provisioning","keywords":["two different","separate","different capabilit","authentication and provisioning","not the same"]},{"id":"confirm_saml","label":"Confirms SAML SSO works today","keywords":["saml","single sign-on is supported","sso is supported","sso works","sign-on works"]},{"id":"name_scim_gap","label":"Names the SCIM gap plainly","keywords":["scim","automatic provisioning is not","deprovisioning","no automatic provisioning"]},{"id":"offer_path","label":"Offers the supported onboarding path","keywords":["csv","just-in-time","first login","import","created at login"]}],"competencyKey":"customer_transparency","expectedEvidence":"Login and provisioning are two different capabilities. SAML SSO is fully supported. SCIM automatic provisioning and deprovisioning is not supported today. Accounts can be created just-in-time at first login, and HR can load or remove users with a CSV import."}],"competencies":[{"key":"requirement_analysis","label":"Requirement analysis"},{"key":"product_knowledge","label":"Product knowledge"},{"key":"gap_identification","label":"Gap identification"},{"key":"customer_transparency","label":"Customer transparency"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"conflation":"Spotted that the customer bundled authentication and provisioning into one request.","supported_today":"Classified the supported capabilities exactly as the capability doc states.","honest_gap":"Named SCIM provisioning and deprovisioning as the real gap.","customer_explanation":"The explanation separates the two capabilities, states the gap plainly and offers a workable path."},"improvementTemplates":{"conflation":"The customer is conflating authentication with provisioning. SAML handles login. Creating and removing accounts is a separate capability.","supported_today":"Three capabilities are supported today: SAML SSO, just-in-time account creation and CSV user import. SCIM is not.","honest_gap":"The honest gap is SCIM automatic provisioning and deprovisioning. Everything else the customer asked for has a supported path.","customer_explanation":"A stronger explanation confirms SAML works, names the SCIM gap without hedging, and offers just-in-time creation plus CSV import as the onboarding path."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"sso-not-provisioning","roleKey":"solutions_engineer","title":"SSO Is Not Provisioning","tagline":"The customer wants SSO to do a job SSO does not do.","mission":"Ridgemont Financial asked for single sign-on with automatic account provisioning. The product supports SAML SSO but not SCIM. Work out what is really supported, name the gap honestly and write the explanation the customer will read.","companyName":"Ridgemont Financial (customer)","durationMinutes":5,"resources":[{"id":"requirements","title":"Customer requirements","kind":"markdown","content":"## What Ridgemont Financial asked for\n\n- Single sign-on through their identity provider\n- New employees get an account automatically, with no ticket\n- Departed employees lose access automatically\n- Go live within one month"},{"id":"capabilities","title":"Product capability doc","kind":"table","content":"| Capability | Status |\n| --- | --- |\n| SAML single sign-on | Supported |\n| Just-in-time account creation at first login | Supported |\n| SCIM automatic provisioning and deprovisioning | Not supported |\n| CSV user import | Supported |"}],"stakeholders":[{"id":"jordan","name":"Jordan Pike","role":"Account Executive","blurb":"Ran the discovery call with Ridgemont. Needs a clear answer to send back.","knowledge":["The customer''s IT team creates every account by hand today and wants that to stop.","On the call the customer used SSO to mean both login and account creation.","The customer runs a standard identity provider and HR can export a user list as CSV."],"withholds":["Will not say what the product supports. That is your job."],"responseRules":[{"id":"rel_goal","priority":3,"anyKeywords":["goal","want","achieve","why","manual","onboard","pain","problem"],"reply":"Their IT team creates every account by hand today. They want new employees to get access without a ticket, and departed employees removed quickly."},{"id":"rel_definition","priority":2,"anyKeywords":["mean","sso","conflat","same thing","account creation","difference","login"],"reply":"When they say SSO they seem to mean both login and account creation. Nobody on the call separated the two."},{"id":"rel_constraint","priority":2,"anyKeywords":["directory","export","csv","hr","identity provider","user list"],"reply":"They run a standard identity provider, and their HR team can export a user list as CSV whenever needed."}],"fallbackReply":"I can tell you what the customer said on the call. What the product actually does is your side of the desk."}],"questions":[{"id":"conflation","kind":"single_select","prompt":"What is the customer conflating in their request?","options":["Authentication and provisioning are different capabilities","SAML and CSV import are the same feature","Single sign-on requires SCIM to work at all","Account creation is only possible manually"],"points":30,"answer":["Authentication and provisioning are different capabilities"],"competencyKey":"requirement_analysis","expectedEvidence":"The customer bundles login (authentication) with account creation and removal (provisioning). The product supports the first through SAML but handles the second differently."},{"id":"supported_today","kind":"multi_select","prompt":"Which capabilities are supported today?","options":["SAML single sign-on","Just-in-time account creation at first login","CSV user import","SCIM automatic provisioning"],"points":25,"answer":["SAML single sign-on","Just-in-time account creation at first login","CSV user import"],"competencyKey":"product_knowledge","expectedEvidence":"The capability doc lists SAML SSO, just-in-time account creation and CSV user import as supported. SCIM provisioning is not supported."},{"id":"honest_gap","kind":"single_select","prompt":"What is the honest gap to tell the customer?","options":["SCIM automatic provisioning and deprovisioning","SAML single sign-on","Creating accounts at first login","Importing users from a CSV file"],"points":15,"answer":["SCIM automatic provisioning and deprovisioning"],"competencyKey":"gap_identification","expectedEvidence":"SCIM is the only capability marked not supported. It covers automatic provisioning and, critically for this customer, automatic deprovisioning of departed employees."},{"id":"customer_explanation","kind":"text","prompt":"Write the customer-facing explanation.","helpText":"Max 400 characters. Separate what works from what does not, and offer the supported path.","maxChars":400,"points":20,"concepts":[{"id":"separate_capabilities","label":"Separates authentication from provisioning","keywords":["two different","separate","different capabilit","authentication and provisioning","not the same"]},{"id":"confirm_saml","label":"Confirms SAML SSO works today","keywords":["saml","single sign-on is supported","sso is supported","sso works","sign-on works"]},{"id":"name_scim_gap","label":"Names the SCIM gap plainly","keywords":["scim","automatic provisioning is not","deprovisioning","no automatic provisioning"]},{"id":"offer_path","label":"Offers the supported onboarding path","keywords":["csv","just-in-time","first login","import","created at login"]}],"competencyKey":"customer_transparency","expectedEvidence":"Login and provisioning are two different capabilities. SAML SSO is fully supported. SCIM automatic provisioning and deprovisioning is not supported today. Accounts can be created just-in-time at first login, and HR can load or remove users with a CSV import."}],"competencies":[{"key":"requirement_analysis","label":"Requirement analysis"},{"key":"product_knowledge","label":"Product knowledge"},{"key":"gap_identification","label":"Gap identification"},{"key":"customer_transparency","label":"Customer transparency"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"conflation":"Spotted that the customer bundled authentication and provisioning into one request.","supported_today":"Classified the supported capabilities exactly as the capability doc states.","honest_gap":"Named SCIM provisioning and deprovisioning as the real gap.","customer_explanation":"The explanation separates the two capabilities, states the gap plainly and offers a workable path."},"improvementTemplates":{"conflation":"The customer is conflating authentication with provisioning. SAML handles login. Creating and removing accounts is a separate capability.","supported_today":"Three capabilities are supported today: SAML SSO, just-in-time account creation and CSV user import. SCIM is not.","honest_gap":"The honest gap is SCIM automatic provisioning and deprovisioning. Everything else the customer asked for has a supported path.","customer_explanation":"A stronger explanation confirms SAML works, names the SCIM gap without hedging, and offers just-in-time creation plus CSV import as the onboarding path."}}'::jsonb,
