do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'rate-limit';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('rate-limit', 'solutions_engineer', 'The Rate Limit', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'solutions_engineer', title = 'The Rate Limit', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"rate-limit","roleKey":"solutions_engineer","title":"The Rate Limit","tagline":"The customer wants 100,000 records now. The API has other plans.","mission":"Harlow Freight wants all 100,000 shipment records loaded immediately. The API allows 1,000 requests per hour. Work out what is actually possible, do the math and set an expectation the customer can trust.","companyName":"Harlow Freight (customer)","durationMinutes":5,"resources":[{"id":"sync_request","title":"Sync requirement note","kind":"markdown","content":"## Customer request\n\nHarlow Freight wants all 100,000 shipment records loaded into the platform immediately. Their team starts using the product next Monday."},{"id":"api_limits","title":"API limits doc","kind":"table","content":"| Limit | Value |\n| --- | --- |\n| Requests per hour, per customer | 1,000 |\n| Records per request (standard endpoint) | 1 |\n| Records per request (batch endpoint) | 100 |\n| Rate limit exceptions | Not available |"}],"stakeholders":[{"id":"mira","name":"Mira Solis","role":"Integration Lead, Harlow Freight","blurb":"Owns the customer''s side of the integration. Practical, wants a real date.","knowledge":["The 100,000 records are a one-time historical load. After that, roughly 2,000 records change per day.","Immediate would be nice, but loaded before Monday is what actually matters."],"withholds":["Does not know the platform''s API limits and will not do the math."],"responseRules":[{"id":"rel_goal","priority":3,"anyKeywords":["immediate","real-time","real time","deadline","monday","when","urgent","why"],"reply":"Immediate would be nice, but honestly what matters is that the records are in place before our team starts on Monday."},{"id":"rel_scope","priority":2,"anyKeywords":["one-time","one time","initial","ongoing","daily","incremental","after that","changes"],"reply":"The 100,000 records are a one-time historical load. After that we expect around 2,000 changed records per day."},{"id":"rel_limit","priority":2,"anyKeywords":["limit","rate","quota","increase","exception","faster"],"reply":"The rate limit is on your platform, not ours. Our side can send requests as fast as you allow."}],"fallbackReply":"I can answer anything about our data and our timing. The API limits are on your side of the fence."}],"questions":[{"id":"core_constraint","kind":"single_select","prompt":"What is the core constraint on this sync?","options":["The API request rate limit","The size of each shipment record","The customer''s network bandwidth","The number of user licenses"],"points":30,"answer":["The API request rate limit"],"competencyKey":"constraint_identification","expectedEvidence":"The API allows 1,000 requests per hour with no exceptions. Everything else about the sync is flexible. The request budget is what bounds the timeline."},{"id":"batch_hours","kind":"number","prompt":"Using the batch endpoint, what is the minimum number of hours for the initial load?","helpText":"Enter hours as a number, e.g. 4","points":25,"answer":[1,0.1],"competencyKey":"capacity_estimation","expectedEvidence":"100,000 records at 100 records per request is 1,000 requests. At 1,000 requests per hour that is 1 hour."},{"id":"unbatched_hours","kind":"number","prompt":"Without batching, how many hours would the initial load take?","helpText":"Enter hours as a number.","points":15,"answer":[100,1],"competencyKey":"impact_quantification","expectedEvidence":"100,000 records at 1 record per request is 100,000 requests. At 1,000 requests per hour that is 100 hours."},{"id":"customer_message","kind":"text","prompt":"Write what you would tell the customer.","helpText":"Max 400 characters. A realistic plan with a timeline they can rely on.","maxChars":400,"points":20,"concepts":[{"id":"recommend_batch","label":"Recommends the batch endpoint","keywords":["batch","100 records per request","batched"]},{"id":"time_estimate","label":"Gives the realistic time estimate","keywords":["one hour","1 hour","an hour","within the hour"]},{"id":"no_realtime_promise","label":"Does not promise real-time","keywords":["not real-time","not real time","not instant","not immediate","cannot be instant"]},{"id":"sync_plan","label":"Initial sync first, then incremental updates","keywords":["initial","incremental","daily updates","then sync changes","ongoing updates","schedule"]}],"competencyKey":"expectation_setting","expectedEvidence":"Use the batch endpoint at 100 records per request. The initial load of 100,000 records takes about 1 hour, well before Monday. The sync is scheduled, not real-time. After the initial load, run incremental updates for the roughly 2,000 daily changes."}],"competencies":[{"key":"constraint_identification","label":"Constraint identification"},{"key":"capacity_estimation","label":"Capacity estimation"},{"key":"impact_quantification","label":"Impact quantification"},{"key":"expectation_setting","label":"Expectation setting"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"core_constraint":"Identified the request rate limit as the constraint that bounds the timeline.","batch_hours":"Calculated the batched load time correctly: 1,000 requests, 1 hour.","unbatched_hours":"Quantified the unbatched cost correctly: 100,000 requests, 100 hours.","customer_message":"The message recommends the batch endpoint, gives a real timeline and avoids promising real-time."},"improvementTemplates":{"core_constraint":"The core constraint is the API rate limit of 1,000 requests per hour, with no exceptions available.","batch_hours":"With the batch endpoint, 100,000 records is 1,000 requests of 100 records each. At 1,000 requests per hour, the load takes about 1 hour.","unbatched_hours":"Without batching, 100,000 records means 100,000 requests. At 1,000 requests per hour, that is 100 hours.","customer_message":"A stronger message recommends the batch endpoint, states the 1 hour estimate, avoids promising real-time and schedules incremental updates after the initial load."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"rate-limit","roleKey":"solutions_engineer","title":"The Rate Limit","tagline":"The customer wants 100,000 records now. The API has other plans.","mission":"Harlow Freight wants all 100,000 shipment records loaded immediately. The API allows 1,000 requests per hour. Work out what is actually possible, do the math and set an expectation the customer can trust.","companyName":"Harlow Freight (customer)","durationMinutes":5,"resources":[{"id":"sync_request","title":"Sync requirement note","kind":"markdown","content":"## Customer request\n\nHarlow Freight wants all 100,000 shipment records loaded into the platform immediately. Their team starts using the product next Monday."},{"id":"api_limits","title":"API limits doc","kind":"table","content":"| Limit | Value |\n| --- | --- |\n| Requests per hour, per customer | 1,000 |\n| Records per request (standard endpoint) | 1 |\n| Records per request (batch endpoint) | 100 |\n| Rate limit exceptions | Not available |"}],"stakeholders":[{"id":"mira","name":"Mira Solis","role":"Integration Lead, Harlow Freight","blurb":"Owns the customer''s side of the integration. Practical, wants a real date.","knowledge":["The 100,000 records are a one-time historical load. After that, roughly 2,000 records change per day.","Immediate would be nice, but loaded before Monday is what actually matters."],"withholds":["Does not know the platform''s API limits and will not do the math."],"responseRules":[{"id":"rel_goal","priority":3,"anyKeywords":["immediate","real-time","real time","deadline","monday","when","urgent","why"],"reply":"Immediate would be nice, but honestly what matters is that the records are in place before our team starts on Monday."},{"id":"rel_scope","priority":2,"anyKeywords":["one-time","one time","initial","ongoing","daily","incremental","after that","changes"],"reply":"The 100,000 records are a one-time historical load. After that we expect around 2,000 changed records per day."},{"id":"rel_limit","priority":2,"anyKeywords":["limit","rate","quota","increase","exception","faster"],"reply":"The rate limit is on your platform, not ours. Our side can send requests as fast as you allow."}],"fallbackReply":"I can answer anything about our data and our timing. The API limits are on your side of the fence."}],"questions":[{"id":"core_constraint","kind":"single_select","prompt":"What is the core constraint on this sync?","options":["The API request rate limit","The size of each shipment record","The customer''s network bandwidth","The number of user licenses"],"points":30,"answer":["The API request rate limit"],"competencyKey":"constraint_identification","expectedEvidence":"The API allows 1,000 requests per hour with no exceptions. Everything else about the sync is flexible. The request budget is what bounds the timeline."},{"id":"batch_hours","kind":"number","prompt":"Using the batch endpoint, what is the minimum number of hours for the initial load?","helpText":"Enter hours as a number, e.g. 4","points":25,"answer":[1,0.1],"competencyKey":"capacity_estimation","expectedEvidence":"100,000 records at 100 records per request is 1,000 requests. At 1,000 requests per hour that is 1 hour."},{"id":"unbatched_hours","kind":"number","prompt":"Without batching, how many hours would the initial load take?","helpText":"Enter hours as a number.","points":15,"answer":[100,1],"competencyKey":"impact_quantification","expectedEvidence":"100,000 records at 1 record per request is 100,000 requests. At 1,000 requests per hour that is 100 hours."},{"id":"customer_message","kind":"text","prompt":"Write what you would tell the customer.","helpText":"Max 400 characters. A realistic plan with a timeline they can rely on.","maxChars":400,"points":20,"concepts":[{"id":"recommend_batch","label":"Recommends the batch endpoint","keywords":["batch","100 records per request","batched"]},{"id":"time_estimate","label":"Gives the realistic time estimate","keywords":["one hour","1 hour","an hour","within the hour"]},{"id":"no_realtime_promise","label":"Does not promise real-time","keywords":["not real-time","not real time","not instant","not immediate","cannot be instant"]},{"id":"sync_plan","label":"Initial sync first, then incremental updates","keywords":["initial","incremental","daily updates","then sync changes","ongoing updates","schedule"]}],"competencyKey":"expectation_setting","expectedEvidence":"Use the batch endpoint at 100 records per request. The initial load of 100,000 records takes about 1 hour, well before Monday. The sync is scheduled, not real-time. After the initial load, run incremental updates for the roughly 2,000 daily changes."}],"competencies":[{"key":"constraint_identification","label":"Constraint identification"},{"key":"capacity_estimation","label":"Capacity estimation"},{"key":"impact_quantification","label":"Impact quantification"},{"key":"expectation_setting","label":"Expectation setting"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"core_constraint":"Identified the request rate limit as the constraint that bounds the timeline.","batch_hours":"Calculated the batched load time correctly: 1,000 requests, 1 hour.","unbatched_hours":"Quantified the unbatched cost correctly: 100,000 requests, 100 hours.","customer_message":"The message recommends the batch endpoint, gives a real timeline and avoids promising real-time."},"improvementTemplates":{"core_constraint":"The core constraint is the API rate limit of 1,000 requests per hour, with no exceptions available.","batch_hours":"With the batch endpoint, 100,000 records is 1,000 requests of 100 records each. At 1,000 requests per hour, the load takes about 1 hour.","unbatched_hours":"Without batching, 100,000 records means 100,000 requests. At 1,000 requests per hour, that is 100 hours.","customer_message":"A stronger message recommends the batch endpoint, states the 1 hour estimate, avoids promising real-time and schedules incremental updates after the initial load."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'security-review';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('security-review', 'solutions_engineer', 'The Security Review', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'solutions_engineer', title = 'The Security Review', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"security-review","roleKey":"solutions_engineer","title":"The Security Review","tagline":"One line in a security questionnaire could sink the deal or your credibility.","mission":"Veyra Bank requires deletion of all customer data within 30 days. The product keeps audit data for 90 days and that is fixed. Identify the mismatch, decide who needs to be involved and draft a careful response.","companyName":"Veyra Bank (prospect)","durationMinutes":5,"resources":[{"id":"customer_requirement","title":"Security questionnaire, item 14","kind":"markdown","content":"## Veyra Bank security questionnaire, item 14\n\nAll customer data must be deleted within 30 days of a deletion request or contract end. Please confirm compliance."},{"id":"retention_policy","title":"Data retention policy","kind":"table","content":"| Data type | Retention | Configurable |\n| --- | --- | --- |\n| Activity data | 30 to 365 days, customer sets the value | Yes |\n| Audit data | 90 days | No, fixed for all customers |\n| Backup copies | 35 days | No, fixed for all customers |"}],"stakeholders":[{"id":"priya","name":"Priya Nair","role":"Security Program Manager","blurb":"Owns the retention policy and the security review process.","knowledge":["Audit retention is fixed at 90 days for fraud investigation reasons. No exception has ever been granted.","Anything touching a contractual deletion commitment must go through security and legal review first.","Activity data retention can be set to 30 days today."],"withholds":["Will not tell you what to promise the customer."],"responseRules":[{"id":"rel_audit","priority":3,"anyKeywords":["audit","90","fixed","exception","change the retention","shorten"],"reply":"Audit retention is fixed at 90 days for fraud investigation reasons. No customer exception has ever been granted."},{"id":"rel_process","priority":2,"anyKeywords":["escalate","legal","who decide","approve","process","review","sign off"],"reply":"Anything touching a contractual deletion commitment goes through security and legal review before we respond. Please do not answer the customer alone."},{"id":"rel_scope","priority":2,"anyKeywords":["activity","configur","30 day","which data","what can we","meet today"],"reply":"Activity data retention is configurable per customer, anywhere from 30 to 365 days. That part we can meet today."}],"fallbackReply":"Ask me about the retention policy or the review process. What to promise the customer is not my call to make for you."}],"questions":[{"id":"mismatch","kind":"single_select","prompt":"Where is the mismatch between the requirement and the product?","options":["The fixed 90 day audit retention conflicts with the 30 day deletion requirement","Activity data cannot be deleted at all","The product has no retention settings","The customer wants data kept longer than the product allows"],"points":30,"answer":["The fixed 90 day audit retention conflicts with the 30 day deletion requirement"],"competencyKey":"risk_identification","expectedEvidence":"Item 14 requires deletion within 30 days. Audit data is retained for 90 days and that value is fixed for all customers, so the requirement cannot be met as written."},{"id":"configurable_today","kind":"multi_select","prompt":"Which retention settings are configurable today?","options":["Activity data retention","Audit data retention","Backup retention"],"points":25,"answer":["Activity data retention"],"competencyKey":"product_knowledge","expectedEvidence":"Only activity data retention is configurable, from 30 to 365 days. Audit data and backup copies are fixed for all customers."},{"id":"next_step","kind":"single_select","prompt":"What is the right next step?","options":["Escalate to the security and legal teams before answering the customer","Confirm compliance now and adjust the product later","Tell the customer the requirement is impossible","Skip item 14 and answer the rest of the questionnaire"],"points":15,"answer":["Escalate to the security and legal teams before answering the customer"],"competencyKey":"escalation_judgment","expectedEvidence":"The requirement touches a contractual deletion commitment, which must go through security and legal review. Confirming compliance now would be false; refusing outright is premature."},{"id":"customer_response","kind":"text","prompt":"Draft the response to the customer.","helpText":"Max 400 characters. Be accurate about what is fixed, what is configurable and what happens next.","maxChars":400,"points":20,"concepts":[{"id":"distinguish_fixed","label":"Distinguishes configurable from fixed retention","keywords":["configurable","fixed","cannot be changed","is set per customer"]},{"id":"no_false_claim","label":"Does not claim compliance without confirmation","keywords":["cannot confirm","not yet confirm","before confirming","without confirmation","not claim"]},{"id":"escalate_internally","label":"Escalates to the security team","keywords":["security team","legal","escalat","internal review","reviewing with"]},{"id":"state_today","label":"States what can be met today","keywords":["activity data","30 days","can be set","meet today","supported today"]}],"competencyKey":"customer_transparency","expectedEvidence":"Activity data retention is configurable and can be set to 30 days today. Audit data retention is fixed at 90 days. I cannot confirm full compliance with item 14 yet. Our security team and legal are reviewing it, and I will come back with a definitive answer."}],"competencies":[{"key":"risk_identification","label":"Risk identification"},{"key":"product_knowledge","label":"Product knowledge"},{"key":"escalation_judgment","label":"Escalation judgment"},{"key":"customer_transparency","label":"Customer transparency"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"mismatch":"Found the exact conflict: fixed 90 day audit retention against a 30 day deletion requirement.","configurable_today":"Correctly identified activity data retention as the only configurable setting.","next_step":"Escalated to security and legal instead of answering the customer alone.","customer_response":"The response is accurate about what is fixed, does not overclaim and sets up a definitive follow-up."},"improvementTemplates":{"mismatch":"The mismatch is audit data: it is retained for 90 days, that value is fixed, and the customer requires deletion within 30 days.","configurable_today":"Only activity data retention is configurable today, from 30 to 365 days. Audit and backup retention are fixed.","next_step":"The right next step is escalating to security and legal before responding. A deletion commitment is contractual, not a support question.","customer_response":"A stronger response separates configurable from fixed retention, avoids claiming compliance before review, and states what can be met today."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"security-review","roleKey":"solutions_engineer","title":"The Security Review","tagline":"One line in a security questionnaire could sink the deal or your credibility.","mission":"Veyra Bank requires deletion of all customer data within 30 days. The product keeps audit data for 90 days and that is fixed. Identify the mismatch, decide who needs to be involved and draft a careful response.","companyName":"Veyra Bank (prospect)","durationMinutes":5,"resources":[{"id":"customer_requirement","title":"Security questionnaire, item 14","kind":"markdown","content":"## Veyra Bank security questionnaire, item 14\n\nAll customer data must be deleted within 30 days of a deletion request or contract end. Please confirm compliance."},{"id":"retention_policy","title":"Data retention policy","kind":"table","content":"| Data type | Retention | Configurable |\n| --- | --- | --- |\n| Activity data | 30 to 365 days, customer sets the value | Yes |\n| Audit data | 90 days | No, fixed for all customers |\n| Backup copies | 35 days | No, fixed for all customers |"}],"stakeholders":[{"id":"priya","name":"Priya Nair","role":"Security Program Manager","blurb":"Owns the retention policy and the security review process.","knowledge":["Audit retention is fixed at 90 days for fraud investigation reasons. No exception has ever been granted.","Anything touching a contractual deletion commitment must go through security and legal review first.","Activity data retention can be set to 30 days today."],"withholds":["Will not tell you what to promise the customer."],"responseRules":[{"id":"rel_audit","priority":3,"anyKeywords":["audit","90","fixed","exception","change the retention","shorten"],"reply":"Audit retention is fixed at 90 days for fraud investigation reasons. No customer exception has ever been granted."},{"id":"rel_process","priority":2,"anyKeywords":["escalate","legal","who decide","approve","process","review","sign off"],"reply":"Anything touching a contractual deletion commitment goes through security and legal review before we respond. Please do not answer the customer alone."},{"id":"rel_scope","priority":2,"anyKeywords":["activity","configur","30 day","which data","what can we","meet today"],"reply":"Activity data retention is configurable per customer, anywhere from 30 to 365 days. That part we can meet today."}],"fallbackReply":"Ask me about the retention policy or the review process. What to promise the customer is not my call to make for you."}],"questions":[{"id":"mismatch","kind":"single_select","prompt":"Where is the mismatch between the requirement and the product?","options":["The fixed 90 day audit retention conflicts with the 30 day deletion requirement","Activity data cannot be deleted at all","The product has no retention settings","The customer wants data kept longer than the product allows"],"points":30,"answer":["The fixed 90 day audit retention conflicts with the 30 day deletion requirement"],"competencyKey":"risk_identification","expectedEvidence":"Item 14 requires deletion within 30 days. Audit data is retained for 90 days and that value is fixed for all customers, so the requirement cannot be met as written."},{"id":"configurable_today","kind":"multi_select","prompt":"Which retention settings are configurable today?","options":["Activity data retention","Audit data retention","Backup retention"],"points":25,"answer":["Activity data retention"],"competencyKey":"product_knowledge","expectedEvidence":"Only activity data retention is configurable, from 30 to 365 days. Audit data and backup copies are fixed for all customers."},{"id":"next_step","kind":"single_select","prompt":"What is the right next step?","options":["Escalate to the security and legal teams before answering the customer","Confirm compliance now and adjust the product later","Tell the customer the requirement is impossible","Skip item 14 and answer the rest of the questionnaire"],"points":15,"answer":["Escalate to the security and legal teams before answering the customer"],"competencyKey":"escalation_judgment","expectedEvidence":"The requirement touches a contractual deletion commitment, which must go through security and legal review. Confirming compliance now would be false; refusing outright is premature."},{"id":"customer_response","kind":"text","prompt":"Draft the response to the customer.","helpText":"Max 400 characters. Be accurate about what is fixed, what is configurable and what happens next.","maxChars":400,"points":20,"concepts":[{"id":"distinguish_fixed","label":"Distinguishes configurable from fixed retention","keywords":["configurable","fixed","cannot be changed","is set per customer"]},{"id":"no_false_claim","label":"Does not claim compliance without confirmation","keywords":["cannot confirm","not yet confirm","before confirming","without confirmation","not claim"]},{"id":"escalate_internally","label":"Escalates to the security team","keywords":["security team","legal","escalat","internal review","reviewing with"]},{"id":"state_today","label":"States what can be met today","keywords":["activity data","30 days","can be set","meet today","supported today"]}],"competencyKey":"customer_transparency","expectedEvidence":"Activity data retention is configurable and can be set to 30 days today. Audit data retention is fixed at 90 days. I cannot confirm full compliance with item 14 yet. Our security team and legal are reviewing it, and I will come back with a definitive answer."}],"competencies":[{"key":"risk_identification","label":"Risk identification"},{"key":"product_knowledge","label":"Product knowledge"},{"key":"escalation_judgment","label":"Escalation judgment"},{"key":"customer_transparency","label":"Customer transparency"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"mismatch":"Found the exact conflict: fixed 90 day audit retention against a 30 day deletion requirement.","configurable_today":"Correctly identified activity data retention as the only configurable setting.","next_step":"Escalated to security and legal instead of answering the customer alone.","customer_response":"The response is accurate about what is fixed, does not overclaim and sets up a definitive follow-up."},"improvementTemplates":{"mismatch":"The mismatch is audit data: it is retained for 90 days, that value is fixed, and the customer requires deletion within 30 days.","configurable_today":"Only activity data retention is configurable today, from 30 to 365 days. Audit and backup retention are fixed.","next_step":"The right next step is escalating to security and legal before responding. A deletion commitment is contractual, not a support question.","customer_response":"A stronger response separates configurable from fixed retention, avoids claiming compliance before review, and states what can be met today."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

