  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"data-residency","roleKey":"solutions_engineer","title":"Data Residency","tagline":"Everything runs in the EU except one thing.","mission":"Nordkapp Insurance requires all data to stay in the EU. The core product is EU hosted, but one optional integration processes data in the United States. Find the risk, make a recommendation and explain the trade-off.","companyName":"Nordkapp Insurance (prospect)","durationMinutes":5,"resources":[{"id":"residency_requirement","title":"Customer requirement","kind":"markdown","content":"## Nordkapp Insurance requirement\n\nAll customer data must be stored and processed inside the EU. No customer data may leave the EU at any time."},{"id":"architecture_note","title":"Architecture note","kind":"table","content":"| Component | Where it runs | Required or optional |\n| --- | --- | --- |\n| Core product and database | EU (Frankfurt) | Required |\n| Reporting | EU (Frankfurt) | Required |\n| SSO service | EU (Dublin) | Required |\n| Data enrichment integration | United States (third party) | Optional |"}],"stakeholders":[{"id":"tomas","name":"Tomas Ekberg","role":"Product Manager","blurb":"Owns the enrichment integration and knows where every component runs.","knowledge":["The enrichment integration calls a third party service hosted in the United States. No EU option exists today.","Enrichment can be disabled per customer with a single setting. The core product works fine without it.","An EU processing region for enrichment is under consideration with no committed date."],"withholds":["Will not commit to a roadmap date and will not decide the deal."],"responseRules":[{"id":"rel_enrichment","priority":3,"anyKeywords":["enrichment","united states","third party","where","process","outside the eu"],"reply":"The enrichment integration calls a third party service hosted in the United States. There is no EU option for it today."},{"id":"rel_disable","priority":2,"anyKeywords":["disable","turn off","optional","without","toggle","per customer"],"reply":"Enrichment can be disabled per customer with a single setting. The core product works fine without it. The customer loses the extra company details it adds to records."},{"id":"rel_roadmap","priority":2,"anyKeywords":["roadmap","eu region","ship","when","future","timeline","plan"],"reply":"An EU processing region for enrichment is under consideration, but there is no committed date. Please do not promise a quarter."}],"fallbackReply":"I can confirm where each component runs and what enrichment does. What to offer this customer is your call."}],"questions":[{"id":"residency_risk","kind":"single_select","prompt":"What is the data residency risk for this customer?","options":["The optional enrichment integration processes data in the United States","The core database is hosted outside the EU","Reporting sends data to the United States","SSO requires a US based identity provider"],"points":30,"answer":["The optional enrichment integration processes data in the United States"],"competencyKey":"risk_identification","expectedEvidence":"The architecture note shows the core product, reporting and SSO all run in the EU. The only component that processes data in the United States is the optional enrichment integration."},{"id":"recommendation","kind":"single_select","prompt":"What do you recommend?","options":["Disable the enrichment integration for this customer","Promise an EU enrichment region by next quarter","Keep enrichment on and hope the customer does not ask","Decline the deal entirely"],"points":25,"answer":["Disable the enrichment integration for this customer"],"competencyKey":"solution_judgment","expectedEvidence":"Enrichment is optional and can be disabled per customer. Disabling it makes the deployment fully EU resident. Promising a roadmap date would be false, and declining the deal is unnecessary."},{"id":"eu_supported","kind":"multi_select","prompt":"Which components stay fully supported in the EU?","options":["Core product and database","Reporting","SSO","Data enrichment"],"points":15,"answer":["Core product and database","Reporting","SSO"],"competencyKey":"product_knowledge","expectedEvidence":"The core product and database, reporting and SSO all run in EU regions (Frankfurt and Dublin). Enrichment is the only component that does not."},{"id":"tradeoff_explanation","kind":"text","prompt":"Explain the trade-off to the customer.","helpText":"Max 400 characters. Be clear about what they keep, what they lose and what happens next.","maxChars":400,"points":20,"concepts":[{"id":"name_loss","label":"Names what is lost without enrichment","keywords":["without enrichment","lose","no enrichment","enrichment will be off","not be enriched"]},{"id":"confirm_core","label":"Confirms EU hosting for the core","keywords":["core product","frankfurt","stays in the eu","hosted in the eu","remains in the eu"]},{"id":"revisit_later","label":"Offers to revisit when an EU region ships","keywords":["revisit","eu region","re-enable","when available","if it becomes available"]},{"id":"in_writing","label":"Puts the decision in writing","keywords":["in writing","document","written","confirm by email","record the decision"]}],"competencyKey":"tradeoff_communication","expectedEvidence":"The core product, reporting and SSO all run in the EU and stay fully supported. We will disable the enrichment integration, so records will not carry the extra company details it adds. We can revisit if an EU region ships for it. I will confirm this configuration in writing."}],"competencies":[{"key":"risk_identification","label":"Risk identification"},{"key":"solution_judgment","label":"Solution judgment"},{"key":"product_knowledge","label":"Product knowledge"},{"key":"tradeoff_communication","label":"Trade-off communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication",