do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'launch-day-import';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('launch-day-import', 'implementation_consultant', 'Launch Day Import', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'implementation_consultant', title = 'Launch Day Import', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"launch-day-import","roleKey":"implementation_consultant","title":"Launch Day Import","tagline":"The customer''s data doesn''t match the system, and the launch date won''t move.","mission":"A customer goes live Monday. Their employee import file has problems, and the system rejects invalid rows silently. Decide what can launch safely, quantify the issues and tell the customer the plan.","companyName":"Brightpath Staffing (customer)","durationMinutes":5,"resources":[{"id":"import_file","title":"import.csv","kind":"table","content":"| employee_id | name | start_date | manager_email |\n| --- | --- | --- | --- |\n| E-101 | Rosa Delgado | 2026-08-03 | m.ortiz@brightpath.com |\n| E-102 | James Wu | 08/04/2026 | m.ortiz@brightpath.com |\n| E-103 | Amara Osei | 2026-08-03 | k.boyle@brightpath.com |\n| E-104 | Dan Reyes | 2026-08-05 | k.boyle@brightpath.com |\n| E-104 | Dan Reyes | 2026-08-10 | k.boyle@brightpath.com |\n| E-105 | Lena Kovac | 07/28/2026 | m.ortiz@brightpath.com |\n| E-106 | Tom Aiello | 2026-08-03 |  |\n| E-107 | Nia Brooks | 2026-08-04 | k.boyle@brightpath.com |"},{"id":"system_rules","title":"System import rules","kind":"markdown","content":"## Import requirements\n\n- `employee_id` must be **unique**\n- `manager_email` is **required** (drives approval routing)\n- `start_date` must be **YYYY-MM-DD**\n\n## Behavior\n\nRows that violate any rule are **silently skipped** by the importer. There is no error report unless you run a pre-import validation."},{"id":"timeline","title":"Launch timeline","kind":"markdown","content":"## Go-live: Monday\n\n12 new hires have contractual start dates next week. The customer has stated the launch date cannot move."}],"stakeholders":[{"id":"priya","name":"Priya Raman","role":"HR Director, Brightpath","blurb":"Owns the employee data. Under pressure to launch Monday.","knowledge":["The duplicate E-104 is a rehire. The newer row (start 2026-08-10) is correct.","Monday is contractual; a partial, safe launch is acceptable if nothing is silently lost."],"withholds":["Will not decide the import strategy."],"responseRules":[{"id":"rel_duplicate","priority":3,"anyKeywords":["duplicate","e-104","e104","two rows","twice","rehire","which row"],"reply":"Good catch. E-104 is a rehire. The newer row with the August 10 start date is the correct one."},{"id":"rel_launch","priority":2,"anyKeywords":["launch","monday","delay","date","partial","phase","deadline"],"reply":"Monday is contractual. We can''t move it. A partial launch is fine as long as nothing gets silently lost and I know exactly who''s missing."},{"id":"rel_manager","priority":2,"anyKeywords":["manager","tom","e-106","e106","missing email","blank"],"reply":"Tom Aiello''s manager just changed teams. I can get you the new manager''s email by tomorrow morning."}],"fallbackReply":"I trust your judgment on the technical side. Just tell me what will and won''t be in the system on Monday."}],"questions":[{"id":"safe_approach","kind":"single_select","prompt":"What is the safest way to handle the import before Monday?","options":["Import the clean rows now, fix and import the problem rows before Monday, and validate final counts","Import everything as-is and fix issues after launch","Delay the entire launch until the file is perfect","Delete the problem rows from the file and import the rest"],"points":30,"answer":["Import the clean rows now, fix and import the problem rows before Monday, and validate final counts"],"competencyKey":"implementation_judgment","expectedEvidence":"The importer silently skips invalid rows, so importing as-is loses people invisibly. A phased import with validation protects the launch date and the data."},{"id":"clean_count","kind":"number","prompt":"How many rows import cleanly today, with no changes?","helpText":"Count rows that pass all three rules as-is.","points":20,"answer":[4,0.5],"competencyKey":"data_integrity","expectedEvidence":"E-101, E-103 and E-107 are clean, plus one of the E-104 rows (the duplicate makes the pair invalid until resolved; 4 rows pass if the older E-104 is removed; strictly as-is: E-101, E-103, E-107 and E-104''s first occurrence). 4 rows."},{"id":"blocking_issues","kind":"multi_select","prompt":"Which issues block rows from importing?","options":["Mixed date formats (MM/DD/YYYY)","Missing manager email","Duplicate employee IDs","Names containing spaces","Too many rows in one file"],"points":15,"answer":["Mixed date formats (MM/DD/YYYY)","Missing manager email","Duplicate employee IDs"],"competencyKey":"data_integrity","expectedEvidence":"E-102 and E-105 have MM/DD/YYYY dates, E-106 is missing its manager email, and E-104 appears twice."},{"id":"customer_plan","kind":"text","prompt":"Write the plan you''d send Priya today.","helpText":"Max 400 characters. What launches Monday, what''s being fixed, and how you''ll verify nothing is lost.","maxChars":400,"points":25,"concepts":[{"id":"phased","label":"Phased import (clean rows now, fixes before Monday)","keywords":["clean rows","phase","first","then","import now","partial","today"]},{"id":"name_fixes","label":"Names the specific fixes needed","keywords":["date","manager","duplicate","e-104","e-106","format"]},{"id":"verify_counts","label":"Verifies counts so nothing is silently lost","keywords":["count","verify","validat","confirm","reconcil","check","nothing lost","missing"]}],"competencyKey":"customer_communication","expectedEvidence":"Import the 4 clean rows today. Fix the 2 date formats, get Tom''s manager email, and keep E-104''s rehire row, then import the remaining 4 before Monday. Run pre-import validation and confirm 8 unique employees in the system, so nothing is silently dropped."}],"competencies":[{"key":"implementation_judgment","label":"Implementation judgment"},{"key":"data_integrity","label":"Data integrity"},{"key":"requirements_interpretation","label":"Requirements interpretation"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"safe_approach":"Chose a phased import that protects both the launch date and the data.","clean_count":"Correctly quantified how much of the file imports cleanly today.","blocking_issues":"Identified all three defect types blocking the import.","customer_plan":"The customer plan is concrete about what launches, what''s being fixed and how it''s verified."},"improvementTemplates":{"safe_approach":"Because the importer silently skips invalid rows, the safe path is importing clean rows now and fixing the rest before Monday with validated counts.","clean_count":"4 rows import cleanly as-is; the other 4 need date fixes, a manager email, or duplicate resolution.","blocking_issues":"Three issues block rows: mixed date formats (E-102, E-105), a missing manager email (E-106), and the E-104 duplicate.","customer_plan":"A stronger plan names what imports today, lists each fix with an owner, and verifies final counts so nothing is silently lost."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"launch-day-import","roleKey":"implementation_consultant","title":"Launch Day Import","tagline":"The customer''s data doesn''t match the system, and the launch date won''t move.","mission":"A customer goes live Monday. Their employee import file has problems, and the system rejects invalid rows silently. Decide what can launch safely, quantify the issues and tell the customer the plan.","companyName":"Brightpath Staffing (customer)","durationMinutes":5,"resources":[{"id":"import_file","title":"import.csv","kind":"table","content":"| employee_id | name | start_date | manager_email |\n| --- | --- | --- | --- |\n| E-101 | Rosa Delgado | 2026-08-03 | m.ortiz@brightpath.com |\n| E-102 | James Wu | 08/04/2026 | m.ortiz@brightpath.com |\n| E-103 | Amara Osei | 2026-08-03 | k.boyle@brightpath.com |\n| E-104 | Dan Reyes | 2026-08-05 | k.boyle@brightpath.com |\n| E-104 | Dan Reyes | 2026-08-10 | k.boyle@brightpath.com |\n| E-105 | Lena Kovac | 07/28/2026 | m.ortiz@brightpath.com |\n| E-106 | Tom Aiello | 2026-08-03 |  |\n| E-107 | Nia Brooks | 2026-08-04 | k.boyle@brightpath.com |"},{"id":"system_rules","title":"System import rules","kind":"markdown","content":"## Import requirements\n\n- `employee_id` must be **unique**\n- `manager_email` is **required** (drives approval routing)\n- `start_date` must be **YYYY-MM-DD**\n\n## Behavior\n\nRows that violate any rule are **silently skipped** by the importer. There is no error report unless you run a pre-import validation."},{"id":"timeline","title":"Launch timeline","kind":"markdown","content":"## Go-live: Monday\n\n12 new hires have contractual start dates next week. The customer has stated the launch date cannot move."}],"stakeholders":[{"id":"priya","name":"Priya Raman","role":"HR Director, Brightpath","blurb":"Owns the employee data. Under pressure to launch Monday.","knowledge":["The duplicate E-104 is a rehire. The newer row (start 2026-08-10) is correct.","Monday is contractual; a partial, safe launch is acceptable if nothing is silently lost."],"withholds":["Will not decide the import strategy."],"responseRules":[{"id":"rel_duplicate","priority":3,"anyKeywords":["duplicate","e-104","e104","two rows","twice","rehire","which row"],"reply":"Good catch. E-104 is a rehire. The newer row with the August 10 start date is the correct one."},{"id":"rel_launch","priority":2,"anyKeywords":["launch","monday","delay","date","partial","phase","deadline"],"reply":"Monday is contractual. We can''t move it. A partial launch is fine as long as nothing gets silently lost and I know exactly who''s missing."},{"id":"rel_manager","priority":2,"anyKeywords":["manager","tom","e-106","e106","missing email","blank"],"reply":"Tom Aiello''s manager just changed teams. I can get you the new manager''s email by tomorrow morning."}],"fallbackReply":"I trust your judgment on the technical side. Just tell me what will and won''t be in the system on Monday."}],"questions":[{"id":"safe_approach","kind":"single_select","prompt":"What is the safest way to handle the import before Monday?","options":["Import the clean rows now, fix and import the problem rows before Monday, and validate final counts","Import everything as-is and fix issues after launch","Delay the entire launch until the file is perfect","Delete the problem rows from the file and import the rest"],"points":30,"answer":["Import the clean rows now, fix and import the problem rows before Monday, and validate final counts"],"competencyKey":"implementation_judgment","expectedEvidence":"The importer silently skips invalid rows, so importing as-is loses people invisibly. A phased import with validation protects the launch date and the data."},{"id":"clean_count","kind":"number","prompt":"How many rows import cleanly today, with no changes?","helpText":"Count rows that pass all three rules as-is.","points":20,"answer":[4,0.5],"competencyKey":"data_integrity","expectedEvidence":"E-101, E-103 and E-107 are clean, plus one of the E-104 rows (the duplicate makes the pair invalid until resolved; 4 rows pass if the older E-104 is removed; strictly as-is: E-101, E-103, E-107 and E-104''s first occurrence). 4 rows."},{"id":"blocking_issues","kind":"multi_select","prompt":"Which issues block rows from importing?","options":["Mixed date formats (MM/DD/YYYY)","Missing manager email","Duplicate employee IDs","Names containing spaces","Too many rows in one file"],"points":15,"answer":["Mixed date formats (MM/DD/YYYY)","Missing manager email","Duplicate employee IDs"],"competencyKey":"data_integrity","expectedEvidence":"E-102 and E-105 have MM/DD/YYYY dates, E-106 is missing its manager email, and E-104 appears twice."},{"id":"customer_plan","kind":"text","prompt":"Write the plan you''d send Priya today.","helpText":"Max 400 characters. What launches Monday, what''s being fixed, and how you''ll verify nothing is lost.","maxChars":400,"points":25,"concepts":[{"id":"phased","label":"Phased import (clean rows now, fixes before Monday)","keywords":["clean rows","phase","first","then","import now","partial","today"]},{"id":"name_fixes","label":"Names the specific fixes needed","keywords":["date","manager","duplicate","e-104","e-106","format"]},{"id":"verify_counts","label":"Verifies counts so nothing is silently lost","keywords":["count","verify","validat","confirm","reconcil","check","nothing lost","missing"]}],"competencyKey":"customer_communication","expectedEvidence":"Import the 4 clean rows today. Fix the 2 date formats, get Tom''s manager email, and keep E-104''s rehire row, then import the remaining 4 before Monday. Run pre-import validation and confirm 8 unique employees in the system, so nothing is silently dropped."}],"competencies":[{"key":"implementation_judgment","label":"Implementation judgment"},{"key":"data_integrity","label":"Data integrity"},{"key":"requirements_interpretation","label":"Requirements interpretation"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"safe_approach":"Chose a phased import that protects both the launch date and the data.","clean_count":"Correctly quantified how much of the file imports cleanly today.","blocking_issues":"Identified all three defect types blocking the import.","customer_plan":"The customer plan is concrete about what launches, what''s being fixed and how it''s verified."},"improvementTemplates":{"safe_approach":"Because the importer silently skips invalid rows, the safe path is importing clean rows now and fixing the rest before Monday with validated counts.","clean_count":"4 rows import cleanly as-is; the other 4 need date fixes, a manager email, or duplicate resolution.","blocking_issues":"Three issues block rows: mixed date formats (E-102, E-105), a missing manager email (E-106), and the E-104 duplicate.","customer_plan":"A stronger plan names what imports today, lists each fix with an owner, and verifies final counts so nothing is silently lost."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

do $$
declare
  t_id uuid;
