  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"duplicate-accounts","roleKey":"implementation_consultant","title":"Duplicate Accounts","tagline":"The migration created two of everything it should not have.","mission":"After a migration, Crestwick Supply is seeing duplicate accounts. Matching used company names instead of the stable external ID. Find the root cause, count the damage and propose a plan that does not destroy data.","companyName":"Crestwick Supply (customer)","durationMinutes":5,"resources":[{"id":"accounts","title":"accounts table","kind":"table","content":"| record | company_name | external_id |\n| --- | --- | --- |\n| R-1 | Acme Corp | EXT-100 |\n| R-2 | ACME Corporation | EXT-100 |\n| R-3 | Delta Freight | EXT-101 |\n| R-4 | Bluepine | EXT-104 |\n| R-5 | Bluepine Ltd | EXT-104 |\n| R-6 | Harrow Media | EXT-102 |"},{"id":"matching_rule","title":"Matching rule note","kind":"markdown","content":"## How the migration matched records\n\nThe import matched existing accounts by company_name, exact text match. The external_id field comes from the customer''s billing system and is unique per company. It was not used for matching."}],"stakeholders":[{"id":"elena","name":"Elena Voss","role":"Operations Manager, Crestwick Supply","blurb":"Owns the account data. Nervous about anything being deleted.","knowledge":["The external_id comes from the billing system, is unique per company and is never reused.","Some duplicate records have open orders attached, so nothing can be deleted automatically.","Wants one record per real company and to see anything questionable before it merges."],"withholds":["Does not know the matching logic and will not design the fix."],"responseRules":[{"id":"rel_source","priority":3,"anyKeywords":["external","ext-","billing","stable","unique","identifier","reuse"],"reply":"The external_id comes from our billing system. It is unique per company and never reused. Company names get typed by hand."},{"id":"rel_delete","priority":2,"anyKeywords":["delete","remove","merge","destroy","lose","safe","open orders"],"reply":"Please do not delete anything automatically. Some of those records have open orders attached."},{"id":"rel_goal","priority":2,"anyKeywords":["goal","want","expect","clean","outcome","success","end state"],"reply":"One record per real company, nothing lost, and I want to see anything questionable before it gets merged."}],"fallbackReply":"I know our companies, not your matching logic. Show me a specific pair and I can tell you if they are the same business."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is the root cause of the duplicates?","options":["Matching used the company name instead of the stable external ID","The billing system exported the same company twice","The import ran twice by mistake","External IDs were reused across companies"],"points":30,"answer":["Matching used the company name instead of the stable external ID"],"competencyKey":"root_cause_analysis","expectedEvidence":"The import matched on exact company_name text. Acme Corp and ACME Corporation are the same company (EXT-100) spelled differently, so name matching created a second record. The unique external_id was never used."},{"id":"duplicate_pairs","kind":"number","prompt":"How many pairs of records share the same external_id?","helpText":"Count pairs, not individual rows.","points":25,"answer":[2,0],"competencyKey":"data_accuracy","expectedEvidence":"EXT-100 appears on R-1 and R-2 (Acme Corp / ACME Corporation), and EXT-104 appears on R-4 and R-5 (Bluepine / Bluepine Ltd). That is 2 duplicate pairs to review."},{"id":"safe_approach","kind":"single_select","prompt":"What is the safe approach to fixing the duplicates?","options":["Merge by external ID and send uncertain matches to a review queue","Auto-delete every record with a repeated external ID","Keep all records and rename the duplicates","Re-run the same import and hope it matches better"],"points":15,"answer":["Merge by external ID and send uncertain matches to a review queue"],"competencyKey":"migration_judgment","expectedEvidence":"The external_id is unique and stable, so it is the correct merge key. Records may have open orders attached, so automatic deletion is unsafe and human review is required for anything uncertain."},{"id":"migration_plan","kind":"text","prompt":"Write the migration fix plan.","helpText":"Max 400 characters. How you will merge, what a human reviews and how you prove nothing was lost.","maxChars":400,"points":20,"concepts":[{"id":"match_external_id","label":"Matches on the external ID","keywords":["external id","external_id","stable id","billing id"]},{"id":"review_queue","label":"Queues ambiguous matches for human review","keywords":["review","human","queue","manually check","approve each"]},{"id":"no_auto_delete","label":"Avoids destructive automatic merging","keywords":["not delete","no automatic delet","never auto","avoid delet","non-destructive"]},{"id":"verify_counts","label":"Verifies record counts after","keywords":["count","verify","reconcil","after the merge","confirm totals"]}],"competencyKey":"plan_quality","expectedEvidence":"Re-match every account on external_id, the unique billing key. Merge exact external_id pairs, and queue any ambiguous match for Elena to review. Do not delete records automatically since some carry open orders. After merging, verify counts: 6 records should become 4 unique companies."}],"competencies":[{"key":"root_cause_analysis","label":"Root-cause analysis"},{"key":"data_accuracy","label":"Data accuracy"},{"key":"migration_judgment","label":"Migration judgment"},{"key":"plan_quality","label":"Plan quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Traced the duplicates to name matching instead of the stable external ID.","duplicate_pairs":"Counted the duplicate pairs correctly from the account data.","safe_approach":"Chose a merge strategy keyed on external ID with human review, not deletion.","migration_plan":"The plan merges on the right key, protects data and verifies the outcome."},"improvementTemplates":{"root_cause":"The root cause is the matching rule: it used exact company name text, while the unique external_id from the billing system was ignored.","duplicate_pairs":"There are 2 duplicate pairs: EXT-100 (Acme Corp and ACME Corporation) and EXT-104 (Bluepine and Bluepine Ltd).","safe_approach":"The safe approach is merging by external ID with a review queue for anything uncertain. Automatic deletion is unsafe because records carry open orders.","migration_plan":"A stronger plan matches on external_id, queues ambiguous pairs for human review, avoids automatic deletion and verifies record counts after the merge."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"duplicate-accounts","roleKey":"implementation_consultant","title":"Duplicate Accounts","tagline":"The migration created two of everything it should not have.","mission":"After a migration, Crestwick Supply is seeing duplicate accounts. Matching used company names instead of the stable external ID. Find the root cause, count the damage and propose a plan that does not destroy data.","companyName":"Crestwick Supply (customer)","durationMinutes":5,"resources":[{"id":"accounts","title":"accounts table","kind":"table","content":"| record | company_name | external_id |\n| --- | --- | --- |\n| R-1 | Acme Corp | EXT-100 |\n| R-2 | ACME Corporation | EXT-100 |\n| R-3 | Delta Freight | EXT-101 |\n| R-4 | Bluepine | EXT-104 |\n| R-5 | Bluepine Ltd | EXT-104 |\n| R-6 | Harrow Media | EXT-102 |"},{"id":"matching_rule","title":"Matching rule note","kind":"markdown","content":"## How the migration matched records\n\nThe import matched existing accounts by company_name, exact text match. The external_id field comes from the customer''s billing system and is unique per company. It was not used for matching."}],"stakeholders":[{"id":"elena","name":"Elena Voss","role":"Operations Manager, Crestwick Supply","blurb":"Owns the account data. Nervous about anything being deleted.","knowledge":["The external_id comes from the billing system, is unique per company and is never reused.","Some duplicate records have open orders attached, so nothing can be deleted automatically.","Wants one record per real company and to see anything questionable before it merges."],"withholds":["Does not know the matching logic and will not design the fix."],"responseRules":[{"id":"rel_source","priority":3,"anyKeywords":["external","ext-","billing","stable","unique","identifier","reuse"],"reply":"The external_id comes from our billing system. It is unique per company and never reused. Company names get typed by hand."},{"id":"rel_delete","priority":2,"anyKeywords":["delete","remove","merge","destroy","lose","safe","open orders"],"reply":"Please do not delete anything automatically. Some of those records have open orders attached."},{"id":"rel_goal","priority":2,"anyKeywords":["goal","want","expect","clean","outcome","success","end state"],"reply":"One record per real company, nothing lost, and I want to see anything questionable before it gets merged."}],"fallbackReply":"I know our companies, not your matching logic. Show me a specific pair and I can tell you if they are the same business."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is the root cause of the duplicates?","options":["Matching used the company name instead of the stable external ID","The billing system exported the same company twice","The import ran twice by mistake","External IDs were reused across companies"],"points":30,"answer":["Matching used the company name instead of the stable external ID"],"competencyKey":"root_cause_analysis","expectedEvidence":"The import matched on exact company_name text. Acme Corp and ACME Corporation are the same company (EXT-100) spelled differently, so name matching created a second record. The unique external_id was never used."},{"id":"duplicate_pairs","kind":"number","prompt":"How many pairs of records share the same external_id?","helpText":"Count pairs, not individual rows.","points":25,"answer":[2,0],"competencyKey":"data_accuracy","expectedEvidence":"EXT-100 appears on R-1 and R-2 (Acme Corp / ACME Corporation), and EXT-104 appears on R-4 and R-5 (Bluepine / Bluepine Ltd). That is 2 duplicate pairs to review."},{"id":"safe_approach","kind":"single_select","prompt":"What is the safe approach to fixing the duplicates?","options":["Merge by external ID and send uncertain matches to a review queue","Auto-delete every record with a repeated external ID","Keep all records and rename the duplicates","Re-run the same import and hope it matches better"],"points":15,"answer":["Merge by external ID and send uncertain matches to a review queue"],"competencyKey":"migration_judgment","expectedEvidence":"The external_id is unique and stable, so it is the correct merge key. Records may have open orders attached, so automatic deletion is unsafe and human review is required for anything uncertain."},{"id":"migration_plan","kind":"text","prompt":"Write the migration fix plan.","helpText":"Max 400 characters. How you will merge, what a human reviews and how you prove nothing was lost.","maxChars":400,"points":20,"concepts":[{"id":"match_external_id","label":"Matches on the external ID","keywords":["external id","external_id","stable id","billing id"]},{"id":"review_queue","label":"Queues ambiguous matches for human review","keywords":["review","human","queue","manually check","approve each"]},{"id":"no_auto_delete","label":"Avoids destructive automatic merging","keywords":["not delete","no automatic delet","never auto","avoid delet","non-destructive"]},{"id":"verify_counts","label":"Verifies record counts after","keywords":["count","verify","reconcil","after the merge","confirm totals"]}],"competencyKey":"plan_quality","expectedEvidence":"Re-match every account on external_id, the unique billing key. Merge exact external_id pairs, and queue any ambiguous match for Elena to review. Do not delete records automatically since some carry open orders. After merging, verify counts: 6 records should become 4 unique companies."}],"competencies":[{"key":"root_cause_analysis","label":"Root-cause analysis"},{"key":"data_accuracy","label":"Data accuracy"},{"key":"migration_judgment","label":"Migration judgment"},{"key":"plan_quality","label":"Plan quality"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Traced the duplicates to name matching instead of the stable external ID.","duplicate_pairs":"Counted the duplicate pairs correctly from the account data.","safe_approach":"Chose a merge strategy keyed on external ID with human review, not deletion.","migration_plan":"The plan merges on the right key, protects data and verifies the outcome."},"improvementTemplates":{"root_cause":"The root cause is the matching rule: it used exact company name text, while the unique external_id from the billing system was ignored.","duplicate_pairs":"There are 2 duplicate pairs: EXT-100 (Acme Corp and ACME Corporation) and EXT-104 (Bluepine and Bluepine Ltd).","safe_approach":"The safe approach is merging by external ID with a review queue for anything uncertain. Automatic deletion is unsafe because records carry open orders.","migration_plan":"A stronger plan matches on external_id, queues ambiguous pairs for human review, avoids automatic deletion and verifies record counts after the merge."}}'::jsonb,
