do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'approval-rules';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('approval-rules', 'implementation_consultant', 'Approval Rules', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'implementation_consultant', title = 'Approval Rules', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"approval-rules","roleKey":"implementation_consultant","title":"Approval Rules","tagline":"Two departments, one threshold, zero agreement.","mission":"Finance and Operations gave conflicting answers about who approves purchases above $10,000. The configuration is blocked until someone decides. Diagnose the real problem and write the message that unblocks it.","companyName":"Meridale Foods (customer)","durationMinutes":5,"resources":[{"id":"finance_email","title":"Email from Finance","kind":"markdown","content":"## Email from Finance\n\nFrom: R. Calloway, Finance Controller\n\nAny purchase above $10,000 must be approved by the controller. This was agreed at kickoff and it matches our audit requirements."},{"id":"operations_email","title":"Email from Operations","kind":"markdown","content":"## Email from Operations\n\nFrom: D. Munro, Operations Director\n\nPurchases above $10,000 should go to the department head. Routing them to Finance adds two days to every order. This is what we asked for in discovery."},{"id":"workflow_config","title":"Current workflow configuration","kind":"table","content":"| Purchase amount | Approver |\n| --- | --- |\n| Up to $10,000 | Department head |\n| Above $10,000 | Not configured, decision pending |"}],"stakeholders":[{"id":"marcus","name":"Marcus Hale","role":"Project Sponsor, Meridale Foods","blurb":"Sponsors the rollout. Wants the dispute settled without taking sides.","knowledge":["The steering committee formally owns process decisions, but nobody has put this one in front of them.","In the old system the controller approved everything over $10,000, and Operations found it slow.","Configuration freeze is in two weeks. An undecided rule becomes a launch risk."],"withholds":["Will not pick a side himself."],"responseRules":[{"id":"rel_owner","priority":3,"anyKeywords":["who decide","owner","authority","final say","steering","sign off","who owns"],"reply":"Good question. Formally the steering committee owns process decisions, but nobody has put this one in front of them yet."},{"id":"rel_history","priority":2,"anyKeywords":["before","previous","old system","used to","legacy","today","current process"],"reply":"In the old system the controller approved everything over ten thousand dollars, but Operations always felt that slowed them down."},{"id":"rel_deadline","priority":2,"anyKeywords":["deadline","when","launch","timeline","block","freeze","how long"],"reply":"Configuration freeze is in two weeks. If this is not decided by then it becomes a launch risk."}],"fallbackReply":"I want this settled quickly. Tell me what you need from me to move it forward."}],"questions":[{"id":"real_problem","kind":"single_select","prompt":"What is the real problem here?","options":["An unresolved requirement conflict, not a configuration bug","The workflow engine cannot route purchases above $10,000","Finance entered the wrong threshold","Operations misread the configuration screen"],"points":30,"answer":["An unresolved requirement conflict, not a configuration bug"],"competencyKey":"problem_framing","expectedEvidence":"The system works and the threshold is agreed. The two departments gave contradictory answers about the approver, so the requirement itself is unresolved."},{"id":"next_step","kind":"single_select","prompt":"What is the right next step?","options":["Ask who owns this decision and get the answer in writing","Configure the controller as approver since Finance sounded more certain","Configure both approvers and let the system pick","Wait for the two directors to work it out themselves"],"points":25,"answer":["Ask who owns this decision and get the answer in writing"],"competencyKey":"decision_process","expectedEvidence":"A consultant should not arbitrate between departments. The path forward is identifying the decision owner (the steering committee) and getting a written decision before the configuration freeze."},{"id":"document_items","kind":"multi_select","prompt":"Once decided, what should be documented?","options":["The chosen approval rule","The name of the decision owner","Acceptance test cases for the rule","The full email history of the disagreement","A list of every purchase from last year"],"points":15,"answer":["The chosen approval rule","The name of the decision owner","Acceptance test cases for the rule"],"competencyKey":"requirements_documentation","expectedEvidence":"Documenting the chosen rule, who decided it and the acceptance tests that prove it works prevents the same dispute from reopening. Email archaeology and old purchase lists add nothing."},{"id":"clarification_message","kind":"text","prompt":"Write the clarification message to the customer.","helpText":"Max 400 characters. Neutral, specific and designed to produce one decision.","maxChars":400,"points":20,"concepts":[{"id":"neutral_framing","label":"Names the conflict neutrally","keywords":["two different","conflicting","disagree","both teams","received different"]},{"id":"single_owner","label":"Asks for a single decision owner","keywords":["decision owner","one owner","who owns","single decision","final say"]},{"id":"propose_deadline","label":"Proposes a deadline","keywords":["by ","deadline","freeze","within a week","before the"]},{"id":"either_outcome","label":"Offers to configure either outcome","keywords":["either","both options","whichever","configure it either way","ready to configure"]}],"competencyKey":"clarification_writing","expectedEvidence":"We received two different answers on who approves purchases above $10,000: Finance named the controller, Operations named the department head. Could you confirm a single decision owner for this rule? A decision by next Friday keeps us ahead of the configuration freeze. We can configure either outcome the same day."}],"competencies":[{"key":"problem_framing","label":"Problem framing"},{"key":"decision_process","label":"Decision process"},{"key":"requirements_documentation","label":"Requirements documentation"},{"key":"clarification_writing","label":"Clarification writing"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"real_problem":"Framed the issue as an unresolved requirement rather than a system defect.","next_step":"Routed the decision to its owner instead of arbitrating between departments.","document_items":"Chose exactly the documentation that prevents the dispute from reopening.","clarification_message":"The message is neutral, names one owner and drives a dated decision."},"improvementTemplates":{"real_problem":"The real problem is an unresolved requirement conflict. The system and threshold are fine; the two departments disagree on the approver.","next_step":"The right next step is asking who owns the decision and getting the answer in writing. The steering committee owns process decisions and has not been asked.","document_items":"Document the chosen rule, the decision owner and acceptance test cases. That combination stops the dispute from reopening after launch.","clarification_message":"A stronger message names the conflict neutrally, asks for a single decision owner, proposes a deadline before the freeze and offers to configure either outcome."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"approval-rules","roleKey":"implementation_consultant","title":"Approval Rules","tagline":"Two departments, one threshold, zero agreement.","mission":"Finance and Operations gave conflicting answers about who approves purchases above $10,000. The configuration is blocked until someone decides. Diagnose the real problem and write the message that unblocks it.","companyName":"Meridale Foods (customer)","durationMinutes":5,"resources":[{"id":"finance_email","title":"Email from Finance","kind":"markdown","content":"## Email from Finance\n\nFrom: R. Calloway, Finance Controller\n\nAny purchase above $10,000 must be approved by the controller. This was agreed at kickoff and it matches our audit requirements."},{"id":"operations_email","title":"Email from Operations","kind":"markdown","content":"## Email from Operations\n\nFrom: D. Munro, Operations Director\n\nPurchases above $10,000 should go to the department head. Routing them to Finance adds two days to every order. This is what we asked for in discovery."},{"id":"workflow_config","title":"Current workflow configuration","kind":"table","content":"| Purchase amount | Approver |\n| --- | --- |\n| Up to $10,000 | Department head |\n| Above $10,000 | Not configured, decision pending |"}],"stakeholders":[{"id":"marcus","name":"Marcus Hale","role":"Project Sponsor, Meridale Foods","blurb":"Sponsors the rollout. Wants the dispute settled without taking sides.","knowledge":["The steering committee formally owns process decisions, but nobody has put this one in front of them.","In the old system the controller approved everything over $10,000, and Operations found it slow.","Configuration freeze is in two weeks. An undecided rule becomes a launch risk."],"withholds":["Will not pick a side himself."],"responseRules":[{"id":"rel_owner","priority":3,"anyKeywords":["who decide","owner","authority","final say","steering","sign off","who owns"],"reply":"Good question. Formally the steering committee owns process decisions, but nobody has put this one in front of them yet."},{"id":"rel_history","priority":2,"anyKeywords":["before","previous","old system","used to","legacy","today","current process"],"reply":"In the old system the controller approved everything over ten thousand dollars, but Operations always felt that slowed them down."},{"id":"rel_deadline","priority":2,"anyKeywords":["deadline","when","launch","timeline","block","freeze","how long"],"reply":"Configuration freeze is in two weeks. If this is not decided by then it becomes a launch risk."}],"fallbackReply":"I want this settled quickly. Tell me what you need from me to move it forward."}],"questions":[{"id":"real_problem","kind":"single_select","prompt":"What is the real problem here?","options":["An unresolved requirement conflict, not a configuration bug","The workflow engine cannot route purchases above $10,000","Finance entered the wrong threshold","Operations misread the configuration screen"],"points":30,"answer":["An unresolved requirement conflict, not a configuration bug"],"competencyKey":"problem_framing","expectedEvidence":"The system works and the threshold is agreed. The two departments gave contradictory answers about the approver, so the requirement itself is unresolved."},{"id":"next_step","kind":"single_select","prompt":"What is the right next step?","options":["Ask who owns this decision and get the answer in writing","Configure the controller as approver since Finance sounded more certain","Configure both approvers and let the system pick","Wait for the two directors to work it out themselves"],"points":25,"answer":["Ask who owns this decision and get the answer in writing"],"competencyKey":"decision_process","expectedEvidence":"A consultant should not arbitrate between departments. The path forward is identifying the decision owner (the steering committee) and getting a written decision before the configuration freeze."},{"id":"document_items","kind":"multi_select","prompt":"Once decided, what should be documented?","options":["The chosen approval rule","The name of the decision owner","Acceptance test cases for the rule","The full email history of the disagreement","A list of every purchase from last year"],"points":15,"answer":["The chosen approval rule","The name of the decision owner","Acceptance test cases for the rule"],"competencyKey":"requirements_documentation","expectedEvidence":"Documenting the chosen rule, who decided it and the acceptance tests that prove it works prevents the same dispute from reopening. Email archaeology and old purchase lists add nothing."},{"id":"clarification_message","kind":"text","prompt":"Write the clarification message to the customer.","helpText":"Max 400 characters. Neutral, specific and designed to produce one decision.","maxChars":400,"points":20,"concepts":[{"id":"neutral_framing","label":"Names the conflict neutrally","keywords":["two different","conflicting","disagree","both teams","received different"]},{"id":"single_owner","label":"Asks for a single decision owner","keywords":["decision owner","one owner","who owns","single decision","final say"]},{"id":"propose_deadline","label":"Proposes a deadline","keywords":["by ","deadline","freeze","within a week","before the"]},{"id":"either_outcome","label":"Offers to configure either outcome","keywords":["either","both options","whichever","configure it either way","ready to configure"]}],"competencyKey":"clarification_writing","expectedEvidence":"We received two different answers on who approves purchases above $10,000: Finance named the controller, Operations named the department head. Could you confirm a single decision owner for this rule? A decision by next Friday keeps us ahead of the configuration freeze. We can configure either outcome the same day."}],"competencies":[{"key":"problem_framing","label":"Problem framing"},{"key":"decision_process","label":"Decision process"},{"key":"requirements_documentation","label":"Requirements documentation"},{"key":"clarification_writing","label":"Clarification writing"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"real_problem":"Framed the issue as an unresolved requirement rather than a system defect.","next_step":"Routed the decision to its owner instead of arbitrating between departments.","document_items":"Chose exactly the documentation that prevents the dispute from reopening.","clarification_message":"The message is neutral, names one owner and drives a dated decision."},"improvementTemplates":{"real_problem":"The real problem is an unresolved requirement conflict. The system and threshold are fine; the two departments disagree on the approver.","next_step":"The right next step is asking who owns the decision and getting the answer in writing. The steering committee owns process decisions and has not been asked.","document_items":"Document the chosen rule, the decision owner and acceptance test cases. That combination stops the dispute from reopening after launch.","clarification_message":"A stronger message names the conflict neutrally, asks for a single decision owner, proposes a deadline before the freeze and offers to configure either outcome."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'migration-cutover';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('migration-cutover', 'implementation_consultant', 'Migration Cutover', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'implementation_consultant', title = 'Migration Cutover', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"migration-cutover","roleKey":"implementation_consultant","title":"Migration Cutover","tagline":"The customer wants to launch Friday with no way back.","mission":"Aldergate Clinics wants to migrate on Friday and sees no need for a rollback plan. The launch checklist is empty. Assess the risk, decide what must exist before go-live and set the conditions without losing the customer.","companyName":"Aldergate Clinics (customer)","durationMinutes":5,"resources":[{"id":"cutover_request","title":"Cutover request note","kind":"markdown","content":"## Cutover request from Aldergate Clinics\n\nWe want to migrate on Friday evening. Our data is clean, so we do not need a rollback plan. Staff arrive Monday morning and must use the new system."},{"id":"launch_checklist","title":"Launch checklist","kind":"table","content":"| Item | Status |\n| --- | --- |\n| Verified backup of the current system | Not done |\n| Rollback procedure | Not done |\n| Post-migration validation checks | Not done |\n| Weekend support coverage | Not done |"}],"stakeholders":[{"id":"sofia","name":"Sofia Brandt","role":"IT Manager, Aldergate Clinics","blurb":"Owns the cutover on the customer side. Confident, but open to reason.","knowledge":["Friday gives the weekend as a buffer before staff arrive Monday. The date came from the clinic directors.","The old system can produce a full export, but nobody has run and verified one yet.","Has not thought through what happens if the migration fails."],"withholds":["Will not volunteer that the rollback assumption is untested."],"responseRules":[{"id":"rel_date","priority":3,"anyKeywords":["friday","why","date","weekend","deadline","move","monday"],"reply":"Friday gives us the weekend as a buffer before staff arrive Monday. The date came from our clinic directors and is hard to move."},{"id":"rel_backup","priority":2,"anyKeywords":["backup","copy","snapshot","export","old system","keep"],"reply":"The old system can produce a full export. To be honest, nobody has actually run and verified one yet."},{"id":"rel_rollback","priority":2,"anyKeywords":["rollback","fail","revert","go wrong","plan b","fallback","way back"],"reply":"Honestly, we assumed the migration would just work. If you think we need a way back, tell me what that involves."}],"fallbackReply":"I can get you access or people on our side. Tell me exactly what you need before Friday."}],"questions":[{"id":"biggest_risk","kind":"single_select","prompt":"What is the biggest risk in this cutover plan?","options":["There is no way back if the migration fails","Friday is a bad day of the week to migrate","The staff might not like the new system","The data volume is too large to move in one weekend"],"points":30,"answer":["There is no way back if the migration fails"],"competencyKey":"risk_identification","expectedEvidence":"The customer explicitly declined a rollback plan and no verified backup exists. If the migration fails, clinics open Monday with no working system and no way to restore the old one."},{"id":"required_items","kind":"multi_select","prompt":"What must exist before go-live?","options":["A verified backup of the current system","A rollback procedure","Post-migration validation checks","A new training video for staff","A larger project budget"],"points":25,"answer":["A verified backup of the current system","A rollback procedure","Post-migration validation checks"],"competencyKey":"launch_readiness","expectedEvidence":"A verified backup, a rollback procedure and post-migration validation checks are the safety items on the launch checklist, and all are currently not done. Training videos and budget are not launch blockers."},{"id":"go_no_go","kind":"single_select","prompt":"As of right now, what is the go/no-go call?","options":["No-go until the checklist items are done","Go, the customer says the data is clean","Go, and write the rollback plan after launch","Cancel the migration entirely"],"points":15,"answer":["No-go until the checklist items are done"],"competencyKey":"go_no_go_judgment","expectedEvidence":"Every checklist item is not done, so launching now is unsafe. The call is conditional: no-go until the items exist, which can still happen before Friday."},{"id":"launch_conditions","kind":"text","prompt":"Write the message that sets the launch conditions.","helpText":"Max 400 characters. Conditions, not refusal. Keep Friday alive if the work gets done.","maxChars":400,"points":20,"concepts":[{"id":"conditions_not_refusal","label":"States conditions, not refusal","keywords":["condition","if we complete","provided","as long as","requires"]},{"id":"rollback_trigger","label":"Defines the rollback trigger","keywords":["rollback","restore the old","revert if","trigger","way back"]},{"id":"validation_window","label":"Proposes a validation window","keywords":["validation","verify","check the data","spot check","over the weekend"]},{"id":"keep_date","label":"Keeps the date if the checklist completes","keywords":["friday","keep the date","on schedule","still go live","stay on track"]}],"competencyKey":"expectation_setting","expectedEvidence":"We can keep Friday on one condition: the checklist is done first. That means a verified backup, a rollback procedure and validation checks. If validation fails Saturday, we restore the old system, which is the rollback trigger. Complete these by Thursday and Friday still works."}],"competencies":[{"key":"risk_identification","label":"Risk identification"},{"key":"launch_readiness","label":"Launch readiness"},{"key":"go_no_go_judgment","label":"Go/no-go judgment"},{"key":"expectation_setting","label":"Expectation setting"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"biggest_risk":"Identified the missing rollback path as the risk that dwarfs all others.","required_items":"Selected exactly the safety items that must exist before go-live.","go_no_go":"Made a conditional no-go call instead of rubber-stamping or cancelling.","launch_conditions":"The message sets clear conditions while keeping the Friday date achievable."},"improvementTemplates":{"biggest_risk":"The biggest risk is having no way back. There is no verified backup and no rollback procedure, so a failed migration leaves the clinics with nothing on Monday.","required_items":"Before go-live: a verified backup, a rollback procedure and post-migration validation checks. All three are on the checklist and all are currently not done.","go_no_go":"The call is no-go until the checklist items exist. That is a condition, not a cancellation; the work can still finish before Friday.","launch_conditions":"A stronger message frames conditions rather than refusal, defines when a rollback triggers, proposes a validation window and keeps Friday if the checklist completes."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"migration-cutover","roleKey":"implementation_consultant","title":"Migration Cutover","tagline":"The customer wants to launch Friday with no way back.","mission":"Aldergate Clinics wants to migrate on Friday and sees no need for a rollback plan. The launch checklist is empty. Assess the risk, decide what must exist before go-live and set the conditions without losing the customer.","companyName":"Aldergate Clinics (customer)","durationMinutes":5,"resources":[{"id":"cutover_request","title":"Cutover request note","kind":"markdown","content":"## Cutover request from Aldergate Clinics\n\nWe want to migrate on Friday evening. Our data is clean, so we do not need a rollback plan. Staff arrive Monday morning and must use the new system."},{"id":"launch_checklist","title":"Launch checklist","kind":"table","content":"| Item | Status |\n| --- | --- |\n| Verified backup of the current system | Not done |\n| Rollback procedure | Not done |\n| Post-migration validation checks | Not done |\n| Weekend support coverage | Not done |"}],"stakeholders":[{"id":"sofia","name":"Sofia Brandt","role":"IT Manager, Aldergate Clinics","blurb":"Owns the cutover on the customer side. Confident, but open to reason.","knowledge":["Friday gives the weekend as a buffer before staff arrive Monday. The date came from the clinic directors.","The old system can produce a full export, but nobody has run and verified one yet.","Has not thought through what happens if the migration fails."],"withholds":["Will not volunteer that the rollback assumption is untested."],"responseRules":[{"id":"rel_date","priority":3,"anyKeywords":["friday","why","date","weekend","deadline","move","monday"],"reply":"Friday gives us the weekend as a buffer before staff arrive Monday. The date came from our clinic directors and is hard to move."},{"id":"rel_backup","priority":2,"anyKeywords":["backup","copy","snapshot","export","old system","keep"],"reply":"The old system can produce a full export. To be honest, nobody has actually run and verified one yet."},{"id":"rel_rollback","priority":2,"anyKeywords":["rollback","fail","revert","go wrong","plan b","fallback","way back"],"reply":"Honestly, we assumed the migration would just work. If you think we need a way back, tell me what that involves."}],"fallbackReply":"I can get you access or people on our side. Tell me exactly what you need before Friday."}],"questions":[{"id":"biggest_risk","kind":"single_select","prompt":"What is the biggest risk in this cutover plan?","options":["There is no way back if the migration fails","Friday is a bad day of the week to migrate","The staff might not like the new system","The data volume is too large to move in one weekend"],"points":30,"answer":["There is no way back if the migration fails"],"competencyKey":"risk_identification","expectedEvidence":"The customer explicitly declined a rollback plan and no verified backup exists. If the migration fails, clinics open Monday with no working system and no way to restore the old one."},{"id":"required_items","kind":"multi_select","prompt":"What must exist before go-live?","options":["A verified backup of the current system","A rollback procedure","Post-migration validation checks","A new training video for staff","A larger project budget"],"points":25,"answer":["A verified backup of the current system","A rollback procedure","Post-migration validation checks"],"competencyKey":"launch_readiness","expectedEvidence":"A verified backup, a rollback procedure and post-migration validation checks are the safety items on the launch checklist, and all are currently not done. Training videos and budget are not launch blockers."},{"id":"go_no_go","kind":"single_select","prompt":"As of right now, what is the go/no-go call?","options":["No-go until the checklist items are done","Go, the customer says the data is clean","Go, and write the rollback plan after launch","Cancel the migration entirely"],"points":15,"answer":["No-go until the checklist items are done"],"competencyKey":"go_no_go_judgment","expectedEvidence":"Every checklist item is not done, so launching now is unsafe. The call is conditional: no-go until the items exist, which can still happen before Friday."},{"id":"launch_conditions","kind":"text","prompt":"Write the message that sets the launch conditions.","helpText":"Max 400 characters. Conditions, not refusal. Keep Friday alive if the work gets done.","maxChars":400,"points":20,"concepts":[{"id":"conditions_not_refusal","label":"States conditions, not refusal","keywords":["condition","if we complete","provided","as long as","requires"]},{"id":"rollback_trigger","label":"Defines the rollback trigger","keywords":["rollback","restore the old","revert if","trigger","way back"]},{"id":"validation_window","label":"Proposes a validation window","keywords":["validation","verify","check the data","spot check","over the weekend"]},{"id":"keep_date","label":"Keeps the date if the checklist completes","keywords":["friday","keep the date","on schedule","still go live","stay on track"]}],"competencyKey":"expectation_setting","expectedEvidence":"We can keep Friday on one condition: the checklist is done first. That means a verified backup, a rollback procedure and validation checks. If validation fails Saturday, we restore the old system, which is the rollback trigger. Complete these by Thursday and Friday still works."}],"competencies":[{"key":"risk_identification","label":"Risk identification"},{"key":"launch_readiness","label":"Launch readiness"},{"key":"go_no_go_judgment","label":"Go/no-go judgment"},{"key":"expectation_setting","label":"Expectation setting"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"biggest_risk":"Identified the missing rollback path as the risk that dwarfs all others.","required_items":"Selected exactly the safety items that must exist before go-live.","go_no_go":"Made a conditional no-go call instead of rubber-stamping or cancelling.","launch_conditions":"The message sets clear conditions while keeping the Friday date achievable."},"improvementTemplates":{"biggest_risk":"The biggest risk is having no way back. There is no verified backup and no rollback procedure, so a failed migration leaves the clinics with nothing on Monday.","required_items":"Before go-live: a verified backup, a rollback procedure and post-migration validation checks. All three are on the checklist and all are currently not done.","go_no_go":"The call is no-go until the checklist items exist. That is a condition, not a cancellation; the work can still finish before Friday.","launch_conditions":"A stronger message frames conditions rather than refusal, defines when a rollback triggers, proposes a validation window and keeps Friday if the checklist completes."}}'::jsonb,
