do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'scope-tradeoff';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('scope-tradeoff', 'implementation_consultant', 'The Scope Trade-off', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'implementation_consultant', title = 'The Scope Trade-off', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"scope-tradeoff","roleKey":"implementation_consultant","title":"The Scope Trade-off","tagline":"The date will not move. The scope has to.","mission":"Penrose Retail''s launch date is fixed and two optional features are unfinished. The contract only requires the core workflow at launch. Decide what to protect, what to defer and how to tell the customer.","companyName":"Penrose Retail (customer)","durationMinutes":5,"resources":[{"id":"scope_table","title":"Scope status","kind":"table","content":"| Work item | Contract status | Progress |\n| --- | --- | --- |\n| Core data import | Required at launch | Done |\n| Approval workflow | Required at launch | Done |\n| Custom notifications | Optional add-on | 60% complete |\n| Branded portal | Optional add-on | 40% complete |"},{"id":"contract_note","title":"Contract note","kind":"markdown","content":"## Contract note\n\nThe launch date is fixed and tied to Penrose Retail''s fiscal year start. The contract requires the core data import and the approval workflow at launch. Custom notifications and the branded portal are optional add-ons with no committed launch date."}],"stakeholders":[{"id":"ivan","name":"Ivan Petrov","role":"Program Lead, Penrose Retail","blurb":"Runs the program on the customer side. Prefers honest plans over big promises.","knowledge":["The launch date is tied to the fiscal year start and cannot move.","The contract commits the data import and the approval workflow at launch. The rest is optional.","His team cares more about notifications than the branded portal."],"withholds":["Will not decide the delivery plan for you."],"responseRules":[{"id":"rel_contract","priority":3,"anyKeywords":["contract","required","committed","obligat","must ship","scope"],"reply":"The contract commits the data import and the approval workflow at launch. Notifications and the portal are listed as optional add-ons."},{"id":"rel_date","priority":2,"anyKeywords":["date","launch","move","delay","push","fixed","fiscal"],"reply":"The launch date is tied to our fiscal year start. It cannot move."},{"id":"rel_priority","priority":2,"anyKeywords":["notification","portal","prefer","which","matter","important","care"],"reply":"If I had to pick, my team cares more about notifications than the branded portal. But do not cut the core to save either."}],"fallbackReply":"I would rather hear a smaller honest plan than a big one that slips. What are you proposing?"}],"questions":[{"id":"protect","kind":"single_select","prompt":"What must be protected for launch?","options":["The core data import and the approval workflow","The custom notifications, since they are 60% done","The branded portal, since it is furthest behind","All four items equally"],"points":30,"answer":["The core data import and the approval workflow"],"competencyKey":"prioritization","expectedEvidence":"The contract requires the core data import and the approval workflow at launch, and both are done. The other two items are optional add-ons with no committed date."},{"id":"defer_items","kind":"multi_select","prompt":"Which items should be deferred past launch?","options":["Custom notifications","Branded portal","Core data import","Approval workflow"],"points":25,"answer":["Custom notifications","Branded portal"],"competencyKey":"scope_judgment","expectedEvidence":"Custom notifications (60%) and the branded portal (40%) are unfinished optional add-ons. Deferring them protects the fixed date without touching contractual scope."},{"id":"deferral_handling","kind":"single_select","prompt":"How should the deferral be handled with the customer?","options":["State plainly what ships after launch and when","Avoid mentioning the unfinished items unless the customer asks","Promise everything will be ready and work weekends","Remove the optional items from the project permanently"],"points":15,"answer":["State plainly what ships after launch and when"],"competencyKey":"deferral_handling","expectedEvidence":"Deferral only works when it is stated openly with a date. Hiding it erodes trust, overpromising risks the launch, and cancelling the items throws away paid scope."},{"id":"scope_message","kind":"text","prompt":"Write the revised-scope message to the customer.","helpText":"Max 400 characters. Confirm the date, name what ships, name what follows and anchor it to the contract.","maxChars":400,"points":20,"concepts":[{"id":"confirm_date","label":"Confirms the launch date","keywords":["launch date","on schedule","date stands","as planned","fiscal year"]},{"id":"ships_at_launch","label":"Names exactly what ships at launch","keywords":["at launch","data import","approval workflow","will be live","ships on day one"]},{"id":"later_with_date","label":"Names what comes later, with a date","keywords":["after launch","notifications","portal","weeks after","follow-up release"]},{"id":"tie_to_contract","label":"Ties the scope to the contract","keywords":["contract","committed","required at launch","optional add-on","as agreed"]}],"competencyKey":"customer_communication","expectedEvidence":"The launch date stands. At launch you get the core data import and the approval workflow, both done and both required by the contract. Custom notifications follow three weeks after launch, then the branded portal. Both are optional add-ons under the contract, and we will confirm the dates in writing."}],"competencies":[{"key":"prioritization","label":"Prioritization"},{"key":"scope_judgment","label":"Scope judgment"},{"key":"deferral_handling","label":"Deferral handling"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"protect":"Protected exactly what the contract requires at launch.","defer_items":"Deferred the two unfinished optional items without touching contractual scope.","deferral_handling":"Handled the deferral openly with a stated date instead of hiding or overpromising.","scope_message":"The message confirms the date, names both phases and anchors the plan to the contract."},"improvementTemplates":{"protect":"The items to protect are the core data import and the approval workflow. They are contractual and already done.","defer_items":"Custom notifications and the branded portal should be deferred. Both are optional add-ons and neither is finished.","deferral_handling":"The deferral should be stated plainly: say what ships after launch and when. Silence or overpromising damages trust more than the deferral itself.","scope_message":"A stronger message confirms the fixed date, names exactly what ships at launch, gives a date for what follows and ties the split to the contract terms."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"scope-tradeoff","roleKey":"implementation_consultant","title":"The Scope Trade-off","tagline":"The date will not move. The scope has to.","mission":"Penrose Retail''s launch date is fixed and two optional features are unfinished. The contract only requires the core workflow at launch. Decide what to protect, what to defer and how to tell the customer.","companyName":"Penrose Retail (customer)","durationMinutes":5,"resources":[{"id":"scope_table","title":"Scope status","kind":"table","content":"| Work item | Contract status | Progress |\n| --- | --- | --- |\n| Core data import | Required at launch | Done |\n| Approval workflow | Required at launch | Done |\n| Custom notifications | Optional add-on | 60% complete |\n| Branded portal | Optional add-on | 40% complete |"},{"id":"contract_note","title":"Contract note","kind":"markdown","content":"## Contract note\n\nThe launch date is fixed and tied to Penrose Retail''s fiscal year start. The contract requires the core data import and the approval workflow at launch. Custom notifications and the branded portal are optional add-ons with no committed launch date."}],"stakeholders":[{"id":"ivan","name":"Ivan Petrov","role":"Program Lead, Penrose Retail","blurb":"Runs the program on the customer side. Prefers honest plans over big promises.","knowledge":["The launch date is tied to the fiscal year start and cannot move.","The contract commits the data import and the approval workflow at launch. The rest is optional.","His team cares more about notifications than the branded portal."],"withholds":["Will not decide the delivery plan for you."],"responseRules":[{"id":"rel_contract","priority":3,"anyKeywords":["contract","required","committed","obligat","must ship","scope"],"reply":"The contract commits the data import and the approval workflow at launch. Notifications and the portal are listed as optional add-ons."},{"id":"rel_date","priority":2,"anyKeywords":["date","launch","move","delay","push","fixed","fiscal"],"reply":"The launch date is tied to our fiscal year start. It cannot move."},{"id":"rel_priority","priority":2,"anyKeywords":["notification","portal","prefer","which","matter","important","care"],"reply":"If I had to pick, my team cares more about notifications than the branded portal. But do not cut the core to save either."}],"fallbackReply":"I would rather hear a smaller honest plan than a big one that slips. What are you proposing?"}],"questions":[{"id":"protect","kind":"single_select","prompt":"What must be protected for launch?","options":["The core data import and the approval workflow","The custom notifications, since they are 60% done","The branded portal, since it is furthest behind","All four items equally"],"points":30,"answer":["The core data import and the approval workflow"],"competencyKey":"prioritization","expectedEvidence":"The contract requires the core data import and the approval workflow at launch, and both are done. The other two items are optional add-ons with no committed date."},{"id":"defer_items","kind":"multi_select","prompt":"Which items should be deferred past launch?","options":["Custom notifications","Branded portal","Core data import","Approval workflow"],"points":25,"answer":["Custom notifications","Branded portal"],"competencyKey":"scope_judgment","expectedEvidence":"Custom notifications (60%) and the branded portal (40%) are unfinished optional add-ons. Deferring them protects the fixed date without touching contractual scope."},{"id":"deferral_handling","kind":"single_select","prompt":"How should the deferral be handled with the customer?","options":["State plainly what ships after launch and when","Avoid mentioning the unfinished items unless the customer asks","Promise everything will be ready and work weekends","Remove the optional items from the project permanently"],"points":15,"answer":["State plainly what ships after launch and when"],"competencyKey":"deferral_handling","expectedEvidence":"Deferral only works when it is stated openly with a date. Hiding it erodes trust, overpromising risks the launch, and cancelling the items throws away paid scope."},{"id":"scope_message","kind":"text","prompt":"Write the revised-scope message to the customer.","helpText":"Max 400 characters. Confirm the date, name what ships, name what follows and anchor it to the contract.","maxChars":400,"points":20,"concepts":[{"id":"confirm_date","label":"Confirms the launch date","keywords":["launch date","on schedule","date stands","as planned","fiscal year"]},{"id":"ships_at_launch","label":"Names exactly what ships at launch","keywords":["at launch","data import","approval workflow","will be live","ships on day one"]},{"id":"later_with_date","label":"Names what comes later, with a date","keywords":["after launch","notifications","portal","weeks after","follow-up release"]},{"id":"tie_to_contract","label":"Ties the scope to the contract","keywords":["contract","committed","required at launch","optional add-on","as agreed"]}],"competencyKey":"customer_communication","expectedEvidence":"The launch date stands. At launch you get the core data import and the approval workflow, both done and both required by the contract. Custom notifications follow three weeks after launch, then the branded portal. Both are optional add-ons under the contract, and we will confirm the dates in writing."}],"competencies":[{"key":"prioritization","label":"Prioritization"},{"key":"scope_judgment","label":"Scope judgment"},{"key":"deferral_handling","label":"Deferral handling"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"protect":"Protected exactly what the contract requires at launch.","defer_items":"Deferred the two unfinished optional items without touching contractual scope.","deferral_handling":"Handled the deferral openly with a stated date instead of hiding or overpromising.","scope_message":"The message confirms the date, names both phases and anchors the plan to the contract."},"improvementTemplates":{"protect":"The items to protect are the core data import and the approval workflow. They are contractual and already done.","defer_items":"Custom notifications and the branded portal should be deferred. Both are optional add-ons and neither is finished.","deferral_handling":"The deferral should be stated plainly: say what ships after launch and when. Silence or overpromising damages trust more than the deferral itself.","scope_message":"A stronger message confirms the fixed date, names exactly what ships at launch, gives a date for what follows and ties the split to the contract terms."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'green-status-page';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('green-status-page', 'technical_support_engineer', 'The Green Status Page', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'technical_support_engineer', title = 'The Green Status Page', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"green-status-page","roleKey":"technical_support_engineer","title":"The Green Status Page","tagline":"Customers can''t log in. The status page says everything is fine.","mission":"Three customers report intermittent login failures since this morning. The status page is green and the queue is growing. Triage the incident, isolate the likely cause and write a customer update you can stand behind.","companyName":"Skedra (your employer)","durationMinutes":5,"resources":[{"id":"tickets","title":"Open tickets","kind":"table","content":"| Ticket | Customer | Time (UTC) | Report |\n| --- | --- | --- | --- |\n| T-881 | Nordwind Health | 10:02 | Staff intermittently can''t log in via company SSO |\n| T-882 | Calder Logistics | 10:15 | SSO login fails about half the time, retry sometimes works |\n| T-883 | Pemble & Co | 10:21 | One user gets ''wrong password''; she recently changed it |\n| T-884 | Ostrom Manufacturing | 10:34 | Whole team locked out through corporate identity provider |"},{"id":"auth_log","title":"Auth log excerpt","kind":"markdown","content":"```\n09:41:12 INFO  deploy complete: R-2214\n09:47:03 ERROR saml_validate account=nordwind assertion_not_yet_valid skew=41s\n09:52:44 INFO  login ok method=password account=pemble\n09:58:19 ERROR saml_validate account=calder assertion_expired skew=67s\n10:03:55 ERROR saml_validate account=nordwind assertion_not_yet_valid skew=38s\n10:11:30 INFO  login ok method=password account=ostrom-admin\n10:19:02 ERROR saml_validate account=ostrom assertion_expired skew=52s\n10:26:47 ERROR password_mismatch account=pemble user=j.harmon\n```"},{"id":"release_notes","title":"Release timeline","kind":"markdown","content":"## Recent releases\n\n| Release | Deployed (UTC) | Notes |\n| --- | --- | --- |\n| R-2212 | Tuesday | Dashboard performance improvements |\n| R-2213 | Wednesday | New report export formats |\n| R-2214 | **Today 09:41** | Auth hardening: tightened SAML assertion time validation from 300s to 30s |\n\n## Status page\n\nStatus checks log in with a **password test account** every 60 seconds. They do not use SSO."}],"stakeholders":[{"id":"sam","name":"Sam Okafor","role":"On-call Platform Engineer","blurb":"Can confirm what changed in the release. Busy mid-incident.","knowledge":["R-2214 tightened the SAML clock-skew window from 300 seconds to 30 seconds.","Only SSO customers whose identity providers drift more than 30s are affected; a config revert takes ~10 minutes."],"withholds":["Won''t volunteer the diagnosis unless asked about the release or SAML."],"responseRules":[{"id":"rel_release","priority":3,"anyKeywords":["r-2214","r2214","release","deploy","saml","clock","skew","assertion","what changed"],"reply":"R-2214 tightened the SAML assertion clock-skew window from 300 seconds to 30. Any identity provider drifting more than 30s will fail validation intermittently. I can revert the config flag in about 10 minutes if you call it."},{"id":"rel_scope","priority":2,"anyKeywords":["affected","scope","who","which customers","password","how many"],"reply":"Password logins are untouched. That''s why the status page is green; its checks use a password test account. Only SSO customers with drifting identity providers are hitting it."}],"fallbackReply":"I''m heads-down on the incident bridge. Ask me something specific about the release or the auth path and I''ll answer fast."}],"questions":[{"id":"likely_cause","kind":"single_select","prompt":"What is the most likely cause?","options":["Release R-2214 tightened SAML time validation, breaking identity providers with clock drift","The password database is failing intermittently","The status page monitoring is broken","Customers'' networks are blocking the login page"],"points":30,"answer":["Release R-2214 tightened SAML time validation, breaking identity providers with clock drift"],"competencyKey":"technical_diagnosis","expectedEvidence":"Every failure in the log is a saml_validate error with skew above 30s, all after the 09:41 R-2214 deploy that tightened the window from 300s to 30s."},{"id":"incident_tickets","kind":"multi_select","prompt":"Which tickets are part of this incident?","options":["T-881 Nordwind Health","T-882 Calder Logistics","T-883 Pemble & Co","T-884 Ostrom Manufacturing"],"points":15,"answer":["T-881 Nordwind Health","T-882 Calder Logistics","T-884 Ostrom Manufacturing"],"competencyKey":"triage","expectedEvidence":"T-881, T-882 and T-884 are SSO/SAML failures. T-883 is a password mismatch for one user who recently changed her password, which is unrelated."},{"id":"immediate_action","kind":"single_select","prompt":"What is the right immediate action?","options":["Escalate to engineering with the log evidence and request the R-2214 skew-tolerance revert","Tell all affected users to reset their passwords","Wait for more tickets to confirm the pattern","Mark the tickets resolved since retries sometimes work"],"points":20,"answer":["Escalate to engineering with the log evidence and request the R-2214 skew-tolerance revert"],"competencyKey":"escalation_judgment","expectedEvidence":"The evidence is sufficient to escalate now, and the platform engineer can revert the config in ~10 minutes. Password resets won''t fix SAML validation."},{"id":"customer_update","kind":"text","prompt":"Write the customer status update.","helpText":"Max 400 characters. Honest about scope and next steps. No promises you can''t keep.","maxChars":400,"points":25,"concepts":[{"id":"acknowledge_scope","label":"Acknowledges the issue and states the SSO-only scope","keywords":["sso","single sign","saml","identity provider","some customers","login"]},{"id":"no_overpromise","label":"Commits to a next update, not a guaranteed fix time","keywords":["update","within","next","working on","identified","investigating","shortly"]},{"id":"workaround","label":"Offers the password-login workaround where available","keywords":["password","workaround","alternative","in the meantime"]}],"competencyKey":"customer_communication","expectedEvidence":"We''ve identified an issue affecting SSO logins for some customers following this morning''s release; password logins are unaffected. Engineering is deploying a fix now. If your account supports password login, that works in the meantime. Next update within 30 minutes."}],"competencies":[{"key":"triage","label":"Triage"},{"key":"technical_diagnosis","label":"Technical diagnosis"},{"key":"escalation_judgment","label":"Escalation judgment"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"likely_cause":"Correlated the log errors with the release timeline to isolate the real cause.","incident_tickets":"Separated the incident tickets from the unrelated password issue.","immediate_action":"Escalated with evidence instead of waiting or applying the wrong fix.","customer_update":"The customer update is honest about scope and avoids promises that can''t be kept."},"improvementTemplates":{"likely_cause":"The log shows SAML validation errors with 38–67s skew starting right after R-2214 tightened the window to 30s. That''s the cause.","incident_tickets":"T-881, T-882 and T-884 are SSO failures; T-883 is a single-user password mismatch and not part of the incident.","immediate_action":"With log evidence in hand, the right move is escalating to engineering and requesting the skew-tolerance revert, a ~10 minute fix.","customer_update":"A stronger update states the SSO-only scope, offers the password workaround, and commits to a next-update time instead of a fix time."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"green-status-page","roleKey":"technical_support_engineer","title":"The Green Status Page","tagline":"Customers can''t log in. The status page says everything is fine.","mission":"Three customers report intermittent login failures since this morning. The status page is green and the queue is growing. Triage the incident, isolate the likely cause and write a customer update you can stand behind.","companyName":"Skedra (your employer)","durationMinutes":5,"resources":[{"id":"tickets","title":"Open tickets","kind":"table","content":"| Ticket | Customer | Time (UTC) | Report |\n| --- | --- | --- | --- |\n| T-881 | Nordwind Health | 10:02 | Staff intermittently can''t log in via company SSO |\n| T-882 | Calder Logistics | 10:15 | SSO login fails about half the time, retry sometimes works |\n| T-883 | Pemble & Co | 10:21 | One user gets ''wrong password''; she recently changed it |\n| T-884 | Ostrom Manufacturing | 10:34 | Whole team locked out through corporate identity provider |"},{"id":"auth_log","title":"Auth log excerpt","kind":"markdown","content":"```\n09:41:12 INFO  deploy complete: R-2214\n09:47:03 ERROR saml_validate account=nordwind assertion_not_yet_valid skew=41s\n09:52:44 INFO  login ok method=password account=pemble\n09:58:19 ERROR saml_validate account=calder assertion_expired skew=67s\n10:03:55 ERROR saml_validate account=nordwind assertion_not_yet_valid skew=38s\n10:11:30 INFO  login ok method=password account=ostrom-admin\n10:19:02 ERROR saml_validate account=ostrom assertion_expired skew=52s\n10:26:47 ERROR password_mismatch account=pemble user=j.harmon\n```"},{"id":"release_notes","title":"Release timeline","kind":"markdown","content":"## Recent releases\n\n| Release | Deployed (UTC) | Notes |\n| --- | --- | --- |\n| R-2212 | Tuesday | Dashboard performance improvements |\n| R-2213 | Wednesday | New report export formats |\n| R-2214 | **Today 09:41** | Auth hardening: tightened SAML assertion time validation from 300s to 30s |\n\n## Status page\n\nStatus checks log in with a **password test account** every 60 seconds. They do not use SSO."}],"stakeholders":[{"id":"sam","name":"Sam Okafor","role":"On-call Platform Engineer","blurb":"Can confirm what changed in the release. Busy mid-incident.","knowledge":["R-2214 tightened the SAML clock-skew window from 300 seconds to 30 seconds.","Only SSO customers whose identity providers drift more than 30s are affected; a config revert takes ~10 minutes."],"withholds":["Won''t volunteer the diagnosis unless asked about the release or SAML."],"responseRules":[{"id":"rel_release","priority":3,"anyKeywords":["r-2214","r2214","release","deploy","saml","clock","skew","assertion","what changed"],"reply":"R-2214 tightened the SAML assertion clock-skew window from 300 seconds to 30. Any identity provider drifting more than 30s will fail validation intermittently. I can revert the config flag in about 10 minutes if you call it."},{"id":"rel_scope","priority":2,"anyKeywords":["affected","scope","who","which customers","password","how many"],"reply":"Password logins are untouched. That''s why the status page is green; its checks use a password test account. Only SSO customers with drifting identity providers are hitting it."}],"fallbackReply":"I''m heads-down on the incident bridge. Ask me something specific about the release or the auth path and I''ll answer fast."}],"questions":[{"id":"likely_cause","kind":"single_select","prompt":"What is the most likely cause?","options":["Release R-2214 tightened SAML time validation, breaking identity providers with clock drift","The password database is failing intermittently","The status page monitoring is broken","Customers'' networks are blocking the login page"],"points":30,"answer":["Release R-2214 tightened SAML time validation, breaking identity providers with clock drift"],"competencyKey":"technical_diagnosis","expectedEvidence":"Every failure in the log is a saml_validate error with skew above 30s, all after the 09:41 R-2214 deploy that tightened the window from 300s to 30s."},{"id":"incident_tickets","kind":"multi_select","prompt":"Which tickets are part of this incident?","options":["T-881 Nordwind Health","T-882 Calder Logistics","T-883 Pemble & Co","T-884 Ostrom Manufacturing"],"points":15,"answer":["T-881 Nordwind Health","T-882 Calder Logistics","T-884 Ostrom Manufacturing"],"competencyKey":"triage","expectedEvidence":"T-881, T-882 and T-884 are SSO/SAML failures. T-883 is a password mismatch for one user who recently changed her password, which is unrelated."},{"id":"immediate_action","kind":"single_select","prompt":"What is the right immediate action?","options":["Escalate to engineering with the log evidence and request the R-2214 skew-tolerance revert","Tell all affected users to reset their passwords","Wait for more tickets to confirm the pattern","Mark the tickets resolved since retries sometimes work"],"points":20,"answer":["Escalate to engineering with the log evidence and request the R-2214 skew-tolerance revert"],"competencyKey":"escalation_judgment","expectedEvidence":"The evidence is sufficient to escalate now, and the platform engineer can revert the config in ~10 minutes. Password resets won''t fix SAML validation."},{"id":"customer_update","kind":"text","prompt":"Write the customer status update.","helpText":"Max 400 characters. Honest about scope and next steps. No promises you can''t keep.","maxChars":400,"points":25,"concepts":[{"id":"acknowledge_scope","label":"Acknowledges the issue and states the SSO-only scope","keywords":["sso","single sign","saml","identity provider","some customers","login"]},{"id":"no_overpromise","label":"Commits to a next update, not a guaranteed fix time","keywords":["update","within","next","working on","identified","investigating","shortly"]},{"id":"workaround","label":"Offers the password-login workaround where available","keywords":["password","workaround","alternative","in the meantime"]}],"competencyKey":"customer_communication","expectedEvidence":"We''ve identified an issue affecting SSO logins for some customers following this morning''s release; password logins are unaffected. Engineering is deploying a fix now. If your account supports password login, that works in the meantime. Next update within 30 minutes."}],"competencies":[{"key":"triage","label":"Triage"},{"key":"technical_diagnosis","label":"Technical diagnosis"},{"key":"escalation_judgment","label":"Escalation judgment"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"likely_cause":"Correlated the log errors with the release timeline to isolate the real cause.","incident_tickets":"Separated the incident tickets from the unrelated password issue.","immediate_action":"Escalated with evidence instead of waiting or applying the wrong fix.","customer_update":"The customer update is honest about scope and avoids promises that can''t be kept."},"improvementTemplates":{"likely_cause":"The log shows SAML validation errors with 38–67s skew starting right after R-2214 tightened the window to 30s. That''s the cause.","incident_tickets":"T-881, T-882 and T-884 are SSO failures; T-883 is a single-user password mismatch and not part of the incident.","immediate_action":"With log evidence in hand, the right move is escalating to engineering and requesting the skew-tolerance revert, a ~10 minute fix.","customer_update":"A stronger update states the SSO-only scope, offers the password workaround, and commits to a next-update time instead of a fix time."}}'::jsonb,
      now()
