do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'api-timeout';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('api-timeout', 'technical_support_engineer', 'The API Timeout', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'technical_support_engineer', title = 'The API Timeout', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"api-timeout","roleKey":"technical_support_engineer","title":"The API Timeout","tagline":"Requests are timing out, and the slow part is not yours.","mission":"Three customers report timeouts this afternoon. Find what changed at 14:00, pick the safest mitigation, and write an escalation engineering can act on. You have the latency log, a dependency note, and the open tickets.","companyName":"Corvela (your employer)","durationMinutes":5,"resources":[{"id":"latency_log","title":"Latency log","kind":"markdown","content":"```\n13:00 p95 api_core=118ms addr_verify=210ms\n13:30 p95 api_core=121ms addr_verify=195ms\n14:00 p95 api_core=119ms addr_verify=9200ms\n14:02 ERROR timeout endpoint=/orders/new waiting_on=addr_verify elapsed=10s\n14:07 ERROR timeout endpoint=/accounts/update waiting_on=addr_verify elapsed=10s\n14:30 p95 api_core=122ms addr_verify=8800ms\n15:00 p95 api_core=120ms addr_verify=9100ms\n```"},{"id":"dependency_note","title":"Service dependency note","kind":"markdown","content":"## What these services are\n\n- `api_core` is our internal API service.\n- `addr_verify` calls **VerifyPoint**, a third-party address verification service.\n\nThe endpoints `/orders/new` and `/accounts/update` call `addr_verify` before they respond. The call waits up to 10 seconds. There were no deployments today."},{"id":"tickets","title":"Open tickets","kind":"table","content":"| Ticket | Customer | Time | Report |\n| --- | --- | --- | --- |\n| T-301 | Bramley Home Goods | 14:05 | Checkout hangs and then fails when we enter a shipping address |\n| T-302 | Quill and Post | 14:12 | Saving a customer address times out |\n| T-303 | Fenmore Outfitters | 14:20 | Address lookup spins for 10 seconds and then errors |"}],"stakeholders":[{"id":"dana","name":"Dana Whitfield","role":"On-call Platform Engineer","blurb":"Knows the service map and the timeout config. Watching alerts.","knowledge":["Nothing deployed today; api_core latency has been flat all day.","addr_verify is a thin wrapper around VerifyPoint, a third-party service; the call waits 10 seconds with no fallback."],"withholds":["Will not write the escalation for you."],"responseRules":[{"id":"rel_dependency","priority":3,"anyKeywords":["verifypoint","addr_verify","address","third party","third-party","vendor","dependency"],"reply":"addr_verify is a thin wrapper around VerifyPoint, a third-party service. Their latency is theirs, not ours. We have a support contact for them if you want me to open a ticket."},{"id":"rel_deploy","priority":2,"anyKeywords":["deploy","release","what changed","internal","our side","ship"],"reply":"Nothing shipped today. api_core has been quiet and its latency looks normal to me all day."},{"id":"rel_timeout","priority":2,"anyKeywords":["timeout","retry","fallback","config","fail fast"],"reply":"The addr_verify call currently waits up to 10 seconds with no fallback. I can add a shorter timeout and a retry path quickly if you make the case."}],"fallbackReply":"I am juggling a few alerts right now. Ask me something specific about the services or the timeline and I will answer fast."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is the root cause of the timeouts?","options":["VerifyPoint, the third-party address verification service, became slow and requests wait on it until they time out","Our internal api_core service is having an outage","A deployment this afternoon broke the checkout endpoints","Customers are entering invalid addresses"],"points":30,"answer":["VerifyPoint, the third-party address verification service, became slow and requests wait on it until they time out"],"competencyKey":"technical_diagnosis","expectedEvidence":"addr_verify p95 jumped from about 200ms to 9200ms at 14:00 while api_core stayed near 120ms. The timeouts start at 14:02 and every failing request is waiting on addr_verify."},{"id":"supporting_evidence","kind":"multi_select","prompt":"Which observations support that root cause?","options":["addr_verify p95 jumped from about 200ms to 9200ms at 14:00","The timeouts started at 14:02, right after the jump","api_core p95 stayed near 120ms all day","The tickets came from three different customers","The errors happen on more than one endpoint"],"points":20,"answer":["addr_verify p95 jumped from about 200ms to 9200ms at 14:00","The timeouts started at 14:02, right after the jump","api_core p95 stayed near 120ms all day"],"competencyKey":"evidence_analysis","expectedEvidence":"The latency jump at 14:00, the timeouts beginning at 14:02, and the unchanged internal p95 together point at the dependency. Ticket count and endpoint spread do not separate internal from external causes."},{"id":"safest_mitigation","kind":"single_select","prompt":"What is the safest mitigation right now?","options":["Add a timeout on the addr_verify call with a graceful fallback and retry, and notify VerifyPoint","Restart api_core in every region","Disable address entry until VerifyPoint recovers","Ask customers to keep retrying until it works"],"points":15,"answer":["Add a timeout on the addr_verify call with a graceful fallback and retry, and notify VerifyPoint"],"competencyKey":"mitigation_judgment","expectedEvidence":"api_core is healthy, so restarting it does nothing. Failing fast with a fallback keeps orders flowing while the vendor is notified. Disabling address entry blocks every customer instead of degrading gracefully."},{"id":"escalation_message","kind":"text","prompt":"Write the escalation message to engineering.","helpText":"Max 400 characters. State the evidence, name the dependency, and say what you want done.","maxChars":400,"points":25,"concepts":[{"id":"timestamps","label":"States the correlation with timestamps","keywords":["14:00","14:02","right after","timeline","correlat"]},{"id":"name_dependency","label":"Names the third-party dependency","keywords":["verifypoint","addr_verify","third party","third-party","address verification","vendor"]},{"id":"not_internal","label":"Distinguishes this from an internal outage","keywords":["api_core","internal","not an outage","unchanged","120ms","healthy"]},{"id":"propose_handling","label":"Proposes timeout and retry handling","keywords":["timeout","retry","fallback","fail fast","shorter"]}],"competencyKey":"escalation_communication","expectedEvidence":"VerifyPoint latency jumped from 200ms to 9s at 14:00 and our timeouts started at 14:02. api_core is healthy at 120ms, so this is the addr_verify dependency, not an internal outage. Requesting a shorter timeout with fallback and retry on that call, and I am notifying the vendor."}],"competencies":[{"key":"technical_diagnosis","label":"Technical diagnosis"},{"key":"evidence_analysis","label":"Evidence analysis"},{"key":"mitigation_judgment","label":"Mitigation judgment"},{"key":"escalation_communication","label":"Escalation communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Traced the timeouts to the third-party verifier instead of assuming an internal outage.","supporting_evidence":"Picked the three observations that actually separate external from internal causes.","safest_mitigation":"Chose a mitigation that degrades gracefully instead of blocking customers or restarting healthy services.","escalation_message":"The escalation names the dependency, anchors the timeline, and asks for a specific change."},"improvementTemplates":{"root_cause":"The verifier''s p95 jumped from 200ms to 9200ms at 14:00 and timeouts began at 14:02 while api_core stayed at 120ms. That points at VerifyPoint, not an internal outage.","supporting_evidence":"The strongest evidence is the verifier latency jump at 14:00, the timeouts starting at 14:02, and the unchanged internal p95. Ticket counts alone do not isolate the cause.","safest_mitigation":"The safe move is a shorter timeout on the addr_verify call with a graceful fallback and retry, plus notifying VerifyPoint. Restarting api_core does nothing because it is healthy.","escalation_message":"A stronger escalation states the 14:00 to 14:02 correlation, names VerifyPoint, rules out an internal outage, and requests timeout and retry handling."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"api-timeout","roleKey":"technical_support_engineer","title":"The API Timeout","tagline":"Requests are timing out, and the slow part is not yours.","mission":"Three customers report timeouts this afternoon. Find what changed at 14:00, pick the safest mitigation, and write an escalation engineering can act on. You have the latency log, a dependency note, and the open tickets.","companyName":"Corvela (your employer)","durationMinutes":5,"resources":[{"id":"latency_log","title":"Latency log","kind":"markdown","content":"```\n13:00 p95 api_core=118ms addr_verify=210ms\n13:30 p95 api_core=121ms addr_verify=195ms\n14:00 p95 api_core=119ms addr_verify=9200ms\n14:02 ERROR timeout endpoint=/orders/new waiting_on=addr_verify elapsed=10s\n14:07 ERROR timeout endpoint=/accounts/update waiting_on=addr_verify elapsed=10s\n14:30 p95 api_core=122ms addr_verify=8800ms\n15:00 p95 api_core=120ms addr_verify=9100ms\n```"},{"id":"dependency_note","title":"Service dependency note","kind":"markdown","content":"## What these services are\n\n- `api_core` is our internal API service.\n- `addr_verify` calls **VerifyPoint**, a third-party address verification service.\n\nThe endpoints `/orders/new` and `/accounts/update` call `addr_verify` before they respond. The call waits up to 10 seconds. There were no deployments today."},{"id":"tickets","title":"Open tickets","kind":"table","content":"| Ticket | Customer | Time | Report |\n| --- | --- | --- | --- |\n| T-301 | Bramley Home Goods | 14:05 | Checkout hangs and then fails when we enter a shipping address |\n| T-302 | Quill and Post | 14:12 | Saving a customer address times out |\n| T-303 | Fenmore Outfitters | 14:20 | Address lookup spins for 10 seconds and then errors |"}],"stakeholders":[{"id":"dana","name":"Dana Whitfield","role":"On-call Platform Engineer","blurb":"Knows the service map and the timeout config. Watching alerts.","knowledge":["Nothing deployed today; api_core latency has been flat all day.","addr_verify is a thin wrapper around VerifyPoint, a third-party service; the call waits 10 seconds with no fallback."],"withholds":["Will not write the escalation for you."],"responseRules":[{"id":"rel_dependency","priority":3,"anyKeywords":["verifypoint","addr_verify","address","third party","third-party","vendor","dependency"],"reply":"addr_verify is a thin wrapper around VerifyPoint, a third-party service. Their latency is theirs, not ours. We have a support contact for them if you want me to open a ticket."},{"id":"rel_deploy","priority":2,"anyKeywords":["deploy","release","what changed","internal","our side","ship"],"reply":"Nothing shipped today. api_core has been quiet and its latency looks normal to me all day."},{"id":"rel_timeout","priority":2,"anyKeywords":["timeout","retry","fallback","config","fail fast"],"reply":"The addr_verify call currently waits up to 10 seconds with no fallback. I can add a shorter timeout and a retry path quickly if you make the case."}],"fallbackReply":"I am juggling a few alerts right now. Ask me something specific about the services or the timeline and I will answer fast."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"What is the root cause of the timeouts?","options":["VerifyPoint, the third-party address verification service, became slow and requests wait on it until they time out","Our internal api_core service is having an outage","A deployment this afternoon broke the checkout endpoints","Customers are entering invalid addresses"],"points":30,"answer":["VerifyPoint, the third-party address verification service, became slow and requests wait on it until they time out"],"competencyKey":"technical_diagnosis","expectedEvidence":"addr_verify p95 jumped from about 200ms to 9200ms at 14:00 while api_core stayed near 120ms. The timeouts start at 14:02 and every failing request is waiting on addr_verify."},{"id":"supporting_evidence","kind":"multi_select","prompt":"Which observations support that root cause?","options":["addr_verify p95 jumped from about 200ms to 9200ms at 14:00","The timeouts started at 14:02, right after the jump","api_core p95 stayed near 120ms all day","The tickets came from three different customers","The errors happen on more than one endpoint"],"points":20,"answer":["addr_verify p95 jumped from about 200ms to 9200ms at 14:00","The timeouts started at 14:02, right after the jump","api_core p95 stayed near 120ms all day"],"competencyKey":"evidence_analysis","expectedEvidence":"The latency jump at 14:00, the timeouts beginning at 14:02, and the unchanged internal p95 together point at the dependency. Ticket count and endpoint spread do not separate internal from external causes."},{"id":"safest_mitigation","kind":"single_select","prompt":"What is the safest mitigation right now?","options":["Add a timeout on the addr_verify call with a graceful fallback and retry, and notify VerifyPoint","Restart api_core in every region","Disable address entry until VerifyPoint recovers","Ask customers to keep retrying until it works"],"points":15,"answer":["Add a timeout on the addr_verify call with a graceful fallback and retry, and notify VerifyPoint"],"competencyKey":"mitigation_judgment","expectedEvidence":"api_core is healthy, so restarting it does nothing. Failing fast with a fallback keeps orders flowing while the vendor is notified. Disabling address entry blocks every customer instead of degrading gracefully."},{"id":"escalation_message","kind":"text","prompt":"Write the escalation message to engineering.","helpText":"Max 400 characters. State the evidence, name the dependency, and say what you want done.","maxChars":400,"points":25,"concepts":[{"id":"timestamps","label":"States the correlation with timestamps","keywords":["14:00","14:02","right after","timeline","correlat"]},{"id":"name_dependency","label":"Names the third-party dependency","keywords":["verifypoint","addr_verify","third party","third-party","address verification","vendor"]},{"id":"not_internal","label":"Distinguishes this from an internal outage","keywords":["api_core","internal","not an outage","unchanged","120ms","healthy"]},{"id":"propose_handling","label":"Proposes timeout and retry handling","keywords":["timeout","retry","fallback","fail fast","shorter"]}],"competencyKey":"escalation_communication","expectedEvidence":"VerifyPoint latency jumped from 200ms to 9s at 14:00 and our timeouts started at 14:02. api_core is healthy at 120ms, so this is the addr_verify dependency, not an internal outage. Requesting a shorter timeout with fallback and retry on that call, and I am notifying the vendor."}],"competencies":[{"key":"technical_diagnosis","label":"Technical diagnosis"},{"key":"evidence_analysis","label":"Evidence analysis"},{"key":"mitigation_judgment","label":"Mitigation judgment"},{"key":"escalation_communication","label":"Escalation communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Traced the timeouts to the third-party verifier instead of assuming an internal outage.","supporting_evidence":"Picked the three observations that actually separate external from internal causes.","safest_mitigation":"Chose a mitigation that degrades gracefully instead of blocking customers or restarting healthy services.","escalation_message":"The escalation names the dependency, anchors the timeline, and asks for a specific change."},"improvementTemplates":{"root_cause":"The verifier''s p95 jumped from 200ms to 9200ms at 14:00 and timeouts began at 14:02 while api_core stayed at 120ms. That points at VerifyPoint, not an internal outage.","supporting_evidence":"The strongest evidence is the verifier latency jump at 14:00, the timeouts starting at 14:02, and the unchanged internal p95. Ticket counts alone do not isolate the cause.","safest_mitigation":"The safe move is a shorter timeout on the addr_verify call with a graceful fallback and retry, plus notifying VerifyPoint. Restarting api_core does nothing because it is healthy.","escalation_message":"A stronger escalation states the 14:00 to 14:02 correlation, names VerifyPoint, rules out an internal outage, and requests timeout and retry handling."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'permission-failure';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('permission-failure', 'technical_support_engineer', 'The Permission Failure', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'technical_support_engineer', title = 'The Permission Failure', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"permission-failure","roleKey":"technical_support_engineer","title":"The Permission Failure","tagline":"Three users lost their reports overnight, and one change explains it.","mission":"Four tickets landed this morning and three of them mention reports. A role template changed on Tuesday. Work out what the change did, quantify which tickets it explains, and write the customer update.","companyName":"Fernbrook Software (your employer)","durationMinutes":5,"resources":[{"id":"role_diff","title":"Role template change","kind":"markdown","content":"## Change applied Tuesday 09:00\n\nRole: **Analyst**\n\n| | Permissions |\n| --- | --- |\n| Before | view_reports, export_data |\n| After | export_data |\n\nThe permission `view_reports` was removed from the Analyst role. No other roles were changed."},{"id":"tickets","title":"Open tickets","kind":"table","content":"| Ticket | User | Role | Report |\n| --- | --- | --- | --- |\n| T-410 | Priya Shah | Analyst | Reports tab says access denied |\n| T-411 | Colin Marsh | Analyst | All my saved reports disappeared this morning |\n| T-412 | Ella Burke | Analyst | Cannot open the weekly sales report |\n| T-413 | Sam Trent | Manager | Forgot my password, need a reset |"}],"stakeholders":[{"id":"marcus","name":"Marcus Lee","role":"IT Administrator","blurb":"Made the Tuesday template change. Slightly embarrassed.","knowledge":["He meant to remove view_reports from the Contractor role and applied the change to Analyst by mistake.","Only the Analyst role changed; restoring the permission takes a few minutes."],"withholds":["Will not decide the customer messaging."],"responseRules":[{"id":"rel_change","priority":3,"anyKeywords":["template","tuesday","view_reports","removed","why","diff","who changed"],"reply":"That change was mine. I meant to remove view_reports from the Contractor role and applied it to Analyst by mistake. I can put it back in a few minutes."},{"id":"rel_scope","priority":2,"anyKeywords":["analyst","affected","which users","other roles","scope","manager"],"reply":"Only the Analyst role changed. Managers and Contractors are untouched, so anything outside Analyst is a different issue."}],"fallbackReply":"Tell me which role or permission you are looking at and I can check the change history for you."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why did these users lose report access?","options":["Tuesday''s template change removed view_reports from the Analyst role","The reports service is down","The users'' accounts were deactivated","A password policy change locked users out"],"points":30,"answer":["Tuesday''s template change removed view_reports from the Analyst role"],"competencyKey":"access_diagnosis","expectedEvidence":"The diff shows view_reports was removed from the Analyst role on Tuesday, and the three report tickets all come from Analyst-role users."},{"id":"explained_count","kind":"number","prompt":"How many of the 4 tickets does the template change explain?","helpText":"Count tickets caused by the removed permission.","points":20,"answer":[3,0],"competencyKey":"impact_quantification","expectedEvidence":"T-410, T-411 and T-412 are Analyst-role users blocked from reports. T-413 is a Manager''s password reset and is unrelated. 3 tickets."},{"id":"right_fix","kind":"single_select","prompt":"What is the right fix?","options":["Restore view_reports to the Analyst role only","Give the affected users admin access so they are never blocked again","Recreate the affected user accounts","Roll back every role template to last month''s version"],"points":15,"answer":["Restore view_reports to the Analyst role only"],"competencyKey":"remediation_judgment","expectedEvidence":"The change removed one permission from one role, so the fix restores exactly that. Admin access grants far more than the users had before, and a full rollback risks undoing unrelated changes."},{"id":"customer_update","kind":"text","prompt":"Write the update you would send the affected users.","helpText":"Max 400 characters. Own the cause, say exactly what is being restored, and when access returns.","maxChars":400,"points":25,"concepts":[{"id":"own_cause","label":"Acknowledges the cause plainly","keywords":["role change","template","our change","permission was removed","on our side","we removed"]},{"id":"specific_permission","label":"States the specific permission being restored","keywords":["view_reports","report permission","view reports"]},{"id":"scoped_fix","label":"Avoids granting broad admin access","keywords":["analyst role","only","scoped","not admin","without admin","exactly what"]},{"id":"when_restored","label":"Confirms when access returns","keywords":["restored","within","shortly","today","back","few minutes"]}],"competencyKey":"customer_communication","expectedEvidence":"A role template change on our side removed the view_reports permission from the Analyst role. We are restoring that permission to the Analyst role only, nothing broader. Your report access will be back within the hour, and we will confirm once it is live."}],"competencies":[{"key":"access_diagnosis","label":"Access diagnosis"},{"key":"impact_quantification","label":"Impact quantification"},{"key":"remediation_judgment","label":"Remediation judgment"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Connected the report tickets to the role template diff instead of chasing a service outage.","explained_count":"Correctly separated the tickets the change explains from the unrelated one.","right_fix":"Chose the narrow fix that restores exactly what was lost, without over-granting.","customer_update":"The update owns the cause, names the specific permission, and commits to a restore time."},"improvementTemplates":{"root_cause":"The diff shows view_reports was removed from the Analyst role on Tuesday. All three report tickets come from Analyst users, which points at that change.","explained_count":"The change explains 3 tickets: T-410, T-411 and T-412 from Analyst users. T-413 is a password reset and is unrelated.","right_fix":"The right fix is restoring view_reports to the Analyst role only. Admin access over-grants, and a template rollback risks undoing unrelated changes.","customer_update":"A stronger update acknowledges the role change plainly, names view_reports as the permission being restored, keeps the fix scoped, and gives a restore time."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"permission-failure","roleKey":"technical_support_engineer","title":"The Permission Failure","tagline":"Three users lost their reports overnight, and one change explains it.","mission":"Four tickets landed this morning and three of them mention reports. A role template changed on Tuesday. Work out what the change did, quantify which tickets it explains, and write the customer update.","companyName":"Fernbrook Software (your employer)","durationMinutes":5,"resources":[{"id":"role_diff","title":"Role template change","kind":"markdown","content":"## Change applied Tuesday 09:00\n\nRole: **Analyst**\n\n| | Permissions |\n| --- | --- |\n| Before | view_reports, export_data |\n| After | export_data |\n\nThe permission `view_reports` was removed from the Analyst role. No other roles were changed."},{"id":"tickets","title":"Open tickets","kind":"table","content":"| Ticket | User | Role | Report |\n| --- | --- | --- | --- |\n| T-410 | Priya Shah | Analyst | Reports tab says access denied |\n| T-411 | Colin Marsh | Analyst | All my saved reports disappeared this morning |\n| T-412 | Ella Burke | Analyst | Cannot open the weekly sales report |\n| T-413 | Sam Trent | Manager | Forgot my password, need a reset |"}],"stakeholders":[{"id":"marcus","name":"Marcus Lee","role":"IT Administrator","blurb":"Made the Tuesday template change. Slightly embarrassed.","knowledge":["He meant to remove view_reports from the Contractor role and applied the change to Analyst by mistake.","Only the Analyst role changed; restoring the permission takes a few minutes."],"withholds":["Will not decide the customer messaging."],"responseRules":[{"id":"rel_change","priority":3,"anyKeywords":["template","tuesday","view_reports","removed","why","diff","who changed"],"reply":"That change was mine. I meant to remove view_reports from the Contractor role and applied it to Analyst by mistake. I can put it back in a few minutes."},{"id":"rel_scope","priority":2,"anyKeywords":["analyst","affected","which users","other roles","scope","manager"],"reply":"Only the Analyst role changed. Managers and Contractors are untouched, so anything outside Analyst is a different issue."}],"fallbackReply":"Tell me which role or permission you are looking at and I can check the change history for you."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why did these users lose report access?","options":["Tuesday''s template change removed view_reports from the Analyst role","The reports service is down","The users'' accounts were deactivated","A password policy change locked users out"],"points":30,"answer":["Tuesday''s template change removed view_reports from the Analyst role"],"competencyKey":"access_diagnosis","expectedEvidence":"The diff shows view_reports was removed from the Analyst role on Tuesday, and the three report tickets all come from Analyst-role users."},{"id":"explained_count","kind":"number","prompt":"How many of the 4 tickets does the template change explain?","helpText":"Count tickets caused by the removed permission.","points":20,"answer":[3,0],"competencyKey":"impact_quantification","expectedEvidence":"T-410, T-411 and T-412 are Analyst-role users blocked from reports. T-413 is a Manager''s password reset and is unrelated. 3 tickets."},{"id":"right_fix","kind":"single_select","prompt":"What is the right fix?","options":["Restore view_reports to the Analyst role only","Give the affected users admin access so they are never blocked again","Recreate the affected user accounts","Roll back every role template to last month''s version"],"points":15,"answer":["Restore view_reports to the Analyst role only"],"competencyKey":"remediation_judgment","expectedEvidence":"The change removed one permission from one role, so the fix restores exactly that. Admin access grants far more than the users had before, and a full rollback risks undoing unrelated changes."},{"id":"customer_update","kind":"text","prompt":"Write the update you would send the affected users.","helpText":"Max 400 characters. Own the cause, say exactly what is being restored, and when access returns.","maxChars":400,"points":25,"concepts":[{"id":"own_cause","label":"Acknowledges the cause plainly","keywords":["role change","template","our change","permission was removed","on our side","we removed"]},{"id":"specific_permission","label":"States the specific permission being restored","keywords":["view_reports","report permission","view reports"]},{"id":"scoped_fix","label":"Avoids granting broad admin access","keywords":["analyst role","only","scoped","not admin","without admin","exactly what"]},{"id":"when_restored","label":"Confirms when access returns","keywords":["restored","within","shortly","today","back","few minutes"]}],"competencyKey":"customer_communication","expectedEvidence":"A role template change on our side removed the view_reports permission from the Analyst role. We are restoring that permission to the Analyst role only, nothing broader. Your report access will be back within the hour, and we will confirm once it is live."}],"competencies":[{"key":"access_diagnosis","label":"Access diagnosis"},{"key":"impact_quantification","label":"Impact quantification"},{"key":"remediation_judgment","label":"Remediation judgment"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Connected the report tickets to the role template diff instead of chasing a service outage.","explained_count":"Correctly separated the tickets the change explains from the unrelated one.","right_fix":"Chose the narrow fix that restores exactly what was lost, without over-granting.","customer_update":"The update owns the cause, names the specific permission, and commits to a restore time."},"improvementTemplates":{"root_cause":"The diff shows view_reports was removed from the Analyst role on Tuesday. All three report tickets come from Analyst users, which points at that change.","explained_count":"The change explains 3 tickets: T-410, T-411 and T-412 from Analyst users. T-413 is a password reset and is unrelated.","right_fix":"The right fix is restoring view_reports to the Analyst role only. Admin access over-grants, and a template rollback risks undoing unrelated changes.","customer_update":"A stronger update acknowledges the role change plainly, names view_reports as the permission being restored, keeps the fix scoped, and gives a restore time."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'duplicate-webhooks';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('duplicate-webhooks', 'technical_support_engineer', 'Duplicate Webhooks', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'technical_support_engineer', title = 'Duplicate Webhooks', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"duplicate-webhooks","roleKey":"technical_support_engineer","title":"Duplicate Webhooks","tagline":"The same order keeps arriving, and nobody is checking the event id.","mission":"A customer says one order appears three times in their warehouse system. The delivery log shows what our platform sent and when. Explain what happened, quantify it, and recommend a fix that makes retries safe.","companyName":"Cartwheel Commerce (your employer)","durationMinutes":5,"resources":[{"id":"delivery_log","title":"Webhook delivery log","kind":"markdown","content":"```\n15:04:10 deliver event=evt_581 type=order.created attempt=1 response=503\n15:06:10 deliver event=evt_581 type=order.created attempt=2 response=503\n15:10:10 deliver event=evt_581 type=order.created attempt=3 response=200\n15:12:44 deliver event=evt_582 type=order.created attempt=1 response=200\n```\n\n**Retry policy:** any non-2xx response is retried with backoff, up to 4 attempts. Every attempt carries the same event id."},{"id":"customer_report","title":"Customer report","kind":"markdown","content":"From Renee Park, developer at Ostwald Retail:\n\n\"Order 4417 shows up three times in our warehouse system. Our endpoint was slow during a database migration between 15:00 and 15:09. It saved each order before returning an error. We do not check event ids today.\""}],"stakeholders":[{"id":"renee","name":"Renee Park","role":"Developer, Ostwald Retail (customer)","blurb":"Built the receiving endpoint. Wants the duplicates gone.","knowledge":["Their endpoint saved each order before timing out and returning a 503 during the migration.","They store the event id from the payload but never check whether they have already processed it."],"withholds":["Does not know how the platform''s retry policy works."],"responseRules":[{"id":"rel_endpoint","priority":3,"anyKeywords":["503","error","fail","endpoint","migration","slow","timed out"],"reply":"Our endpoint was mid-migration between 15:00 and 15:09. It saved each order first, then timed out and returned a 503. So the order got created even when we sent you an error."},{"id":"rel_dedup","priority":2,"anyKeywords":["event id","duplicate","dedup","idempot","same event","already processed"],"reply":"We store the event id from the payload but we never check whether we have seen it before. If that is the fix, it is a small change on our side."},{"id":"rel_scope","priority":2,"anyKeywords":["how many","other orders","other events","just this","evt_582","scope"],"reply":"Order 4417 is the only one we have seen tripled. Everything after 15:10 looks normal on our side."}],"fallbackReply":"Happy to check anything in our system. What exactly do you want me to look up?"}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why does the customer see the same order three times?","options":["Failed deliveries were retried, and the endpoint processed the same event again on each attempt","The platform generated three separate order events for one order","The warehouse system invented duplicate orders on its own","The webhook payload was corrupted in transit"],"points":30,"answer":["Failed deliveries were retried, and the endpoint processed the same event again on each attempt"],"competencyKey":"integration_diagnosis","expectedEvidence":"The log shows one event, evt_581, delivered three times after two 503 responses triggered retries. The endpoint saved the order on every attempt because it never checks event ids."},{"id":"delivery_count","kind":"number","prompt":"How many times was evt_581 delivered in total?","points":20,"answer":[3,0],"competencyKey":"log_analysis","expectedEvidence":"The log shows attempts 1, 2 and 3 for evt_581, at 15:04, 15:06 and 15:10. 3 deliveries."},{"id":"durable_fix","kind":"single_select","prompt":"What is the durable fix?","options":["The receiver deduplicates incoming events by event id, so retries become safe","Turn off retries for this customer","Slow down all webhook deliveries platform-wide","Ask the customer to avoid database migrations during business hours"],"points":15,"answer":["The receiver deduplicates incoming events by event id, so retries become safe"],"competencyKey":"durable_fix_judgment","expectedEvidence":"Every attempt carries the same event id, so checking it before processing makes retries harmless. Turning off retries trades duplicates for lost events."},{"id":"customer_reply","kind":"text","prompt":"Write your reply to Renee.","helpText":"Max 400 characters. Explain the behavior, recommend the fix, and help her clean up.","maxChars":400,"points":25,"concepts":[{"id":"retries_expected","label":"Explains that retries are expected on failures","keywords":["retry","retries","non-2xx","by design","expected","error response"]},{"id":"dedup_by_id","label":"Recommends deduplication by event id","keywords":["event id","dedup","idempot","same id","already processed","evt_581"]},{"id":"offer_log","label":"Offers the delivery log","keywords":["delivery log","log","attempts","timestamps","share the"]},{"id":"safe_cleanup","label":"Describes safe cleanup of the duplicates","keywords":["clean","remove the duplicate","delete the extra","keep one","reconcile"]}],"competencyKey":"customer_communication","expectedEvidence":"Your endpoint returned 503 twice, and we retry any non-2xx response, so evt_581 was delivered three times with the same event id. Checking the event id before processing makes retries safe. I have attached the delivery log with all three attempts. For cleanup, keep the first order 4417 record and remove the two duplicates."}],"competencies":[{"key":"integration_diagnosis","label":"Integration diagnosis"},{"key":"log_analysis","label":"Log analysis"},{"key":"durable_fix_judgment","label":"Durable fix judgment"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Explained the duplicates as retry redelivery plus a receiver that never checks event ids.","delivery_count":"Read the delivery count straight from the log.","durable_fix":"Recommended idempotent processing instead of weakening the retry system.","customer_reply":"The reply explains the behavior, gives the customer a concrete fix, and helps with cleanup."},"improvementTemplates":{"root_cause":"The log shows evt_581 delivered three times after two 503s triggered retries. The endpoint saved the order each time because it never checks event ids.","delivery_count":"evt_581 was delivered 3 times: attempts at 15:04, 15:06 and 15:10.","durable_fix":"The durable fix is deduplication by event id on the receiver. Turning off retries would trade duplicates for silently lost events.","customer_reply":"A stronger reply explains that retries on failures are expected, recommends dedup by event id, offers the delivery log, and describes how to remove the duplicates safely."}}'::jsonb then
