do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'one-customer-or-everyone';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('one-customer-or-everyone', 'technical_support_engineer', 'One Customer or Everyone', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'technical_support_engineer', title = 'One Customer or Everyone', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
