    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"one-customer-or-everyone","roleKey":"technical_support_engineer","title":"One Customer or Everyone","tagline":"One customer is down, every dashboard is green, and both are telling the truth.","mission":"Kestrel Freight says nobody at their office can reach the platform since this morning. Your metrics look normal. Decide whether this is a platform problem or an account problem, choose the diagnostics that settle it, and write the next-steps message.","companyName":"Verdant Systems (your employer)","durationMinutes":5,"resources":[{"id":"platform_status","title":"Platform health","kind":"table","content":"| Metric | Value | State |\n| --- | --- | --- |\n| API error rate | 0.1% | Normal |\n| API p95 latency | 180ms | Normal |\n| us-east region | Healthy | Green |\n| us-west region | Healthy | Green |\n| eu-central region | Healthy | Green |\n| Logins in the last hour | 12,400 | Normal |"},{"id":"account_note","title":"Kestrel Freight account notes","kind":"markdown","content":"## Security settings\n\nIP allowlist: **ON**. Only listed IPs can reach the API and the app.\n\n## Change history\n\nAllowlist entries were edited yesterday at 17:40 by user `kestrel-admin`.\n\n## Support note from their IT\n\nThe office moved to a new building and a new network provider this week.\n\n## Their report\n\n\"Every request from our office is refused since this morning. Your status page says all good, which cannot be right.\""}],"stakeholders":[{"id":"owen","name":"Owen Delaney","role":"IT Manager, Kestrel Freight (customer)","blurb":"Frustrated but cooperative. Can check things on their side.","knowledge":["The office switched network providers on Monday, which changed their outbound IP.","A contractor edited the allowlist yesterday evening and removed entries he called stale."],"withholds":["Does not know what the platform metrics show."],"responseRules":[{"id":"rel_network","priority":3,"anyKeywords":["network","moved","office","provider","isp","new ip","outbound","egress"],"reply":"We moved buildings over the weekend and switched network providers on Monday. I can read our current outbound IP off the router if you need it."},{"id":"rel_allowlist","priority":3,"anyKeywords":["allowlist","allow list","ip list","firewall","changed","yesterday","17:40","security setting"],"reply":"A contractor tidied our security settings yesterday evening and removed entries he called stale. I did not review what he took out."},{"id":"rel_scope","priority":2,"anyKeywords":["everyone","all users","home","remote","vpn","other locations"],"reply":"It is only the office. Two people working from home this morning got in fine."}],"fallbackReply":"I can check anything on our side. Tell me exactly what you need and I will get it."}],"questions":[{"id":"likely_cause","kind":"single_select","prompt":"What is the most likely cause?","options":["An account-specific configuration issue, most likely the IP allowlist blocking their new network","A platform-wide outage the status page has not caught yet","Their user passwords all expired at once","A regional failure in us-east"],"points":30,"answer":["An account-specific configuration issue, most likely the IP allowlist blocking their new network"],"competencyKey":"scope_triage","expectedEvidence":"Every platform metric is normal and 12,400 logins succeeded in the last hour. Their allowlist was edited yesterday and their office changed networks this week, so their new IP is likely not on the list."},{"id":"what_not_to_do","kind":"single_select","prompt":"Which action should you avoid right now?","options":["Declare a platform outage and post a public incident","Check request logs for their account","Ask their IT for the office''s current outbound IP","Review the allowlist change history"],"points":15,"answer":["Declare a platform outage and post a public incident"],"competencyKey":"incident_judgment","expectedEvidence":"The metrics show a healthy platform with thousands of successful logins. Declaring an outage would be false and would alarm every other customer."},{"id":"useful_diagnostics","kind":"multi_select","prompt":"Which diagnostics would help most?","options":["Request logs for the Kestrel Freight account","The office''s current outbound IP address","The allowlist change history from yesterday","A restart of the us-east region","A survey asking other customers if they see errors"],"points":20,"answer":["Request logs for the Kestrel Freight account","The office''s current outbound IP address","The allowlist change history from yesterday"],"competencyKey":"diagnostic_planning","expectedEvidence":"Their request logs show whether traffic is being rejected, their current IP shows what should be on the list, and the change history shows what the edit removed. Restarting a healthy region and surveying customers add nothing."},{"id":"next_steps_message","kind":"text","prompt":"Write the next-steps message to the customer.","helpText":"Max 400 characters. Be honest about platform health without dismissing them, and say what you need from them.","maxChars":400,"points":25,"concepts":[{"id":"healthy_not_dismissive","label":"Confirms the platform is healthy without dismissing them","keywords":["healthy","no outage","platform is up","taking this seriously","normal","other customers are"]},{"id":"point_to_allowlist","label":"Points to the allowlist change","keywords":["allowlist","allow list","ip list","changed yesterday","17:40"]},{"id":"ask_current_ip","label":"Asks for their current IP","keywords":["current ip","outbound ip","egress","your ip","send us the ip","new network"]},{"id":"commit_followup","label":"Commits to a follow-up","keywords":["follow up","update you","within","get back","as soon as"]}],"competencyKey":"customer_communication","expectedEvidence":"Our platform is healthy right now, but we are taking your report seriously. Your account''s IP allowlist was edited yesterday at 17:40, and your office moved networks this week, so your new address may not be on the list. Please send your office''s current outbound IP. I will check your request logs and follow up within the hour."}],"competencies":[{"key":"scope_triage","label":"Scope triage"},{"key":"incident_judgment","label":"Incident judgment"},{"key":"diagnostic_planning","label":"Diagnostic planning"},{"key":"customer_communication","label":"Customer communication"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"likely_cause":"Weighed healthy platform metrics against the account''s recent changes and landed on the allowlist.","what_not_to_do":"Avoided declaring a false outage while the evidence pointed at one account.","useful_diagnostics":"Picked the three diagnostics that actually settle the question.","next_steps_message":"The message is honest about platform health, specific about the likely cause, and asks for exactly what is needed."},"improvementTemplates":{"likely_cause":"With every metric normal and 12,400 successful logins, a platform outage does not fit. The allowlist edit plus the office network move point at account configuration.","what_not_to_do":"Declaring a platform outage is the move to avoid. The platform is demonstrably healthy, and a false incident alarms every other customer.","useful_diagnostics":"The useful diagnostics are the account''s request logs, their current outbound IP, and the allowlist change history. Restarting healthy regions adds nothing.","next_steps_message":"A stronger message confirms the platform is healthy without dismissing the customer, points to the allowlist edit, asks for their current IP, and commits to a follow-up time."}}'::jsonb then
