do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'executive-queue';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('executive-queue', 'business_systems_analyst', 'The Executive Queue', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'business_systems_analyst', title = 'The Executive Queue', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"executive-queue","roleKey":"business_systems_analyst","title":"The Executive Queue","tagline":"Routine $80 purchases are landing on the CFO''s desk. The system isn''t broken.","mission":"Since a policy update, ordinary purchases are routing to executives for approval and teams have started bypassing the system. Find the rule interaction causing it, quantify the impact and recommend a fix that survives compliance review.","companyName":"Ridgeline Manufacturing","durationMinutes":5,"resources":[{"id":"rules","title":"Approval rules (evaluated top-down)","kind":"table","content":"| Rule | Condition | Routes to |\n| --- | --- | --- |\n| R0 (new) | vendor_status ≠ ''approved'' | Executive |\n| R1 | amount < $500 | Auto-approve |\n| R2 | $500 – $5,000 | Manager |\n| R3 | > $5,000 | Director |"},{"id":"purchases","title":"Recent purchase orders","kind":"table","content":"| PO | Vendor | vendor_status | Amount | Routed to |\n| --- | --- | --- | ---: | --- |\n| PO-501 | Apex Supply | pending_verification | $80 | Executive |\n| PO-502 | Corewood | approved | $340 | Auto-approved |\n| PO-503 | Apex Supply | pending_verification | $1,200 | Executive |\n| PO-504 | Danner Tools | pending_verification | $95 | Executive |\n| PO-505 | Veritas Labs | approved | $7,800 | Director |\n| PO-506 | Mistral Parts | pending_verification | $2,300 | Executive |"},{"id":"systems_note","title":"Systems note","kind":"markdown","content":"## Vendor master migration\n\nLast month''s vendor migration created records with `vendor_status = ''pending_verification''`. Status changes to `''approved''` only **after a vendor''s first completed purchase order** in the new system.\n\n## Policy update\n\nThe new policy requires executive review for purchases from **new vendors**. It was implemented as rule R0, evaluated before all other rules."}],"stakeholders":[{"id":"farah","name":"Farah Idris","role":"Compliance Officer","blurb":"Wrote the new-vendor policy. Guards the audit trail.","knowledge":["The policy intent was genuinely new vendor relationships, not migrated vendors awaiting their first PO.","Any fix must preserve the audit trail; blanket auto-approval is unacceptable."],"withholds":["Will not design the system fix."],"responseRules":[{"id":"rel_intent","priority":3,"anyKeywords":["intent","policy mean","new vendor","meant","purpose","why the rule","definition"],"reply":"The policy meant genuinely new vendor relationships: companies we''ve never bought from. Vendors that came over in the migration are not new; they''re just waiting on a status backfill."},{"id":"rel_audit","priority":2,"anyKeywords":["audit","compliance","bypass","auto-approve","auto approve","p-card","constraint"],"reply":"Whatever you propose must keep the audit trail intact. Teams bypassing with p-cards is exactly what the auditors flagged last year, so blanket auto-approval is off the table."}],"fallbackReply":"My concern is compliance, not system mechanics. If you can show the fix preserves review for genuinely new vendors, I''ll support it."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why are ordinary purchases routing to executives?","options":["Rule R0 fires first, and migrated vendors still have vendor_status ''pending_verification''","The purchase amounts are being read incorrectly","Executives added themselves to every approval chain","The policy explicitly requires executive review for all purchases"],"points":30,"answer":["Rule R0 fires first, and migrated vendors still have vendor_status ''pending_verification''"],"competencyKey":"root_cause_analysis","expectedEvidence":"R0 is evaluated before the amount rules, and the migration left vendors as ''pending_verification'' until their first completed PO, so routine re-orders match R0 and route to executives."},{"id":"impacted_count","kind":"number","prompt":"How many of the 6 sample POs under $5,000 were wrongly routed to an executive?","points":20,"answer":[4,0.5],"competencyKey":"process_analysis","expectedEvidence":"PO-501 ($80), PO-503 ($1,200), PO-504 ($95) and PO-506 ($2,300), all under $5,000 from migrated vendors, were routed to executives."},{"id":"best_fix","kind":"single_select","prompt":"Which fix best matches the policy intent?","options":["Backfill ''approved'' status for migrated vendors and define ''new vendor'' precisely in R0","Delete rule R0 entirely","Auto-approve everything under $5,000 regardless of vendor","Raise the executive threshold to $50,000"],"points":15,"answer":["Backfill ''approved'' status for migrated vendors and define ''new vendor'' precisely in R0"],"competencyKey":"systems_judgment","expectedEvidence":"The system is doing what R0 says; the data and the definition are what''s wrong. Backfilling migrated vendors and tightening the R0 definition preserves review for genuinely new vendors."},{"id":"stakeholder_summary","kind":"text","prompt":"Summarize the situation and your recommendation for the stakeholders.","helpText":"Max 400 characters. Separate what the system is doing from what the policy intended.","maxChars":400,"points":25,"concepts":[{"id":"system_vs_policy","label":"Separates system behavior from policy intent","keywords":["as configured","working as","rule says","intent","policy meant","not a bug","doing exactly"]},{"id":"quantify","label":"Quantifies the impact","keywords":["4","four","two thirds","most","of the 6","routine purchases"]},{"id":"fix_with_audit","label":"Proposes the fix while preserving compliance review","keywords":["backfill","definition","genuinely new","audit","preserve","still review","keep executive review"]}],"competencyKey":"stakeholder_summary","expectedEvidence":"The system is doing exactly what R0 says. The migration left most vendors ''pending_verification'', so routine re-orders route to executives (4 of 6 recent POs). Recommend backfilling migrated vendor statuses and defining ''new vendor'' precisely, keeping executive review for genuinely new relationships and the full audit trail."}],"competencies":[{"key":"root_cause_analysis","label":"Root-cause analysis"},{"key":"process_analysis","label":"Process analysis"},{"key":"systems_judgment","label":"Systems judgment"},{"key":"stakeholder_summary","label":"Stakeholder summary"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Traced the routing problem to the rule order and the unmigrated vendor statuses, not a system bug.","impacted_count":"Quantified the impact precisely from the purchase records.","best_fix":"Chose a fix that matches policy intent while preserving review for genuinely new vendors.","stakeholder_summary":"The summary cleanly separates system behavior from policy intent."},"improvementTemplates":{"root_cause":"The cause is rule interaction: R0 fires before the amount rules, and migrated vendors still carry ''pending_verification'' status.","impacted_count":"4 of the 6 sample POs (PO-501, PO-503, PO-504, PO-506) were under $5,000 and wrongly routed to executives.","best_fix":"The fix matching policy intent is backfilling migrated vendor statuses and precisely defining ''new vendor'' in R0. Deleting R0 or blanket auto-approval would fail compliance.","stakeholder_summary":"A stronger summary states the system is working as configured, quantifies the impact, and proposes the backfill + definition fix while keeping the audit trail."}}'::jsonb then
