do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'invoice-routing';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('invoice-routing', 'business_systems_analyst', 'Invoice Routing', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'business_systems_analyst', title = 'Invoice Routing', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"invoice-routing","roleKey":"business_systems_analyst","title":"Invoice Routing","tagline":"Five invoices failed because a vendor cannot spell its own name the same way twice.","mission":"Invoices route to approvers by matching the vendor name printed on the invoice. Five failed this week and sit unpaid. Find the design flaw, quantify it, and lay out a migration that fixes routing without losing the audit trail.","companyName":"Millbrook Foods","durationMinutes":5,"resources":[{"id":"failures","title":"Routing failures this week","kind":"table","content":"| Invoice | Vendor name on invoice | vendor_id in master | Amount | Status |\n| --- | --- | --- | ---: | --- |\n| INV-1088 | J&J Supplies | V-201 | $2,140 | Failed to route |\n| INV-1091 | J and J Supplies | V-201 | $860 | Failed to route |\n| INV-1094 | JJ Supplies Inc | V-201 | $1,375 | Failed to route |\n| INV-1096 | Nortec Ltd. | V-318 | $540 | Failed to route |\n| INV-1099 | Brightline Paper Co | V-442 | $3,200 | Failed to route |"},{"id":"routing_rule","title":"Current routing rule","kind":"markdown","content":"## How routing works today\n\nAn incoming invoice is routed to an approver by **exact match** on the vendor name printed on the invoice against the canonical name in the vendor master. Any invoice with no exact match lands on a weekly failure report and waits.\n\n## Vendor master (relevant rows)\n\n| vendor_id | Canonical name |\n| --- | --- |\n| V-201 | J&J Supplies LLC |\n| V-318 | Nortec Limited |\n| V-442 | Brightline Paper Company |\n\nEvery invoice already carries a `vendor_id`, matched upstream by the procurement system when the purchase order is created."}],"stakeholders":[{"id":"gloria","name":"Gloria Sanders","role":"Accounts Payable Manager","blurb":"Owns the failure report. Fields the calls from unpaid vendors.","knowledge":["The vendor_id comes from procurement at purchase order time and is reliable; the printed names vary constantly.","Auditors require a record of why each invoice routed where it did."],"withholds":["Will not design the new routing logic."],"responseRules":[{"id":"rel_vendor_id","priority":3,"anyKeywords":["vendor_id","vendor id","v-201","master","canonical","procurement","reliable"],"reply":"The vendor_id comes from procurement when the purchase order is cut, and it is reliable. The names are whatever the vendor''s billing system prints that week."},{"id":"rel_audit","priority":2,"anyKeywords":["audit","trail","record","compliance","history","why it routed"],"reply":"Audit asks us to show why each invoice routed where it did. Whatever you change, that record has to survive."},{"id":"rel_backlog","priority":2,"anyKeywords":["failed","backlog","unpaid","late","reprocess","waiting","five invoices"],"reply":"The five on the failure report are sitting unpaid, and two vendors have already called. I need those cleared as part of any fix, not left behind."}],"fallbackReply":"I know the payables side cold. Ask me about the invoices, the vendors, or what audit expects."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why do these invoices fail to route?","options":["Routing matches on vendor names, which vary between invoices, instead of the stable vendor_id","The vendor master is missing these vendors","The approvers are rejecting the invoices","The invoice amounts exceed routing limits"],"points":30,"answer":["Routing matches on vendor names, which vary between invoices, instead of the stable vendor_id"],"competencyKey":"process_diagnosis","expectedEvidence":"All five failed invoices carry a valid vendor_id, but none of the printed names exactly match the canonical names. The match key is unstable; the id is not."},{"id":"v201_count","kind":"number","prompt":"How many of the failed invoices belong to vendor V-201?","points":20,"answer":[3,0],"competencyKey":"data_quantification","expectedEvidence":"INV-1088, INV-1091 and INV-1094 all map to V-201 under three different printed names. 3 invoices."},{"id":"best_fix","kind":"single_select","prompt":"What is the right fix?","options":["Route by vendor_id, with an exception queue for invoices that cannot be matched","Ask vendors to print their canonical name exactly on every invoice","Add every name variation to the vendor master as it appears","Route all failed invoices to one senior approver"],"points":15,"answer":["Route by vendor_id, with an exception queue for invoices that cannot be matched"],"competencyKey":"solution_design","expectedEvidence":"The vendor_id is already on every invoice and is reliable, so it is the right match key. An exception queue handles the rare unmatched case without silent failure. Chasing name variations never ends."},{"id":"migration_plan","kind":"text","prompt":"Describe your migration approach.","helpText":"Max 400 characters. Cover the new matching, exceptions, the audit record, and the failed invoices.","maxChars":400,"points":25,"concepts":[{"id":"switch_to_id","label":"Switches matching to vendor_id","keywords":["vendor_id","vendor id","match on id","route by id","stable id"]},{"id":"exception_queue","label":"Keeps an exception queue for unmatched invoices","keywords":["exception queue","exception","unmatched","manual review","queue"]},{"id":"audit_trail","label":"Preserves an audit trail of routing decisions","keywords":["audit","trail","record","why it routed","log each","history"]},{"id":"reprocess_failed","label":"Backfills or reprocesses the failed invoices","keywords":["reprocess","backfill","failed invoices","re-run","rerun","clear the backlog"]}],"competencyKey":"migration_planning","expectedEvidence":"Switch matching from printed names to vendor_id, which every invoice already carries. Invoices with no id match go to an exception queue for manual review instead of failing silently. Record each routing decision so the audit trail survives. Then reprocess the five failed invoices under the new rule so the backlog clears."}],"competencies":[{"key":"process_diagnosis","label":"Process diagnosis"},{"key":"data_quantification","label":"Data quantification"},{"key":"solution_design","label":"Solution design"},{"key":"migration_planning","label":"Migration planning"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Identified the unstable match key as the design flaw, not the vendors or the data.","v201_count":"Counted the V-201 invoices correctly across three name variations.","best_fix":"Chose the stable identifier with an exception path instead of chasing name variations.","migration_plan":"The migration covers matching, exceptions, the audit trail, and the existing backlog."},"improvementTemplates":{"root_cause":"Every failed invoice has a valid vendor_id but a printed name that does not exactly match the master. The flaw is matching on names instead of the stable id.","v201_count":"3 failed invoices belong to V-201: INV-1088, INV-1091 and INV-1094, each with a different printed name.","best_fix":"The right fix routes by vendor_id with an exception queue for unmatched invoices. Adding name variations to the master is a treadmill that never ends.","migration_plan":"A stronger plan switches matching to vendor_id, keeps an exception queue, preserves the audit record of every routing decision, and reprocesses the five failed invoices."}}'::jsonb then
    insert into public.sim_template_versions (template_id, version, content, published_at)
    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"invoice-routing","roleKey":"business_systems_analyst","title":"Invoice Routing","tagline":"Five invoices failed because a vendor cannot spell its own name the same way twice.","mission":"Invoices route to approvers by matching the vendor name printed on the invoice. Five failed this week and sit unpaid. Find the design flaw, quantify it, and lay out a migration that fixes routing without losing the audit trail.","companyName":"Millbrook Foods","durationMinutes":5,"resources":[{"id":"failures","title":"Routing failures this week","kind":"table","content":"| Invoice | Vendor name on invoice | vendor_id in master | Amount | Status |\n| --- | --- | --- | ---: | --- |\n| INV-1088 | J&J Supplies | V-201 | $2,140 | Failed to route |\n| INV-1091 | J and J Supplies | V-201 | $860 | Failed to route |\n| INV-1094 | JJ Supplies Inc | V-201 | $1,375 | Failed to route |\n| INV-1096 | Nortec Ltd. | V-318 | $540 | Failed to route |\n| INV-1099 | Brightline Paper Co | V-442 | $3,200 | Failed to route |"},{"id":"routing_rule","title":"Current routing rule","kind":"markdown","content":"## How routing works today\n\nAn incoming invoice is routed to an approver by **exact match** on the vendor name printed on the invoice against the canonical name in the vendor master. Any invoice with no exact match lands on a weekly failure report and waits.\n\n## Vendor master (relevant rows)\n\n| vendor_id | Canonical name |\n| --- | --- |\n| V-201 | J&J Supplies LLC |\n| V-318 | Nortec Limited |\n| V-442 | Brightline Paper Company |\n\nEvery invoice already carries a `vendor_id`, matched upstream by the procurement system when the purchase order is created."}],"stakeholders":[{"id":"gloria","name":"Gloria Sanders","role":"Accounts Payable Manager","blurb":"Owns the failure report. Fields the calls from unpaid vendors.","knowledge":["The vendor_id comes from procurement at purchase order time and is reliable; the printed names vary constantly.","Auditors require a record of why each invoice routed where it did."],"withholds":["Will not design the new routing logic."],"responseRules":[{"id":"rel_vendor_id","priority":3,"anyKeywords":["vendor_id","vendor id","v-201","master","canonical","procurement","reliable"],"reply":"The vendor_id comes from procurement when the purchase order is cut, and it is reliable. The names are whatever the vendor''s billing system prints that week."},{"id":"rel_audit","priority":2,"anyKeywords":["audit","trail","record","compliance","history","why it routed"],"reply":"Audit asks us to show why each invoice routed where it did. Whatever you change, that record has to survive."},{"id":"rel_backlog","priority":2,"anyKeywords":["failed","backlog","unpaid","late","reprocess","waiting","five invoices"],"reply":"The five on the failure report are sitting unpaid, and two vendors have already called. I need those cleared as part of any fix, not left behind."}],"fallbackReply":"I know the payables side cold. Ask me about the invoices, the vendors, or what audit expects."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why do these invoices fail to route?","options":["Routing matches on vendor names, which vary between invoices, instead of the stable vendor_id","The vendor master is missing these vendors","The approvers are rejecting the invoices","The invoice amounts exceed routing limits"],"points":30,"answer":["Routing matches on vendor names, which vary between invoices, instead of the stable vendor_id"],"competencyKey":"process_diagnosis","expectedEvidence":"All five failed invoices carry a valid vendor_id, but none of the printed names exactly match the canonical names. The match key is unstable; the id is not."},{"id":"v201_count","kind":"number","prompt":"How many of the failed invoices belong to vendor V-201?","points":20,"answer":[3,0],"competencyKey":"data_quantification","expectedEvidence":"INV-1088, INV-1091 and INV-1094 all map to V-201 under three different printed names. 3 invoices."},{"id":"best_fix","kind":"single_select","prompt":"What is the right fix?","options":["Route by vendor_id, with an exception queue for invoices that cannot be matched","Ask vendors to print their canonical name exactly on every invoice","Add every name variation to the vendor master as it appears","Route all failed invoices to one senior approver"],"points":15,"answer":["Route by vendor_id, with an exception queue for invoices that cannot be matched"],"competencyKey":"solution_design","expectedEvidence":"The vendor_id is already on every invoice and is reliable, so it is the right match key. An exception queue handles the rare unmatched case without silent failure. Chasing name variations never ends."},{"id":"migration_plan","kind":"text","prompt":"Describe your migration approach.","helpText":"Max 400 characters. Cover the new matching, exceptions, the audit record, and the failed invoices.","maxChars":400,"points":25,"concepts":[{"id":"switch_to_id","label":"Switches matching to vendor_id","keywords":["vendor_id","vendor id","match on id","route by id","stable id"]},{"id":"exception_queue","label":"Keeps an exception queue for unmatched invoices","keywords":["exception queue","exception","unmatched","manual review","queue"]},{"id":"audit_trail","label":"Preserves an audit trail of routing decisions","keywords":["audit","trail","record","why it routed","log each","history"]},{"id":"reprocess_failed","label":"Backfills or reprocesses the failed invoices","keywords":["reprocess","backfill","failed invoices","re-run","rerun","clear the backlog"]}],"competencyKey":"migration_planning","expectedEvidence":"Switch matching from printed names to vendor_id, which every invoice already carries. Invoices with no id match go to an exception queue for manual review instead of failing silently. Record each routing decision so the audit trail survives. Then reprocess the five failed invoices under the new rule so the backlog clears."}],"competencies":[{"key":"process_diagnosis","label":"Process diagnosis"},{"key":"data_quantification","label":"Data quantification"},{"key":"solution_design","label":"Solution design"},{"key":"migration_planning","label":"Migration planning"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Identified the unstable match key as the design flaw, not the vendors or the data.","v201_count":"Counted the V-201 invoices correctly across three name variations.","best_fix":"Chose the stable identifier with an exception path instead of chasing name variations.","migration_plan":"The migration covers matching, exceptions, the audit trail, and the existing backlog."},"improvementTemplates":{"root_cause":"Every failed invoice has a valid vendor_id but a printed name that does not exactly match the master. The flaw is matching on names instead of the stable id.","v201_count":"3 failed invoices belong to V-201: INV-1088, INV-1091 and INV-1094, each with a different printed name.","best_fix":"The right fix routes by vendor_id with an exception queue for unmatched invoices. Adding name variations to the master is a treadmill that never ends.","migration_plan":"A stronger plan switches matching to vendor_id, keeps an exception queue, preserves the audit record of every routing decision, and reprocesses the five failed invoices."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
