do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'access-provisioning';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('access-provisioning', 'business_systems_analyst', 'Access Provisioning', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'business_systems_analyst', title = 'Access Provisioning', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"access-provisioning","roleKey":"business_systems_analyst","title":"Access Provisioning","tagline":"Two people left the company and their logins did not.","mission":"A spot check found former employees with working accounts. HR and IT each run their own system, connected by a nightly sync. Find why departures are not turning accounts off, measure the exposure, and recommend the fix.","companyName":"Copperfield Logistics","durationMinutes":5,"resources":[{"id":"hr_table","title":"HR system status","kind":"table","content":"| Employee | Name | HR status | Last day |\n| --- | --- | --- | --- |\n| E-11 | Tara Nguyen | terminated | 2026-07-10 |\n| E-12 | Bo Ellis | active | |\n| E-13 | Ken Watts | terminated | 2026-07-15 |\n| E-14 | Ana Silva | on_leave | |\n| E-15 | Raj Mehta | active | |\n| E-16 | Lucy Ford | active | |"},{"id":"it_table","title":"IT directory access","kind":"table","content":"| Employee | IT account | Access |\n| --- | --- | --- |\n| E-11 | t.nguyen | enabled |\n| E-12 | b.ellis | enabled |\n| E-13 | k.watts | enabled |\n| E-14 | a.silva | enabled |\n| E-15 | r.mehta | enabled |\n| E-16 | l.ford | enabled |"},{"id":"mapping_note","title":"Sync rule note","kind":"markdown","content":"## Nightly sync rule\n\nThe IT directory disables an account only when the HR feed shows status `separated`.\n\n## HR status values\n\nHR uses exactly three values: `active`, `on_leave`, `terminated`. HR has never used `separated`."}],"stakeholders":[{"id":"denise","name":"Denise Alvarez","role":"IT Operations Lead","blurb":"Runs the directory and the nightly sync. Wants a clean fix.","knowledge":["The sync predates the current HR system; the old system sent ''separated'' when someone left, and nobody updated the rule.","Changing the mapping is a small config edit; specific accounts can be disabled manually today."],"withholds":["Will not decide which system is authoritative."],"responseRules":[{"id":"rel_mapping","priority":3,"anyKeywords":["separated","mapping","sync","status value","terminated","rule","config"],"reply":"The sync predates our current HR system. The old one sent ''separated'' when someone left. Nobody updated the rule after the migration. Changing it is a small config edit."},{"id":"rel_disable","priority":2,"anyKeywords":["disable","revoke","e-11","e-13","right now","immediately","manual"],"reply":"I can disable specific accounts manually today if you name them. The sync fix takes care of it going forward."},{"id":"rel_risk","priority":2,"anyKeywords":["risk","security","audit","review","exposure"],"reply":"Security flagged orphaned accounts in last year''s review. If we touch this, they will want a documented access review, not just a quiet fix."}],"fallbackReply":"I run the directory and the sync. Ask me something specific and I can pull it up."}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why do departed employees still have access?","options":["IT disables accounts only on the status ''separated'', a value HR never sends","The nightly sync job has stopped running","HR forgot to record the terminations","IT accounts can only be disabled manually"],"points":30,"answer":["IT disables accounts only on the status ''separated'', a value HR never sends"],"competencyKey":"systems_diagnosis","expectedEvidence":"HR correctly shows E-11 and E-13 as terminated, but the sync only reacts to ''separated'', which HR has never used. The systems disagree on vocabulary, not on facts."},{"id":"exposed_count","kind":"number","prompt":"How many departed employees still have enabled access?","points":20,"answer":[2,0],"competencyKey":"risk_quantification","expectedEvidence":"E-11 (Tara Nguyen) and E-13 (Ken Watts) are terminated in HR and enabled in the IT directory. 2 employees."},{"id":"authoritative_source","kind":"single_select","prompt":"Which system should be the authoritative source for employment status?","options":["The HR system","The IT directory","The department managers, by email","Whichever system was updated most recently"],"points":15,"answer":["The HR system"],"competencyKey":"data_governance","expectedEvidence":"HR records the employment event itself and already shows the correct statuses. The IT directory should follow HR, not the other way around."},{"id":"recommendation","kind":"text","prompt":"Write your recommendation.","helpText":"Max 400 characters. Cover the source of truth, the mapping fix, the immediate cleanup, and how this stays fixed.","maxChars":400,"points":25,"concepts":[{"id":"hr_source_of_truth","label":"Defines HR as the source of truth","keywords":["source of truth","authoritative","hr system","hr status","hr owns"]},{"id":"fix_mapping","label":"Fixes the status mapping","keywords":["mapping","terminated","sync rule","status value","map"]},{"id":"immediate_review","label":"Runs an immediate access review","keywords":["immediate","disable now","access review","today","revoke","right away"]},{"id":"ongoing_reconciliation","label":"Adds ongoing reconciliation between the systems","keywords":["reconcil","recurring","ongoing","regular","compare","monitor"]}],"competencyKey":"written_recommendation","expectedEvidence":"Make the HR system the authoritative source for employment status. Fix the sync mapping so ''terminated'' disables the IT account. Run an immediate access review and disable E-11 and E-13 today. Then add a recurring reconciliation that compares HR status against directory access and flags any mismatch."}],"competencies":[{"key":"systems_diagnosis","label":"Systems diagnosis"},{"key":"risk_quantification","label":"Risk quantification"},{"key":"data_governance","label":"Data governance"},{"key":"written_recommendation","label":"Written recommendation"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Found the vo