do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'crm-handoff';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('crm-handoff', 'business_systems_analyst', 'The CRM Handoff', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'business_systems_analyst', title = 'The CRM Handoff', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"crm-handoff","roleKey":"business_systems_analyst","title":"The CRM Handoff","tagline":"Forty leads went in, twelve came out, and nobody noticed the gap.","mission":"Sales says Marketing sends them nothing. Marketing says they qualified forty leads last month. Both are right. Find where the leads go, measure the loss, and propose a handoff that cannot silently drop leads again.","companyName":"Bluearc Software","durationMinutes":5,"resources":[{"id":"stage_map","title":"Lifecycle stage mapping","kind":"markdown","content":"| Marketing stage | Maps to Sales stage |\n| --- | --- |\n| new | none (marketing only) |\n| engaged | none (marketing only) |\n| qualified | **no mapping defined** |\n\nSales stages are: `prospect`, `opportunity`, `customer`. A lead appears in Sales queues only after it has a Sales stage."},{"id":"funnel_note","title":"Last month''s funnel","kind":"markdown","content":"## Counts\n\n- 40 leads reached Marketing stage `qualified`.\n- 12 of those became Sales opportunities, each created by hand by a rep.\n- 28 have no Sales stage and appear in no Sales queue."}],"stakeholders":[{"id":"hana","name":"Hana Kim","role":"Marketing Operations Manager","blurb":"Runs the marketing side of the CRM. Tired of the blame game.","knowledge":["The ''qualified'' stage was added in March and its Sales mapping was never configured.","The 12 opportunities came from one rep who tracks qualified leads in her own spreadsheet; nobody owns the handoff."],"withholds":["Will not speak for what Sales will agree to."],"responseRules":[{"id":"rel_mapping","priority":3,"anyKeywords":["mapping","qualified","no sales stage","configured","stage","march"],"reply":"We added the ''qualified'' stage in March. Setting up where it lands in Sales was on someone''s list, but I honestly could not tell you whose. It never got configured."},{"id":"rel_manual","priority":2,"anyKeywords":["12","twelve","manual","by hand","rep","opportunit","spreadsheet"],"reply":"One rep keeps her own spreadsheet of qualified leads and creates opportunities by hand. That is where the 12 came from. Nobody else does it."},{"id":"rel_owner","priority":2,"anyKeywords":["own","whose","responsib","who decides","handoff","accountable"],"reply":"Right now nobody owns the handoff. Marketing thinks it ends at ''qualified'' and Sales thinks it starts at ''opportunity''. The gap between those two is unclaimed."}],"fallbackReply":"I can pull anything from the marketing side of the CRM. What do you want to see?"}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why do qualified leads disappear?","options":["The ''qualified'' stage has no mapped Sales stage, so qualified leads never reach a Sales queue","Sales reps are deleting leads they do not want","Marketing is qualifying too many leads","The CRM drops records during nightly maintenance"],"points":30,"answer":["The ''qualified'' stage has no mapped Sales stage, so qualified leads never reach a Sales queue"],"competencyKey":"funnel_diagnosis","expectedEvidence":"The mapping table shows ''qualified'' has no mapped Sales stage, and a lead appears in Sales queues only after it has one. The 12 that made it were created by hand."},{"id":"lost_count","kind":"number","prompt":"How many qualified leads fell through last month?","points":25,"answer":[28,0],"competencyKey":"impact_quantification","expectedEvidence":"40 leads reached ''qualified''. 12 were manually turned into opportunities. 28 have no Sales stage and sit in no queue."},{"id":"handoff_owner","kind":"single_select","prompt":"Who should own the handoff definition?","options":["Marketing and Sales jointly, with one written definition","Marketing alone, since they create the leads","Sales alone, since they work the leads","The CRM vendor''s support team"],"points":15,"answer":["Marketing and Sales jointly, with one written definition"],"competencyKey":"ownership_judgment","expectedEvidence":"The handoff spans both teams, and the gap exists because each side assumes the other owns it. One written definition agreed by both closes that gap."},{"id":"proposal","kind":"text","prompt":"Write your proposal to fix the handoff.","helpText":"Max 400 characters. Cover the mapping, the written definition, ownership, and how you would catch this next time.","maxChars":400,"points":20,"concepts":[{"id":"explicit_mapping","label":"Maps qualified to a Sales stage explicitly","keywords":["map qualified","mapping","map to","prospect","sales stage"]},{"id":"written_criteria","label":"Defines the handoff criteria in writing","keywords":["written","criteria","definition","document","agree on"]},{"id":"assign_ownership","label":"Assigns ownership","keywords":["owner","own the handoff","accountab","responsib","jointly"]},{"id":"monitor_unmapped","label":"Adds monitoring for unmapped leads","keywords":["monitor","alert","unmapped","report on","track","flag"]}],"competencyKey":"process_proposal","expectedEvidence":"Map ''qualified'' explicitly to the Sales stage ''prospect'' so every qualified lead lands in a Sales queue. Write down the handoff criteria and get both teams to agree on the definition. Make Marketing and Sales joint owners of it. Add a weekly report that flags any lead sitting in ''qualified'' with no Sales stage, so the next gap cannot stay invisible."}],"competencies":[{"key":"funnel_diagnosis","label":"Funnel diagnosis"},{"key":"impact_quantification","label":"Impact quantification"},{"key":"ownership_judgment","label":"Ownership judgment"},{"key":"process_proposal","label":"Process proposal"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Located the gap in the stage mapping instead of blaming either team.","lost_count":"Quantified the lost leads directly from the funnel counts.","handoff_owner":"Recognized that a cross-team gap needs joint ownership and one written definition.","proposal":"The proposal fixes the mapping, writes down the definition, assigns owners, and adds monitoring."},"improvementTemplates":{"root_cause":"The mapping table shows ''qualified'' has no mapped Sales stage, so those leads never enter a Sales queue. The 12 that converted were created by hand.","lost_count":"28 leads fell through: 40 reached ''qualified'' and only 12 became opportunities.","handoff_owner":"Joint ownership with one written definition is the answer. The gap exists precisely because each team assumed the other owned the handoff.","proposal":"A stronger proposal maps ''qualified'' to a specific Sales stage, defines the handoff criteria in writing, assigns joint ownership, and monitors for unmapped leads."}}'::jsonb then
