    values (
      t_id,
      coalesce((select max(version) from public.sim_template_versions where template_id = t_id), 0) + 1,
      '{"format":"micro","schemaVersion":1,"slug":"crm-handoff","roleKey":"business_systems_analyst","title":"The CRM Handoff","tagline":"Forty leads went in, twelve came out, and nobody noticed the gap.","mission":"Sales says Marketing sends them nothing. Marketing says they qualified forty leads last month. Both are right. Find where the leads go, measure the loss, and propose a handoff that cannot silently drop leads again.","companyName":"Bluearc Software","durationMinutes":5,"resources":[{"id":"stage_map","title":"Lifecycle stage mapping","kind":"markdown","content":"| Marketing stage | Maps to Sales stage |\n| --- | --- |\n| new | none (marketing only) |\n| engaged | none (marketing only) |\n| qualified | **no mapping defined** |\n\nSales stages are: `prospect`, `opportunity`, `customer`. A lead appears in Sales queues only after it has a Sales stage."},{"id":"funnel_note","title":"Last month''s funnel","kind":"markdown","content":"## Counts\n\n- 40 leads reached Marketing stage `qualified`.\n- 12 of those became Sales opportunities, each created by hand by a rep.\n- 28 have no Sales stage and appear in no Sales queue."}],"stakeholders":[{"id":"hana","name":"Hana Kim","role":"Marketing Operations Manager","blurb":"Runs the marketing side of the CRM. Tired of the blame game.","knowledge":["The ''qualified'' stage was added in March and its Sales mapping was never configured.","The 12 opportunities came from one rep who tracks qualified leads in her own spreadsheet; nobody owns the handoff."],"withholds":["Will not speak for what Sales will agree to."],"responseRules":[{"id":"rel_mapping","priority":3,"anyKeywords":["mapping","qualified","no sales stage","configured","stage","march"],"reply":"We added the ''qualified'' stage in March. Setting up where it lands in Sales was on someone''s list, but I honestly could not tell you whose. It never got configured."},{"id":"rel_manual","priority":2,"anyKeywords":["12","twelve","manual","by hand","rep","opportunit","spreadsheet"],"reply":"One rep keeps her own spreadsheet of qualified leads and creates opportunities by hand. That is where the 12 came from. Nobody else does it."},{"id":"rel_owner","priority":2,"anyKeywords":["own","whose","responsib","who decides","handoff","accountable"],"reply":"Right now nobody owns the handoff. Marketing thinks it ends at ''qualified'' and Sales thinks it starts at ''opportunity''. The gap between those two is unclaimed."}],"fallbackReply":"I can pull anything from the marketing side of the CRM. What do you want to see?"}],"questions":[{"id":"root_cause","kind":"single_select","prompt":"Why do qualified leads disappear?","options":["The ''qualified'' stage has no mapped Sales stage, so qualified leads never reach a Sales queue","Sales reps are deleting leads they do not want","Marketing is qualifying too many leads","The CRM drops records during nightly maintenance"],"points":30,"answer":["The ''qualified'' stage has no mapped Sales stage, so qualified leads never reach a Sales queue"],"competencyKey":"funnel_diagnosis","expectedEvidence":"The mapping table shows ''qualified'' has no mapped Sales stage, and a lead appears in Sales queues only after it has one. The 12 that made it were created by hand."},{"id":"lost_count","kind":"number","prompt":"How many qualified leads fell through last month?","points":25,"answer":[28,0],"competencyKey":"impact_quantification","expectedEvidence":"40 leads reached ''qualified''. 12 were manually turned into opportunities. 28 have no Sales stage and sit in no queue."},{"id":"handoff_owner","kind":"single_select","prompt":"Who should own the handoff definition?","options":["Marketing and Sales jointly, with one written definition","Marketing alone, since they create the leads","Sales alone, since they work the leads","The CRM vendor''s support team"],"points":15,"answer":["Marketing and Sales jointly, with one written definition"],"competencyKey":"ownership_judgment","expectedEvidence":"The handoff spans both teams, and the gap exists because each side assumes the other owns it. One written definition agreed by both closes that gap."},{"id":"proposal","kind":"text","prompt":"Write your proposal to fix the handoff.","helpText":"Max 400 characters. Cover the mapping, the written definition, ownership, and how you would catch this next time.","maxChars":400,"points":20,"concepts":[{"id":"explicit_mapping","label":"Maps qualified to a Sales stage explicitly","keywords":["map qualified","mapping","map to","prospect","sales stage"]},{"id":"written_criteria","label":"Defines the handoff criteria in writing","keywords":["written","criteria","definition","document","agree on"]},{"id":"assign_ownership","label":"Assigns ownership","keywords":["owner","own the handoff","accountab","responsib","jointly"]},{"id":"monitor_unmapped","label":"Adds monitoring for unmapped leads","keywords":["monitor","alert","unmapped","report on","track","flag"]}],"competencyKey":"process_proposal","expectedEvidence":"Map ''qualified'' explicitly to the Sales stage ''prospect'' so every qualified lead lands in a Sales queue. Write down the handoff criteria and get both teams to agree on the definition. Make Marketing and Sales joint owners of it. Add a weekly report that flags any lead sitting in ''qualified'' with no Sales stage, so the next gap cannot stay invisible."}],"competencies":[{"key":"funnel_diagnosis","label":"Funnel diagnosis"},{"key":"impact_quantification","label":"Impact quantification"},{"key":"ownership_judgment","label":"Ownership judgment"},{"key":"process_proposal","label":"Process proposal"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"root_cause":"Located the gap in the stage mapping instead of blaming either team.","lost_count":"Quantified the lost leads directly from the funnel counts.","handoff_owner":"Recognized that a cross-team gap needs joint ownership and one written definition.","proposal":"The proposal fixes the mapping, writes down the definition, assigns owners, and adds monitoring."},"improvementTemplates":{"root_cause":"The mapping table shows ''qualified'' has no mapped Sales stage, so those leads never enter a Sales queue. The 12 that converted were created by hand.","lost_count":"28 leads fell through: 40 reached ''qualified'' and only 12 became opportunities.","handoff_owner":"Joint ownership with one written definition is the answer. The gap exists precisely because each team assumed the other owned the handoff.","proposal":"A stronger proposal maps ''qualified'' to a specific Sales stage, defines the handoff criteria in writing, assigns joint ownership, and monitors for unmapped leads."}}'::jsonb,
      now()
    )
    returning id into v_id;
    update public.sim_templates set current_version_id = v_id where id = t_id;
  end if;
end $$;

do $$
declare
  t_id uuid;
  v_id uuid;
  existing_content jsonb;
begin
  select id into t_id from public.sim_templates where slug = 'change-request';
  if t_id is null then
    insert into public.sim_templates (slug, role_key, title, status)
    values ('change-request', 'business_systems_analyst', 'The Change Request', 'published')
    returning id into t_id;
  else
    update public.sim_templates
      set role_key = 'business_systems_analyst', title = 'The Change Request', status = 'published'
      where id = t_id;
  end if;

  select tv.content into existing_content
    from public.sim_templates t
    join public.sim_template_versions tv on tv.id = t.current_version_id
    where t.id = t_id;

  if existing_content is distinct from '{"format":"micro","schemaVersion":1,"slug":"change-request","roleKey":"business_systems_analyst","title":"The Change Request","tagline":"The stakeholder wants a shortcut that runs straight through a financial control.","mission":"A director wants a workflow exception this week. Her request collides with an approved financial control. Identify the exact conflict, decide the right path, and answer her in a way that keeps both the relationship and the control intact.","companyName":"Halbrook Industries","durationMinutes":5,"resources":[{"id":"request_email","title":"Change request email","kind":"markdown","content":"From: Dana Pruitt, Director of Facilities\nTo: Business Systems\nSubject: Approval exception for Facilities\n\nOur repair purchases keep stalling in secondary approval. I want purchases under $8,000 from the Facilities department to skip secondary approval entirely. Urgent repairs cannot wait two days for a second signature. Please make this change this week."},{"id":"policy_doc","title":"Purchase control PC-7","kind":"markdown","content":"## Control PC-7\n\nAll purchases above $5,000 require secondary approval by a second authorized approver.\n\n- Approved by internal audit in January.\n- Control owner: Finance Controller.\n- Any change to this control requires the control owner''s documented approval."}],"stakeholders":[{"id":"victor","name":"Victor Osei","role":"Finance Controller","blurb":"Owns control PC-7. Reasonable, but guards the threshold.","knowledge":["A documented exception process exists: a short risk memo plus his sign-off, filed for audit, about a week end to end.","The $5,000 threshold came from a fraud case involving split purchases; audit set it in January."],"withholds":["Will not pre-approve anything in chat."],"responseRules":[{"id":"rel_owner","priority":3,"anyKeywords":["control owner","pc-7","pc7","who approves","exception","change the control","process"],"reply":"PC-7 is mine. There is a real exception process: a short risk memo, my sign-off, and it goes in the audit file. It usually takes about a week, not months."},{"id":"rel_threshold","priority":2,"anyKeywords":["5,000","5000","threshold","why","january","audit","fraud"],"reply":"The $5,000 line is not arbitrary. We had a fraud case two years ago involving split purchases just under the old limit. Audit set the current threshold in January."},{"id":"rel_urgency","priority":2,"anyKeywords":["urgent","repair","facilities","emergency","two days","expedite"],"reply":"If Facilities has genuinely urgent repairs, there is an emergency purchase route with after-the-fact review. That might solve Dana''s real problem without touching the control."}],"fallbackReply":"I would rather answer a precise question than guess at what you need. What part of the control are you looking at?"}],"questions":[{"id":"identify_conflict","kind":"single_select","prompt":"What is the conflict in this request?","options":["It removes secondary approval for purchases between $5,000 and $8,000, which control PC-7 requires","It asks for a change to be made this week","Facilities is not allowed to request workflow changes","The $8,000 figure is higher than any real repair cost"],"points":30,"answer":["It removes secondary approval for purchases between $5,000 and $8,000, which control PC-7 requires"],"competencyKey":"policy_analysis","expectedEvidence":"PC-7 requires secondary approval above $5,000. The request skips it under $8,000, so purchases from $5,000 to $8,000 would bypass an audit-approved control."},{"id":"what_not_to_do","kind":"single_select","prompt":"Which response should you avoid?","options":["Implement the exception quietly and hope audit does not notice","Check the request against the written control","Tell Dana exactly where the conflict is","Ask the control owner how exceptions are handled"],"points":25,"answer":["Implement the exception quietly and hope audit does not notice"],"competencyKey":"professional_judgment","expectedEvidence":"Changing an audit-approved control without the owner''s documented approval violates the control''s own change rule and creates audit exposure. Silence is the one option that is never right here."},{"id":"right_path","kind":"single_select","prompt":"What is the right path forward?","options":["Route the request to the Finance Controller, the control owner, for a documented decision","Reject the request and close the ticket","Implement it only for purchases under $5,000, since that avoids the conflict","Escalate to the CEO for a decision"],"points":15,"answer":["Route the request to the Finance Controller, the control owner, for a documented decision"],"competencyKey":"governance_process","expectedEvidence":"The control itself says changes require the control owner''s documented approval. Routing the request there addresses Dana''s need through the process that exists for exactly this case."},{"id":"stakeholder_response","kind":"text","prompt":"Write your response to Dana.","helpText":"Max 400 characters. Name the conflict, keep the door open, and offer a concrete path.","maxChars":400,"points":20,"concepts":[{"id":"name_conflict","label":"Names the specific policy conflict","keywords":["pc-7","5,000","5000","control","requires secondary","conflict"]},{"id":"not_refusal","label":"Does not refuse outright","keywords":["understand","valid","not saying no","want to help","hear you","real problem"]},{"id":"governed_path","label":"Proposes the governed path","keywords":["control owner","finance controller","exception process","formal","governed"]},{"id":"offer_to_raise","label":"Offers to raise it and document the outcome","keywords":["raise it","bring this to","on your behalf","record the outcome","follow up with"]}],"competencyKey":"written_response","expectedEvidence":"I understand the delay on urgent repairs is a real problem. I cannot implement this as asked: control PC-7 requires secondary approval above $5,000, so the request conflicts with it between $5,000 and $8,000. There is an exception process through the Finance Controller, the control owner. I will raise it on your behalf this week and record the outcome either way."}],"competencies":[{"key":"policy_analysis","label":"Policy analysis"},{"key":"professional_judgment","label":"Professional judgment"},{"key":"governance_process","label":"Governance process"},{"key":"written_response","label":"Written response"},{"key":"stakeholder_communication","label":"Stakeholder communication"}],"stakeholderPoints":10,"stakeholderCompetencyKey":"stakeholder_communication","strengthTemplates":{"identify_conflict":"Pinpointed the exact range where the request breaks the control.","what_not_to_do":"Recognized that silently bypassing an audit-approved control is the one unacceptable move.","right_path":"Routed the request to the control owner, which is what the control itself requires.","stakeholder_response":"The response names the conflict, stays constructive, and offers a real path forward."},"improvementTemplates":{"identify_conflict":"PC-7 requires secondary approval above $5,000, and the request skips it under $8,000. The conflict is the $5,000 to $8,000 range.","what_not_to_do":"The move to avoid is implementing the exception silently. The control''s own rules require the owner''s documented approval for any change.","right_path":"The right path routes the request to the Finance Controller for a documented decision. The exception process exists for exactly this case.","stakeholder_response":"A stronger response names the PC-7 conflict precisely, acknowledges the real problem without refusing outright, proposes the governed path, and offers to raise it and document the outcome."}}'::jsonb then
